/**
 * Shared adoption map: durable child session id → its direct parent session id,
 * and whether the parent is live. Used by the stub persistence (to author the
 * resumed child's header) and the stub agents (to set header.parentSession on
 * a cold resume). Seeded by tests that register durable post residents.
 */
const postAdoption = new Map()

// --- stubs --------------------------------------------------------------------

/** Subagent provider stub: continuable-capable, records prepare calls. */
function stubProvider(name) {
  const provider = {
    name,
    capabilities: { outputSchema: true, depthLimit: true, toolFilter: true, persona: true },
    inheritsParentContext: name === 'fork',
    prepareCalls: [],
    async start() {
      throw new Error(`stub provider "${name}": one-shot start is not used in these tests`)
    },
    async prepareContinuable(request) {
      provider.prepareCalls.push(request)
      return { seed: [] }
    }
  }
  return provider
}

/** F10 (spec 004 §7.1) — a minimal GLOBAL stub for a harness capability tool
 * (web_search/read/write/glob/grep/web_fetch/edit). The dsh-tools registry has
 * no native tools in this hermetic composition, so a test that must prove a
 * worker/head INHERITS a global tool registers these on the global plane
 * BEFORE the plugin boots (the head/worker restrict allow-list reads
 * `ctx.tools.get(name)` at setup). The stub's schema matches the dsh-tools
 * contract (output {schema, render}); `name` is preserved so the restrict
 * allow-list identifies it by name exactly as the real harness would. */
function stubGlobalTool(name) {
  return defineTool({
    name,
    description: `F10 stub for global tool "${name}"`,
    parameters: { input: { type: 'string', description: 'stub input' } },
    output: {
      // dsh-tools output uses the VALUE schema DSL (no `required` keyword).
      schema: { type: 'object', additionalProperties: false, properties: {} },
      render: (_args, value) => [{ type: 'text', text: `${name}: ok` }]
    },
    async execute() {
      return {}
    }
  })
}

/** Materialize one (fresh or resumed) agent with the requested identity. */
async function materializeStubAgent(agents, sessionId, options) {
  const callerSignal = options.signal
  let callerSignalAborted = false
  callerSignal?.addEventListener('abort', () => {
    callerSignalAborted = true
  }, { once: true })
  const parentSession = options.parentSession ?? options.meta?.parentSession
  const agent = {
    id: sessionId,
    options: options.agentOptions ?? {},
    status: 'idle',
    session: {
      header: {
        id: sessionId,
        parentSession,
        delegationDepth: options.meta?.delegationDepth
      },
      // M-A: a seeded create (the dept_head_rotate fresh-mint passes the
      // journal seed — buildHeadRotationSeed) materializes those events into
      // the fresh session, mimicking the real factory's
      // sessions.prepare(id, {seed, meta}) boundary (the synchronous
      // snapshots/validation are the dshd-core unit tests' job; here the
      // events must simply be observable in the fresh session).
      events: [...(Array.isArray(options.seed) ? options.seed : [])]
    },
    inboxMessages: [],
    ctx: undefined,
    callerSignalAborted: () => callerSignalAborted,
    followup(message) {
      this.inboxMessages.push(message)
    },
    steer() {},
    inject() {},
    send() {},
    cancelCalls: [],
    cancel(cause, options) {
      this.cancelCalls.push({ cause, options })
    },
    // Never settles: the Activation stays resident for the whole test (the
    // settlement watcher just waits on whenIdle forever, which is fine).
    whenIdle() {
      return new Promise(() => {})
    }
  }
  // The child context must be a REAL scoped cordis context (createScope — the
  // mechanism the real agent factory uses), anchored under the tools entry's
  // fiber ctx so the upward service walk resolves childCtx.tools as traced.
  // M2.4 (live-case replica): the REAL harness keys the agent scope BY THE
  // AGENT OBJECT — dsh-agent-loop ReactLoopAgent does `createScope(loopCtx,
  // this)` (key = the agent) + `this.ctx = scope.ctx.extend({ agent: this })`
  // — so `agentCtx.agent === the scope key`. `agents.scopeKeyAsAgent` makes
  // the stub mirror that shape (the default `Symbol` key stays for the other
  // fixtures); the M2.4 fixture needs it for the `agentCtx.agent` fallback the
  // waypoint scope resolution uses when the plugin's `scopeOf` import is a
  // different dsh-scope module instance than the harness's (the live dual
  // instance — see the M2.4 test below). `agents.scopeCreate` (M2.4) lets the
  // live-case fixture swap the scope FACTORY to a SECOND dsh-scope instance.
  const childKey = agents.scopeKeyAsAgent === true ? agent : Symbol('stub-child-scope')
  const scopeCreate = agents.scopeCreate ?? createScope
  // F10 live-layout fixture: a test may bind a STANDING ancestor scope (the
  // base agent preset's `isolate` realm) as the agent scope's PARENT, so the
  // agent INHERITS the model capability tools as an ancestor contribution while
  // the host GLOBAL layer stays empty of them — the real dsh composition shape.
  const parentKey = agents.scopeParentKey ?? options?.scopeParent
  const scope = scopeCreate(agents.scopeAnchor, childKey, parentKey !== void 0 ? { parent: parentKey } : void 0)
  const childCtx = scope.ctx.extend({ agent })
  agent.ctx = childCtx
  agents.childContexts.push({ ctx: childCtx, key: childKey })
  agents.childAgents.push(agent)
  // The programmatic setup runs BEFORE publish, and the real harness AWAITS it
  // (dsh-agent-loop lib/index.js:1260 `(await raceAbort(setup?.(ctx)...))?.commit()`)
  // — so the stub awaits it too. This keeps the F10 preset-mount ordering test
  // deterministic (the async postSetup must fully mount the preset + restrict
  // BEFORE the agent is observable) and is faithful to the production seam.
  const provision = await options.setup?.(childCtx)
  provision?.commit?.()
  agents.store.set(sessionId, agent)
  return {
    agent,
    dispose: async () => {
      // Record the invocation BEFORE awaiting the gate (the real harness
      // dispose() starts the teardown synchronously — machine.cancel — and
      // only then awaits whenIdle).
      agents.disposeCalls.set(sessionId, (agents.disposeCalls.get(sessionId) ?? 0) + 1)
      const gate = agents.disposeGates.get(sessionId)
      if (gate !== undefined) await gate
      agents.store.delete(sessionId)
    }
  }
}

/**
 * Stub agents service: satisfies the REAL SubagentContinuationManager's
 * materialization + cold-resume contract. Child contexts are REAL scoped
 * cordis contexts, so registerContinuableSetup registrations land in the
 * child's own tool layer.
 */
class StubAgents extends Service {
  constructor(ctx, sessionCwds) {
    super(ctx, 'agents')
    this.store = new Map()
    this.createCalls = []
    this.resumeCalls = []
    this.childContexts = []
    this.childAgents = []
    this.scopeAnchor = ctx
    // F5: the shared sessionId → cwd index (mirrors the harness's canonical-
    // cwd header index) so the StubWorkspaceRegistry's attach can validate the
    // cwd vs workspace path like the real dsh-workspace attachSession does.
    this.sessionCwds = sessionCwds
    // Piece 1 cwd fix (2026-08-22): forced resume failures (per durable session
    // id) so the wakePost resume-failed → create-fresh fallback is testable.
    this.resumeRejects = new Set()
    // W6 system-health: forced MATERIALIZE failures (per durable session id) so
    // a content-free bus delivery can be driven to the 'failed' catch block that
    // records a post-error line (both resume AND create must throw).
    this.createRejects = new Set()
    // fb-6 forensics: forced CREATE failures with the REAL harness
    // no-provider/model signature (per durable session id) — the residual case
    // where the WORKER_AGENT_OPTIONS fallback ALSO fails is drivable
    // deterministically (B5 marker + post-error forensics tests).
    this.createNoProviderRejects = new Set()
    // W8-i: per-session 'session "<id>" not found' ONCE (the transient first-
    // attempt failure the host delivery retries through the host-attach repair
    // seam) — the FIRST resume throws the harness not-found class, the retry
    // resume SUCCEEDS, so the W8-i retry-before-record + no-trace tests can
    // drive a transient not-found deterministically.
    this.resumeNotFoundOnce = new Set()
    // W8-i: per-session PERSISTENT 'session "<id>" not found' (the retry ALSO
    // fails) — every resume throws the not-found class so the W8-i
    // record-only-on-retry-failure + the stable per-(post+class) dedupe tests
    // drive a persistent not-found deterministically.
    this.resumeNotFound = new Set()
    // Sleep-self-deadlock fix tests (2026-08-23): per-session dispose GATES —
    // a promise the stub handle's dispose awaits BEFORE detaching, modelling
    // the real harness dispose() → await machine.whenIdle() contract (which
    // never settles from the machine's own turn, the deadlock the fix removes)
    // — and a per-session dispose-call counter to assert the shared-promise
    // dedupe (one detach for two concurrent disposers, no leaks).
    this.disposeGates = new Map()
    this.disposeCalls = new Map()
    // F10 live-layout fixture: the standing scope key (a base-agent-preset
    // `isolate` realm) mounted as the PARENT of every agent scope materialized
    // AFTER this field is set. A test sets this BEFORE spawning/rotating an
    // agent so the agent INHERITS the model capability tools as an ancestor
    // contribution while the host GLOBAL layer stays empty of them. Undefined
    // by default (the pre-Preset layout: no ancestor layer, globals only).
    this.scopeParentKey = undefined
    // M2.4 (live-case replica): when true, every child scope created by this
    // stub is keyed BY THE AGENT OBJECT itself (createScope(anchor, agent) —
    // the dsh-agent-loop ReactLoopAgent shape: `createScope(loopCtx, this)`
    // + `ctx.extend({ agent: this })`), so `agentCtx.agent === scopeOf(ctx)`.
    // False by default (the pre-M2.4 fixtures key child scopes by a Symbol).
    this.scopeKeyAsAgent = false
    // M2.4 (live-case replica): the scope FACTORY the stub uses for child
    // scopes. Default `undefined` → the canonical top-level `createScope`
    // import. The M2.4 fixture overrides it with a SECOND dsh-scope instance
    // (query-suffixed import of the same package — a distinct module with its
    // OWN kScope symbol), reproducing the LIVE dual-instance shape: the harness
    // side (createScope + the loader's dsh-scope consumers) runs on one module
    // instance while the deepartments lib keeps the canonical one — exactly the
    // post-boot condition where the plugin's `scopeOf(agentCtx)` reads
    // `undefined` and the audit waypoints collapse to the GLOBAL view.
    this.scopeCreate = undefined
  }

  get(id) {
    return this.store.get(id)
  }

  list() {
    return [...this.store.values()]
  }

  roots() {
    return [...this.store.values()]
  }

  put(agent) {
    this.store.set(agent.id, agent)
    return agent
  }

  async create(options) {
    this.createCalls.push(options)
    if (this.createNoProviderRejects.has(String(options.sessionId))) throw new Error(`agent "session-${String(options.sessionId)}" has no provider/model`)
    if (this.createRejects.has(String(options.sessionId))) throw new Error('stub: forced create failure (W6 post-error script)')
    this.sessionCwds?.set(String(options.sessionId), options.meta?.cwd)
    this.ensureStoreSession(options.sessionId, options.meta)
    return materializeStubAgent(this, options.sessionId, options)
  }

  async resume(options) {
    this.resumeCalls.push(options)
    // W8-i: a PERSISTENT 'session "<id>" not found' (every resume throws — the
    // retry ALSO fails) → the W8-i record-on-retry-failure + stable-dedupe path.
    if (this.resumeNotFound.has(options.resumeSessionId)) throw new Error(`session "${options.resumeSessionId}" not found`)
    // W8-i: a transient 'session "<id>" not found' (once per session) thrown by
    // the NORMAL resume path — the W8-i retry must re-resume SUCCESSFULLY.
    if (this.resumeNotFoundOnce.has(options.resumeSessionId)) {
      this.resumeNotFoundOnce.delete(options.resumeSessionId)
      throw new Error(`session "${options.resumeSessionId}" not found`)
    }
    if (this.resumeRejects.has(options.resumeSessionId)) throw new Error('stub: forced resume failure (Piece 1 cwd-fix test)')
    this.sessionCwds?.set(String(options.resumeSessionId), options.meta?.cwd)
    // Cold resume: restore a dormant resident under its DURABLE id (the seeded
    // childId), with header.parentSession from the adoption map, applying the
    // setup closure (board tools install on cold resume exactly like fresh).
    this.ensureStoreSession(options.resumeSessionId, {
      ...options.meta,
      parentSession: postAdoption.get(options.resumeSessionId)
    })
    return materializeStubAgent(this, options.resumeSessionId, {
      ...options,
      parentSession: postAdoption.get(options.resumeSessionId)
    })
  }

  /**
   * Piece 1 — production parity for the SESSIONS STORE: a real dsh-agent root
   * session is ENTERED in `ctx.sessions` while its agent lives (root agents
   * appear in `sessions.list()`), and the plugin's head title pin resolves
   * the session via `ctx.sessions.get(...)`. The stub therefore registers the
   * session id in the REAL dsh-session store at create/resume, so ensureHead's
   * pin finds a live Session and the tests observe the pinned log on the
   * store entry (which production equates with the agent's own session).
   * Idempotent: a resume-after-create (or a wake-cold-resume of a session
   * still entered in the store) REUSES the existing entry instead of tripping
   * the store's duplicate-id rejection. Never throws: a missing/faulty store
   * degrades to the plain agent session, mirroring the optional-seam
   * discipline the plugin itself uses.
   */
  ensureStoreSession(sessionId, meta = {}) {
    const id = SessionId(sessionId)
    // `this.ctx.get('sessions')` (NOT the `this.ctx.sessions` property — cordis
    // guards non-injected property access on a service ctx).
    const store = this.ctx.get('sessions')
    if (store === undefined || typeof store.get !== 'function') return undefined
    const existing = store.get(id)
    if (existing !== undefined) return existing
    try {
      return store.create(id, { meta }) ?? store.get(id)
    } catch {
      // A concurrent registration won the race — reuse its entry.
      return store.get(id)
    }
  }
}

/** FIX-2 (QD NO_ADAPTER alerting) — a trivial optional `llm` service stub:
 * satisfies the plugin's BOOT provider-adapter check (`ctx.get('llm').
 * listProviders()`). A boot WITHOUT this option leaves `llm` absent (the
 * hermetic default) so the boot check skips with a warn (headless/minimal
 * profile), exactly as production.
 *
 * FIX-2 race-tolerance: `listProviders` may be EITHER a static array (the
 * pre-race test shape) OR a FUNCTION the boot check PROBES on EACH poll — so a
 * test models a provider adapter that REGISTERS ASYNCHRONOUSLY after the boot
 * check first reads the registry (the fix-2 false positive: the check fires
 * before `ctx.llm.registerAdapter` settles). */
class StubLLM extends Service {
  constructor(ctx, providers) {
    super(ctx, 'llm')
    this.providers = providers ?? []
  }

  listProviders() {
    return typeof this.providers === 'function' ? this.providers() : this.providers
  }
}

/** Stub persistence: author enough of a resolved session to cold-resume, and
 * (FIX 1 — the rotation cold-seed seam) RECORD the S2 `create`/`append` calls
 * as spies so the real-Loader rotation can run (no real artifact backend is
 * needed — the rotation unit tests cover artifact shape; here the point is
 * that the seed landed via the persistence seam and NOT in the live store). */
class StubPersistence extends Service {
  constructor(ctx, durableSessions = []) {
    super(ctx, 'sessionPersistence')
    this.createCalls = []
    this.appendCalls = []
    // Dx1 F2 (boot residue): the durable sessions the STUB knows — ids the
    // boot residue sweep enumerates via list() (each becomes a header {id}).
    // Default [] keeps the pre-fixture behavior byte-identical for every
    // existing test (the bootPlugin `durableSessions` opt opts in).
    this.durableSessions = durableSessions
  }

  /** S2 `persistence.create(meta)` — detached lazy metadata (spy). */
  async create(meta) {
    this.createCalls.push(meta)
  }

  /** S2 `persistence.append(id, events)` — the seed artifact (spy). */
  async append(id, events) {
    this.appendCalls.push({ id, events })
  }

  async inspect(childId) {
    const parentSession = postAdoption.get(childId)
    if (parentSession === undefined) {
      throw new Error('stub persistence: no stored session for this child')
    }
    return {
      meta: { parentSession, seedLength: 0 },
      events: [{
        type: 'subagent/descriptor',
        data: { version: 2, mode: 'continuable', provider: 'spawn', label: 'board-post' }
      }]
    }
  }

  /** B2: `sessionPersistence.list()` — the persistence-header enumeration the
   * continuation manager's listChildren uses to build its cold corpus. The
   * stub has no detached sessions, so the live-preferred corpus stays
   * live-only (a cold child cannot be resumed in this harness either). Dx1 F2:
   * when the boot opted into `durableSessions`, those ids ARE the corpus (the
   * boot residue sweep enumerates them). */
  async list() {
    return [...this.durableSessions].map((id) => ({ id: String(id) }))
  }
}

// NOTE (Task T1): the StubPersistence above deliberately exposes NO `readRaw`,
// so the one-cycle session-log capture in the hermetic harness always degrades
// to the STUB form (`transcript: unavailable`) — exactly the service-absence
// scenario the spec's Risks section mandates must degrade silently (test 4).
// The bundle resolves `sessionPersistence`/`sessionQuery` OPTIONALLY via
// `ctx.get` (see src/index.ts note), so the plugin boots without them.

// Batch S1 live-fix: an OPT-IN real-API-shaped persistence for the real-capture
// tests. `readRaw` IS present — a BOUND class method that uses `this` (mirroring
// the jsonl backend's `readRaw` at dsh-session-persistence-jsonl lib/index.js:869),
// so an unbound extraction-and-call would crash with a raw TypeError, exactly
// like the live bug — and it returns a canned artifact only when one is
// configured (`undefined` otherwise, exercising the "service present but no
// stored artifact" degrade path). bootPlugin mounts it when passed
// `{ rawPersistence: true }`.
class StubPersistenceWithRaw extends StubPersistence {
  artifact = undefined
  artifactById = new Map()

  setRawArtifact(content) {
    this.artifact = content
  }

  /** B5-ghost: set a PER-SESSION raw artifact (a durable session present for
   * EXACTLY that id) — the conservative readonly resolver can then certify
   * usable vs definitively-gone per post, without a global artifact leaking to
   * every other session. */
  setRawArtifactFor(id, content) {
    this.artifactById.set(String(id), content)
  }

  async readRaw(id) {
    const byId = this.artifactById.get(String(id))
    if (byId !== undefined) return { meta: { id }, filename: 'session.jsonl', content: byId }
    if (this.artifact === undefined) return undefined
    return { meta: { id }, filename: 'session.jsonl', content: this.artifact }
  }
}

/** Stub persistence carrying a `root` (so the boot web-UI cleanup hook can
 * resolve the sessions root + derived state-home paths, like the real jsonl
 * backend's public `root` — mirrors session-cleanup.test.js). Used by the
 * Fix wake-12 restart tests to author a witness artifact the boot cleanup
 * truncates: the cleanup hook is chained AFTER the hosts loader restored the
 * deferred seed, so observing its flag-clear is the deterministic "the restore
 * has happened" marker before the wake pre-step runs. */
class StubPersistenceWithRoot extends StubPersistence {
  constructor(ctx, root) {
    super(ctx)
    this.root = root
  }
}

/** Dx1 F2 fallback — a persistence carrying a sessions `root` but NO `list()`
 * (the headless/minimal shape) so the boot residue sweep exercises its
 * bounded sessions-root dir scan. */
class StubPersistenceRootOnly extends Service {
  constructor(ctx, root) {
    super(ctx, 'sessionPersistence')
    this.root = root
  }
}

/** U2 — stub of the canonical session-archive service (dsh-workspace
 * `workspaceRegistry`, the same service the web RPC `workspace.archiveSession`
 * drives): a pure registry-global set add + durable mirror file, no session/
 * agent termination. Rotation calls `archiveSession(oldId)` server-side
 * (spec 002 §3.3 S2.5) — the tests assert the old id lands in
 * `archivedSessionIds` + the durable mirror. FIX 1b — also the workspace
 * LIST/ATTACH surface (spec 002 §3.3 S2.2 + the boot repair hook): `list()`
 * returns the workspace entities (default: one recording entity at
 * `stateDir`; `bootPlugin({ workspaceEntities })` overrides for the repair
 * tests) and `attachSession` records the target ids (reality validates the
 * session's persisted header cwd against the entity path and throws on
 * mismatch — dsh-workspace lib:87-105). FIX 1b.1 — model the provider's
 * mid-init window: while `notReadyRejects` > 0, `list()` rejects like the
 * real registry whose storage/start has not completed ("workspace registry is
 * not started yet"; each call decrements). The boot repair hook must RETRY
 * (non-strict get + bounded loop) until list() resolves — the old strict-get
 * race silently skipped exactly this state in production. */
class StubWorkspaceRegistry extends Service {
  constructor(ctx, stateDir, entities, sessionCwds) {
    super(ctx, 'workspaceRegistry')
    this.stateDir = stateDir
    this.archived = []
    this.attachCalls = []
    this.notReadyRejects = 0
    this.createCalls = []
    this.resolveByPathCalls = []
    // F5: the shared sessionId → cwd index, so the attach below can validate
    // the session cwd against the entity path like the real dsh-workspace
    // attachSession (realpath equality). A session whose cwd is NOT tracked
    // (a host session minted by the harness/GUI, or a resume without a create)
    // skips validation — preserving the pre-F5 stub behavior for tests that
    // never track a cwd for the session.
    this.sessionCwds = sessionCwds
    // Piece 1 cwd fix (2026-08-22): the default entity carries the DURABLE
    // membership view the real entity exposes (`sessionIds` — dsh-workspace
    // lib:78-80) AND mirrors the real attach into the persisted workspace
    // record (workspace.json) — the exact projection the native sidebar groups
    // by. This lets the cwd-fix tests assert both the resolved create cwd and
    // the post-attach membership file.
    this.entitySessions = []
    const defaultEntity = {
      path: stateDir,
      title: 'root',
      sessionIds: this.entitySessions,
      attachSession: async (sessionId) => {
        this.attachCalls.push(sessionId)
        const cwd = this.sessionCwds?.get(String(sessionId))
        if (cwd !== undefined && cwd !== stateDir) throw new Error(`stub: cwd mismatch for ${sessionId} (${cwd} != ${stateDir})`)
        if (!this.entitySessions.includes(sessionId)) {
          this.entitySessions.push(sessionId)
          writeFile(path.join(this.stateDir, 'workspace.json'), JSON.stringify({ path: this.stateDir, sessionIds: [...this.entitySessions] }, null, 2), 'utf8')
            .catch(() => {})
        }
      }
    }
    this.entities = entities ?? [defaultEntity]
  }

  get archivedSessionIds() {
    return this.archived
  }

  setNotReadyRejects(count) {
    this.notReadyRejects = count
  }

  list() {
    if (this.notReadyRejects > 0) {
      this.notReadyRejects--
      return Promise.reject(new Error('workspace registry is not started yet'))
    }
    return Promise.resolve(this.entities)
  }

  /** F5 (spec 004 §6.2 L1) — `create(path, title)`: idempotent for an existing
   * entity at the same canonical path (returns it, title untouched — matching
   * the real registry's "existing canonical path returns the existing entity
   * without changing its title"); otherwise creates a NEW validation-aware
   * entity (cwd == path required to attach). Records the call so the tests can
   * assert the workspace was created with the department name as its title. */
  async create(path, title) {
    this.createCalls.push({ path, title })
    const existing = this.entities.find((e) => e.path === path)
    if (existing !== undefined) return existing
    const sessions = []
    const entity = {
      path,
      title,
      sessionIds: sessions,
      attachSession: async (sessionId) => {
        this.attachCalls.push(sessionId)
        const cwd = this.sessionCwds?.get(String(sessionId))
        if (cwd !== undefined && cwd !== path) throw new Error(`stub: cwd mismatch for ${sessionId} (${cwd} != ${path})`)
        if (!sessions.includes(sessionId)) sessions.push(sessionId)
      }
    }
    this.entities.push(entity)
    return entity
  }

  /** F5 RACE FIX (incident 2026-08-23) — `resolveByPath(path)`: the
   * NON-MUTATING canonical-path lookup of the real registry (dsh-workspace
   * lib:452-455 — realpath-normalizes, then returns the entity owning the
   * canonical path, or `undefined` when the directory is unowned). This is the
   * anti-duplicate guard the ensure uses AFTER list() has proven the durable
   * state is loaded: an entity an earlier boot / the GUI already created is
   * returned WITHOUT creating a fresh duplicate record. Records the call so
   * the tests can assert resolveByPath-first ordering. */
  async resolveByPath(path) {
    this.resolveByPathCalls.push(path)
    const canonical = await realpath(path)
    return this.entities.find((e) => e.path === canonical)
  }

  async archiveSession(sessionId) {
    if (this.archived.includes(sessionId)) return
    this.archived.push(sessionId)
    // Durable mirror (fire-and-forget, like the real registry's setState →
    // global.set): T7 asserts the state file holds archivedSessionIds.
    writeFile(path.join(this.stateDir, 'workspace-registry.json'), JSON.stringify(this.archived, null, 2), 'utf8')
      .catch(() => {})
  }
}

/** A live parent agent as the registry would hold it (exact identity). */
function fakeParentAgent(id = SessionId(randomUUID())) {
  return {
    id,
    options: { provider: 'deepseek-official', model: 'deepseek-v4-flash' },
    status: 'idle',
    session: { header: { id }, events: [] },
    ctx: { get: () => undefined },
    inboxMessages: [],
    injectedMessages: [],
    followup(message) {
      this.inboxMessages.push(message)
    },
    steer() {},
    inject(message) {
      this.injectedMessages.push(message)
    },
    send() {},
    cancelCalls: [],
    cancel(cause, options) {
      this.cancelCalls.push({ cause, options })
    },
    whenIdle() {
      return new Promise(() => {})
    }
  }
}

// --- boot harness --------------------------------------------------------------

/** F10 preset-mount ordering fixture (2026-08-23): a stub agentPresets service
 * that replicates the REAL mount() TIMING. The real agentPresets.mount(agentCtx,
 * id) resolves the preset, ensures its STANDING mount, and BINDS the agent scope
 * to that standing scope (dsh-agent-presets lib/index.js:954-960,
 * bindScopeParent) — the fs capability tools are an ANCESTOR contribution of
 * that standing mount, NOT host-global. This stub registers the capability tools
 * into a PER-PRESET standing scope and binds the agent scope to it ONLY when
 * mount() is called (the async bind inside the real mount). So a capability
 * probe that runs BEFORE the mount (the pre-fix postSetup order, a
 * fire-and-forget `void agentPresets.mount(...)`) sees NO fs tools — the agent
 * scope is not yet parented — and drops them from the allow-list, which
 * restrict() then masks; a probe that runs AFTER the mount (the fix) sees them
 * as an inherited contribution and keeps them. The default is board-only
 * (agentPresets absent). */
class StubAgentPresets extends Service {
  constructor(root, agents) {
    super(root, 'agentPresets')
    this.root = root
    this.agents = agents
    this.standingScope = new Map() // presetId -> { key, ctx }
    this.mountCalls = []
  }

  _standing(presetId) {
    let standing = this.standingScope.get(presetId)
    if (standing === undefined) {
      const key = Symbol(`standing-${presetId}`)
      const scope = createScope(this.agents.scopeAnchor ?? this.root, key)
      standing = { key, ctx: scope.ctx }
      this.standingScope.set(presetId, standing)
    }
    return standing
  }

  async resolve() {
    return { id: 'deepartments' }
  }

  async mount(agentCtx, presetId = 'deepartments') {
    this.mountCalls.push(presetId)
    const standing = this._standing(presetId)
    // Register the preset capability tools into the STANDING (ancestor) scope
    // ONLY here, idempotent per preset — the preset's own layer, exactly where
    // the real base-agent-preset carries them.
    for (const name of ['read', 'write', 'glob', 'grep', 'web_search', 'web_fetch']) {
      if (standing.ctx.tools.get(name) === undefined) {
        standing.ctx.tools.register(stubGlobalTool(name))
      }
    }
    // Bind the agent's scope to the standing (ancestor) scope — the async bind
    // the real mount performs inside mount(). A capability probe that runs
    // BEFORE this bind sees NO inherited fs tools (the agent scope has no
    // parent standing mount yet).
    const agentKey = scopeOf(agentCtx)
    if (agentKey !== undefined) {
      bindScopeParent(agentKey, standing.key)
    }
  }
}

/** FASE 2.6 shared-config-source stub: provides the `deepartments.org` SHARED
 * CONFIG SOURCE service (the surface the bundle consumes in the full/FASE 2.6
 * composition where the dshd-core row is the source of truth). A test sets it
 * to carry org.postsRetention while the bundle's OWN mirror (`opts.org`) does
 * NOT, so the boot reconcile's SHARED-first read is exercised. Absent → dshd-core
 * is NOT composed (the hermetic default) → the bundle falls back to cfg.org. */
class StubDeepartmentsOrg extends Service {
  constructor(ctx, stateDir, org) {
    super(ctx, 'deepartments.org')
    this.stateDir = stateDir
    this.org = org
  }
}

/**
 * Boot the REAL Loader with the REAL dsh services, the REAL SubagentRuntime,
 * stub agents/persistence services, two stub subagent providers, and the
 * dsh-deepartments bundle itself.
 */
async function bootPlugin(stateDir, opts = {}) {
  const root = new Context()
  const loaderFiber = await root.plugin(Loader, { baseUrl: new URL('.', import.meta.url).href })
  const loader = root.loader
  loader.create({ id: 'sessions', name: '@deepseek-ai/dsh-session' })
  loader.create({ id: 'projections', name: '@deepseek-ai/dsh-session-projection' })
  loader.create({ id: 'systemPrompt', name: '@deepseek-ai/dsh-system-prompt' })
  loader.create({ id: 'tools', name: '@deepseek-ai/dsh-tools' })

  const agents = new StubAgents(root)
  // FIX-2 (QD NO_ADAPTER alerting): an OPT-IN `llm` service stub so the BOOT
  // provider-adapter check is drivable (ctx.get('llm').listProviders()). A boot
  // without this option leaves `llm` ABSENT (the hermetic default) → the boot
  // check skips with a warn (headless/minimal profile), exactly as production.
  const llm = opts.llmListProviders !== undefined ? new StubLLM(root, opts.llmListProviders) : undefined
  // F10 preset-mount ordering fix: an OPT-IN stub agentPresets service that
  // replicates the real mount() timing (registers the preset fs tools into a
  // PER-PRESET standing scope and binds the agent scope to it only when mount()
  // is called), so a test can exercise the "the mount must be AWAITED before the
  // capability probe" ordering. When absent, postSetup skips the mount (the
  // hermetic default — board-only).
  const agentPresets = opts.agentPresets === true ? new StubAgentPresets(root, agents) : undefined
  // Piece 1 cwd fix (2026-08-22): a boot opt forces per-session resume failures
  // (the wakePost resume-failed → create-fresh fallback path).
  if (opts.resumeRejects !== undefined) agents.resumeRejects = new Set(opts.resumeRejects)
  // W6 system-health: a boot opt forces per-session CREATE failures (so both
  // resume AND create throw → a bus delivery reaches the 'failed' catch block
  // that records the post-error-line class).
  if (opts.createRejects !== undefined) agents.createRejects = new Set(opts.createRejects)
  // fb-6 forensics: a boot opt forces per-session CREATE failures with the
  // real "has no provider/model" SIGNATURE (distinct from the generic W6
  // createRejects — the B5 marker + post-error forensics need the exact
  // harness class), so the residual fallback-ALSO-fails path is drivable.
  if (opts.createNoProviderRejects !== undefined) agents.createNoProviderRejects = new Set(opts.createNoProviderRejects)
  // W8-i: a boot opt forces a per-session transient 'session "<id>" not found'
  // ONCE (so the host delivery retry is exercised: first resume throws, the
  // retry resume succeeds → NO post-error row).
  if (opts.resumeNotFoundOnce !== undefined) agents.resumeNotFoundOnce = new Set(opts.resumeNotFoundOnce)
  // W8-i: a boot opt forces a per-session PERSISTENT 'session "<id>" not found'
  // (every resume throws → the retry ALSO fails → the record-on-retry-failure +
  // stable per-(post+class) dedupe path).
  if (opts.resumeNotFound !== undefined) agents.resumeNotFound = new Set(opts.resumeNotFound)
  // F5 (spec 004 §6.2): the shared sessionId → cwd index the StubAgents records
  // on create and the StubWorkspaceRegistry validates on attach (mirrors the
  // harness canonical-cwd header index, so the department-workspace tests can
  // assert the session groups into ITS department entity, not the root one).
  const sessionCwds = new Map()
  agents.sessionCwds = sessionCwds
  // Batch S1 live-fix: a boot opt swaps in the real-API-shaped persistence
  // (readRaw present) so the real-capture tests exercise the bound call shape;
  // the default stays readRaw-less so the harness keeps degrading to the stub.
  // B5-ghost: `opts.rawArtifacts` ({ sessionId → content }) pre-seeds
  // PER-SESSION raw artifacts at construction — BEFORE any boot pass reads them
  // (a deterministic durable-present signal for exactly those sessions).
  // Fix wake-12: a boot opt mounts a root-carrying persistence so the boot
  // web-UI cleanup hook can resolve the sessions root (restart tests).
  const persistence = opts.rawPersistence === true
    ? (() => {
        const p = new StubPersistenceWithRaw(root)
        if (opts.rawArtifacts !== undefined) {
          for (const [id, content] of Object.entries(opts.rawArtifacts)) p.setRawArtifactFor(String(id), content)
        }
        return p
      })()
    : opts.persistenceRoot !== undefined
      ? new StubPersistenceWithRoot(root, opts.persistenceRoot)
      : opts.persistenceRootOnly !== undefined
        ? new StubPersistenceRootOnly(root, opts.persistenceRootOnly)
        : new StubPersistence(root, opts.durableSessions)
  // U2: the canonical session-archive service (`workspaceRegistry`) — mounted
  // like the real GUI profile has it, so the rotated dept_sleep's server-side
  // archive (spec 002 §3.3 S2.5) is exercised through the same seam. FIX 1b:
  // `workspaceEntities` (optional) overrides the entity list the S2.2 attach
  // and the boot repair hook iterate (default: one recording entity).
  // F5 RACE FIX (incident 2026-08-23): `withoutWorkspaceRegistry: true`
  // composes a composition WITHOUT the workspaceRegistry service at all (the
  // production-headless shape — `ctx.get('workspaceRegistry')` returns
  // undefined) so the ensure's DEFINITIVE-absence path (no list/create seam)
  // is exercised directly.
  const workspaceRegistry = opts.withoutWorkspaceRegistry === true
    ? undefined
    : new StubWorkspaceRegistry(root, stateDir, opts.workspaceEntities, sessionCwds)
  // P2 VISIBILITY FIX (2026-08-25): a boot opt PRE-SEEDS the registry archive
  // set — the archive-leak regression drives an ensureHead that observes a
  // durable head id ALREADY archived before materialization (this is the
  // resumed-archived-id state the fix rotates away from; the real registry
  // persists the set across boots in workspace.json archivedSessionIds).
  if (workspaceRegistry !== undefined && Array.isArray(opts.workspaceRegistryArchived)) {
    for (const id of opts.workspaceRegistryArchived) {
      if (!workspaceRegistry.archived.includes(id)) workspaceRegistry.archived.push(id)
    }
  }
  // FIX 1b.1 — `registryNotReadyRejects` models a provider whose init is still
  // in flight at boot (list() rejects mid-init) for the boot-repair retry
  // regression.
  if (workspaceRegistry !== undefined && typeof opts.registryNotReadyRejects === 'number' && opts.registryNotReadyRejects > 0) {
    workspaceRegistry.setNotReadyRejects(opts.registryNotReadyRejects)
  }
  await root.plugin(SubagentRuntime)

  const spawnStub = stubProvider('spawn')
  const forkStub = stubProvider('fork')
  root.subagents.registerProvider(spawnStub)
  root.subagents.registerProvider(forkStub)

  // B2 override fixture: compose the REAL harness control plugin
  // (dsh-tool-subagent-control — the native global `send_message`) BEFORE the
  // deepartments row, exactly as dsh-base does in the GUI/headless profiles.
  // AWAITED so the native owns the global name deterministically BEFORE the
  // deepartments row applies (the plugin then must NOT register `send_message`
  // globally — same-layer duplicate would throw — and must shadow the native
  // per-agent own-layer).
  if (opts.nativeControlTool === true) {
    await loader.create({ id: 'native-tool-subagent-control', name: '@deepseek-ai/dsh-tool-subagent-control' })
  }

  // FASE 2.6 shared-config-source fixture: `opts.composeCore === true` composes
  // the REAL dshd-core plugin BEFORE the bundle, so its `apply` SYNCHRONOUSLY
  // provides `deepartments.org` (the SHARED CONFIG SOURCE) with the org config
  // given in `opts.deepartmentsOrg` (e.g. carrying org.postsRetention) while the
  // bundle's OWN mirror (`opts.org`) does NOT — the exact post-relocation split
  // the boot reconcile reads SHARED-first (`coreOrg?.org ?? cfg.org`). ABSENT →
  // dshd-core is NOT composed (the hermetic default) → the bundle falls back to
  // cfg.org (behavior-neutral). Composing dshd-core via the Loader (rather than
  // a stub Service) is REQUIRED for determinism: it provides `deepartments.org`
  // synchronously inside its `apply`, so it is resolvable at the bundle's own
  // apply time (a stub Service registers asynchronously and is NOT yet visible
  // when the bundle's `apply` reads `ctx.get('deepartments.org')`).
  if (opts.composeCore === true) {
    await loader.create({
      id: 'dshd-core',
      name: 'dshd-core',
      config: {
        stateDir,
        org: opts.deepartmentsOrg ?? { departments: [] }
      }
    })
  }

  loader.create({
    id: 'deepartments',
    name: '../lib/index.js',
    config: {
      stateDir,
      // F1: `opts.org` overrides TEST_ORG (the multi-department scope tests
      // need a SECOND configured department/head); the default stays TEST_ORG
      // whose departments carry NO workspacePath/jobDir — the optional-field
      // compat surface every test already exercises.
      org: opts.org ?? TEST_ORG,
      // W6 system-health: `opts.health` supplies the `health` config section
      // (a config-toggle test); absent → the section is omitted (code default
      // enabled:true, intervalMs:60000).
      ...(opts.health !== undefined ? { health: opts.health } : {})
    }
  })
  await loader.await()
  agents.scopeAnchor = loader.resolve('tools').fiber?.ctx ?? root
  // F10 (spec 004 §7.1): register the GLOBAL harness capability tools as stubs
  // AFTER boot (once the tools service is composed — an inline register before
  // `loader.await()` would touch the pre-composition tools and corrupt it). The
  // BOOTED head's setup ran before this (its inherited surface is board-only),
  // but any LATER materialization — a dept_worker_spawn, or a slept head's
  // wake — sees the globals in its restrict allow-list (in the real harness
  // these are the native globals the host profile composes). An
  // already-registered name is skipped (no duplicate throw).
  if (opts.globalTools !== undefined) {
    for (const name of opts.globalTools) {
      if (root.tools.get(name) === undefined) root.tools.register(stubGlobalTool(name))
    }
  }
  return {
    root,
    agents,
    llm,
    agentPresets,
    persistence,
    workspaceRegistry,
    spawnStub,
    forkStub,
    pluginCtx: () => loader.resolve('deepartments').fiber?.ctx ?? loader.resolve('deepartments').ctx,
    dispose: () => loaderFiber.dispose()
  }
}

async function waitFor(predicate, timeoutMs = 5000, label = 'condition') {
  const deadline = Date.now() + timeoutMs
  while (Date.now() < deadline) {
    if (await predicate()) return
    await new Promise((resolve) => setTimeout(resolve, 25))
  }
  throw new Error(`timed out waiting for ${label}`)
}

/** Race a promise against a short deadline; rejects with a LABELED error when
 * the deadline passes (used to assert that a path does NOT block — the pre-fix
 * dept_sleep self-deadlock would time out here). Clears the timer on settle so
 * the losing timer can never produce an unhandled rejection; the hung promise
 * itself stays pending (a pending promise is inert, no unhandled rejection). */
function withTimeout(promise, ms, label) {
  let timer
  const deadline = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(`timed out: ${label}`)), ms)
  })
  return Promise.race([promise, deadline]).finally(() => clearTimeout(timer))
}

async function withTempStateDir(fn) {
  const stateDir = await mkdtemp(path.join(tmpdir(), 'deepartments-invoke-'))
  try {
    return await fn(stateDir)
  } finally {
    await rm(stateDir, { recursive: true, force: true })
  }
}

/**
 * Seed a durable department head (root agent) into posts.json BEFORE boot,
 * and register its adoption so a cold resume restores it under the same
 * stable session id (`head-<postId>`). Mirrors what a production posts.json
 * holds for a previously-materialized head.
 */
/** B3b2: settle the boot's fire-and-forget head materialization (ensureAllHeads
 * runs after the registries load — the room-boot barrier `waitForRooms` used
 * to provide is gone with the rooms). Tests that act on the booted plugin
 * before their own head wait must call this right after bootPlugin. */
async function waitForHeadMaterialized(agents) {
  await waitFor(() => agents.store.has('head-research-head'), 5000, 'head materialized at boot')
}

async function seedPost(stateDir, { postId, sessionId = `head-${postId}`, roomId, agentPreset = 'deepartments-head', provider, role, departmentId, managerId, jobId, retired, sleepEpoch, previousChildId, inflightWorkers, tools }) {
  const postsPath = path.join(stateDir, 'posts.json')
  let existing = {}
  try {
    existing = JSON.parse(await readFile(postsPath, 'utf8'))
  } catch {
    /* no prior seed */
  }
  const entry = { sessionId, roomId, agentPreset }
  // Batch 3a: a disposable worker carries its provider:'worker' marker + role.
  if (provider !== undefined) entry.provider = provider
  if (role !== undefined) entry.role = role
  // F1: the creator link + department + job link + retired marker (post-PostEntry
  // extension) — seeded so the loader exercises the NEW optional fields.
  if (departmentId !== undefined) entry.departmentId = departmentId
  if (managerId !== undefined) entry.managerId = managerId
  if (jobId !== undefined) entry.jobId = jobId
  if (retired === true) entry.retired = true
  // Batch G: a slept head carries the durable sleep-mark (and its previous
  // incarnation's sessionId) in posts.json — seeded so the relay can respawn it.
  if (sleepEpoch !== undefined) entry.sleepEpoch = sleepEpoch
  if (previousChildId !== undefined) entry.previousChildId = previousChildId
  // Fix (head-sleep worker drain): seed the durable in-flight worker ledger.
  if (inflightWorkers !== undefined) entry.inflightWorkers = inflightWorkers
  // VALLE lane B (fb-29 structural fix): the worker's durable role-template
  // `tools` allow-list (the design-B cold re-materialization fast-path).
  if (tools !== undefined) entry.tools = tools
  existing[postId] = entry
  await writeFile(postsPath, JSON.stringify(existing, null, 2), 'utf8')
  postAdoption.set(sessionId, '')
}

/** Pre-author a post's long-term memory journal at
 * `<stateDir>/journals/<postId>.md` (the durable file dept_memo_write writes)
 * so a slept head's next wake can load it as its redeployed context. */
async function seedJournal(stateDir, postId, summary) {
  const journalPath = path.join(stateDir, 'journals', `${postId}.md`)
  await mkdir(path.dirname(journalPath), { recursive: true })
  const content = [
    '---',
    `author: ${postId}`,
    `timestamp: ${new Date().toISOString()}`,
    'wake_counter: 1',
    'board_cursor: none',
    'decisions: []',
    'constraints: []',
    'open_items: []',
    '---',
    '',
    summary,
    ''
  ].join('\n')
  await writeFile(journalPath, content, 'utf8')
  return journalPath
}

/** Seed a HOST registration into hosts.json BEFORE boot (the context-injection
 * gate: only the session registered as the board host receives the wake pack).
 * The boot loader restores it into the in-memory `hosts` Map (invoke.ts:1429).
 * Returns the deterministic `host-<sessionId>` member id. */
async function seedHostRegistration(stateDir, sessionId, roomId = 'board') {
  const hostsPath = path.join(stateDir, 'hosts.json')
  await mkdir(stateDir, { recursive: true })
  await writeFile(hostsPath, JSON.stringify({ [`host-${sessionId}`]: { sessionId: String(sessionId), roomId } }, null, 2))
  return `host-${sessionId}`
}

async function readPosts(stateDir) {
  const postsPath = path.join(stateDir, 'posts.json')
  // Test hardening (mirrors readHosts below): retry until the file is present
  // AND parses. persistPosts is fire-and-forget (registerEntry → void
  // persistPosts, invoke.ts:5420), so a reader could otherwise catch the file
  // mid-write and a torn JSON.parse would throw straight through the enclosing
  // waitFor — the ~1/10 flake in the new "P2 visibility fix (b)" test.
  let parsed
  await waitFor(async () => {
    try {
      parsed = JSON.parse(await readFile(postsPath, 'utf8'))
      return true
    } catch {
      return false
    }
  }, 5000, 'posts.json readable')
  return parsed
}

async function readHosts(stateDir) {
  const hostsPath = path.join(stateDir, 'hosts.json')
  // Task T4 (test hardening): retry until the file is present AND parses.
  // persistHosts is fire-and-forget, so a reader could otherwise catch the file
  // mid-write and a torn JSON.parse would throw straight through the enclosing
  // waitFor (the ~1/6 flake in test 74 "Batch 7 host dept_sleep").
  let parsed
  await waitFor(async () => {
    try {
      parsed = JSON.parse(await readFile(hostsPath, 'utf8'))
      return true
    } catch {
      return false
    }
  }, 5000, 'hosts.json readable')
  return parsed
}

