// legacy A+B: head sleep retired 2026-08-27 — kept for history (R6)
test.skip('Batch G self-deadlock fix: a bus wake DURING the in-flight detach joins the same promise, resumes cleanly after the detach (one dispose, one resume), and a later cycle disposes the RE-materialized handle (no stale map leak)', async () => {
  await withTempStateDir(async (stateDir) => {
    const postId = 'research-head'
    await seedJournal(stateDir, postId, 'WAKE-DURING-DISPOSE: resume only after the detach.')
    const { root, agents, dispose } = await bootPlugin(stateDir)
    await waitForHeadMaterialized(agents)
    try {
      const head = agents.store.get(`head-${postId}`)
      const { ctx: headCtx, key } = agents.childContexts[0]
      const sleep = headCtx.tools.get('dept_sleep', key)
      const signal = new AbortController().signal
      let release
      const gate = new Promise((resolve) => { release = () => resolve() })
      agents.disposeGates.set(`head-${postId}`, gate)

      // Sleep: the tool call RETURNS (fire-and-forget detach, still gated).
      await withTimeout(sleep.execute({}, { agent: head, signal }), 1500, 'dept_sleep returns while the detach is in flight')
      assert.equal(agents.disposeCalls.get(`head-${postId}`), 1, 'one detach launched')

      // A wake arrives while the detach is still in flight: the bus delivery
      // (deliverBusRecord → materializePost respawn branch) must JOIN the
      // shared promise — never race a second dispose over the not-yet-
      // detached machine.
      const host = agents.put(fakeParentAgent())
      const sendPromise = root.tools.get('send_message').execute(
        { to: [postId], text: 'wake while the detach is in flight' },
        { agent: host, signal }
      )
      let sendSettled = false
      sendPromise.then(() => { sendSettled = true }, () => { sendSettled = true })
      await new Promise((r) => setTimeout(r, 750))
      assert.equal(sendSettled, false, 'the wake is PARKED on the shared detach (it does not race/resume over the live loop)')
      assert.equal(agents.disposeCalls.get(`head-${postId}`), 1, 'no second dispose from the wake (shared promise)')

      // Open the gate: the detach settles; the wake then resumes the durable
      // session and delivers — exactly one dispose overall.
      release()
      const sent = await withTimeout(sendPromise, 5000, 'bus delivery completes after the detach')
      assert.equal(sent.delivered[postId], 'resumed', 'the respawn-from-sleep delivery reports resumed')
      // F8 head rotation: the wake RECREATES the head FRESH (a NEW id) after the
      // detach — never resumes the archived old artifact.
      await waitFor(() => agents.createCalls.length > 1, 5000, 'slept head recreated fresh after the detach')
      const freshId = String(agents.createCalls.at(-1).sessionId)
      assert.notEqual(freshId, `head-${postId}`, 'the fresh wake session is a NEW id (not the archived old one)')
      assert.equal(agents.disposeCalls.get(`head-${postId}`), 1, 'still exactly ONE detach for the OLD session (the wake joined it, never doubled it)')
      assert.equal(agents.createCalls.filter((c) => String(c.sessionId) === `head-${postId}`).length, 1, 'the ARCHIVED old id is never re-created')
      const resumed = agents.store.get(freshId)
      assert.ok(resumed, 'fresh head materialized by the wake')
      await waitFor(() => resumed.inboxMessages.length >= 1, 5000, 'fresh head woken after the detach')
      assert.equal(resumed.inboxMessages.at(-1).source.kind, 'agent', 'head wake uses the bus agent source')
      await waitFor(async () => (await readPosts(stateDir))[postId].sleepEpoch === undefined, 5000, 'sleepEpoch cleared after the wake')

      // No stale map leak: a SECOND cycle (fresh handle re-materialized by the
      // wake) must dispose AGAIN — a lingering settled `disposingHeads` entry
      // would dedupe it and the counter would stay at 1. This dispose is keyed
      // by the FRESH session id (F8 rotation).
      agents.disposeGates.delete(freshId)
      const { ctx: freshHeadCtx, key: freshKey } = agents.childContexts.at(-1)
      const freshSleep = freshHeadCtx.tools.get('dept_sleep', freshKey)
      assert.ok(freshSleep, 'dept_sleep re-installed on the expanded head')
      await withTimeout(freshSleep.execute({}, { agent: resumed, signal }), 1500, 'second-cycle dept_sleep returns')
      await waitFor(() => agents.store.has(freshId) === false, 5000, 'second-cycle detach settled')
      assert.equal(agents.disposeCalls.get(freshId), 1, 'second cycle disposed the RE-materialized (FRESH) handle once (no stale in-flight map entry)')
    } finally {
      await dispose()
    }
  })
})

// --- Batch G2 (2026-08-26): the QD-directive CASCADE deadlock --------------
// The Batch G fix fired the own-handle detach from dept_sleep (awaiting it is
// invariant self-deadlock). The QD `head-slept` directive EMIT — dispatched
// AFTER that fire but AWAITED — re-entered materializePost for the directive
// target and JOINED the very detach: one level deeper, the same self-deadlock.
// Live incident (all timestamps UTC 2026-08-26): quality-head self-slept at
// 20:48:25 — its self directive (m-230) delivery joined its own never-settling
// detach → QH turn 9 ended... never (frozen). ipd head slept at 21:18:28 — its
// directive (m-237) delivery joined the QH zombie → ipd frozen. Host
// send_message (m-238) at 21:18:58 joined the ipd zombie → the host
// (session-1dcd7fda) froze mid-turn. The fix: the materializePost detach join
// is BOUNDED (joinHeadDisposeOnce) so a zombie detach can never freeze ANY bus
// delivery — including the QD directive deliveries the dept_sleep and
// host-rotation still await: a zombie target delays them by at most the bound,
// then the sleep returns, the turn ends, whenIdle settles and the zombie
// self-heals (no persistence of the freeze).

// legacy A+B: head sleep retired 2026-08-27 — kept for history (R6)
test.skip('Batch G2 QD cascade fix (A): a head dept_sleep RETURNS within the bounded detach join even when its own quality-inspect directive delivery joins the never-settling detach — the self-directive re-entry must not re-create the self-deadlock one level deeper (pre-fix: the awaited directive → materializePost → UNBOUNDED join of the just-fired detach → QH self-sleep freeze)', async () => {
  const prevInspect = process.env[QUALITY_INSPECT_ENV_VAR]
  const prevJoin = process.env.DEEPARTMENTS_DISPOSE_JOIN_TIMEOUT_MS
  process.env[QUALITY_INSPECT_ENV_VAR] = '1' // force the D-Q2 dice hit deterministically (QH self-slept directive)
  process.env.DEEPARTMENTS_DISPOSE_JOIN_TIMEOUT_MS = '300'
  try {
    await withTempStateDir(async (stateDir) => {
      const env = await bootWithQD(stateDir)
      try {
        await seedJournal(stateDir, 'quality-head', 'G2-SELF-DIRECTIVE: sleep must return even when the self directive joins the detach.')
        const { head, headCtx, key } = qdHead(env)
        // The QH machine detach can never settle (the real dispose() → await
        // machine.whenIdle() contract while this very turn runs the tool).
        env.agents.disposeGates.set('head-quality-head', new Promise(() => {}))
        const signal = new AbortController().signal
        const result = await withTimeout(headCtx.tools.get('dept_sleep', key).execute({}, { agent: head, signal }), 1500, "dept_sleep must return within the bounded join while the self-directive delivery joins the never-settling detach (pre-fix: the unbounded join → self-deadlock)")
        assert.equal(result.member, 'quality-head', 'the sleep commits immediately')
        assert.equal(env.agents.disposeCalls.get('head-quality-head'), 1, 'exactly one detach launched (in the background)')
        // The directive is STILL emitted: the bounded join lets its delivery
        // settle instead of freezing the sleep (the record is durable and
        // present when the tool returns).
        await waitFor(async () => (await qualityDirectives(stateDir)).filter((d) => /head slept.*quality-head/.test(d.text)).length >= 1, 5000, 'the self quality-inspect directive record was emitted')
        // B3 always-wake exemption: the self-directive delivery wakes the QH
        // FRESH (the sleep mark was durable at the tool's commit, then the
        // fresh mint clears it — the QH immediately gets its own inspect
        // directive, the D-Q2 anti-loop dice whatever it is).
        await waitFor(async () => {
          const post = (await readPosts(stateDir))['quality-head']
          return post.sessionId !== 'head-quality-head' && post.sleepEpoch === undefined
        }, 5000, 'the fresh incarnation is registered (self-directive always-wake)')
      } finally {
        await env.dispose()
      }
    })
  } finally {
    if (prevInspect === undefined) delete process.env[QUALITY_INSPECT_ENV_VAR]
    else process.env[QUALITY_INSPECT_ENV_VAR] = prevInspect
    if (prevJoin === undefined) delete process.env.DEEPARTMENTS_DISPOSE_JOIN_TIMEOUT_MS
    else process.env.DEEPARTMENTS_DISPOSE_JOIN_TIMEOUT_MS = prevJoin
  }
})

