test('B2 send_message noWake gate: a noWake:true send to a dormant catalog head persists the record as prepared (NO materialize/wake — the dormant head stays dormant, sleepEpoch preserved), and the default (noWake absent) send to the SAME dormant head still ALWAYS wakes (the always-wake path is byte-identical)', async () => {
  await withTempStateDir(async (stateDir) => {
    // A dormant head that is NOT a configured coordinator (ensureAllHeads skips it
    // — it stays dormant). The same shape as the B2 dormant-wake test.
    await seedPost(stateDir, { postId: 'sleeper-head', sessionId: 'head-sleeper-head', roomId: 'research', agentPreset: 'deepartments-head', sleepEpoch: Date.now() })
    const { root, agents, pluginCtx, dispose } = await bootPlugin(stateDir)
    try {
      const host = agents.put(fakeParentAgent())
      const signal = new AbortController().signal
      const send = pluginCtx().tools.get('send_message')

      // B2: EXPLICIT noWake:true — the record persists 'prepared' and the dormant
      // head is NOT materialized/woken (the dormant recipient stays dormant).
      const result = await send.execute({ to: ['sleeper-head'], text: 'queue for later', noWake: true }, { agent: host, signal })
      assert.equal(result.delivered['sleeper-head'], 'prepared', 'noWake:true to a dormant recipient returns prepared (persisted, NOT woken)')
      // No wake = NO F8 rotation: the durable entry's sessionId is untouched (a wake
      // would update it to a fresh id) and the sleep mark is preserved.
      const postsAfterNoWake = await readPosts(stateDir)
      assert.equal(postsAfterNoWake['sleeper-head'].sessionId, 'head-sleeper-head', 'noWake does NOT materialize/rotate the dormant head (sessionId unchanged)')
      assert.equal(postsAfterNoWake['sleeper-head'].sleepEpoch !== undefined, true, 'the dormant head stays dormant (sleepEpoch preserved)')
      // The write-ahead + final sidecar row is 'prepared' (the pair stays pending-unwoken).
      assert.equal(await deliveryStatus(stateDir, result.messageId, 'sleeper-head'), 'prepared', 'the sidecar row is prepared (noWake leaves the pair pending-unwoken)')
      const records = await loadMessageRecords(resolveMessagesPath(stateDir))
      assert.equal(records.length, 1, 'the noWake send still persists its record')
      assert.equal(records[0].to[0], 'sleeper-head', 'the record targets the dormant recipient')

      // Default path (noWake absent): the SAME dormant head STILL ALWAYS wakes.
      const beforeWake = agents.createCalls.length
      const wake = await send.execute({ to: ['sleeper-head'], text: 'wake now' }, { agent: host, signal })
      assert.equal(wake.delivered['sleeper-head'], 'resumed', 'the default (noWake absent) send to a dormant head still ALWAYS wakes (resumed)')
      await waitFor(() => agents.createCalls.length > beforeWake, 5000, 'the default send materializes the dormant head')
      await waitFor(async () => (await readPosts(stateDir))['sleeper-head'].sleepEpoch === undefined, 5000, 'sleepEpoch cleared after the default wake')
    } finally {
      await dispose()
    }
  })
})

// legacy A+B: head sleep retired 2026-08-27 — kept for history (R6)
test.skip('B3 m-361 regression: a QD ack (ack:true) to a JUST-SLEPT head stays dormant (sleepEpoch preserved, NO materialize/wake) and the ack record persists as prepared (drains at the next real wake); a NON-ack send to the same dormant head still ALWAYS wakes it (the exempt work-delivery path); the head-slept DIRECTIVE to quality-head is STILL always-wake (emitted + delivered to the LIVE QH, never no-waked by B3)', async () => {
  await withTempStateDir(async (stateDir) => {
    const env = await bootWithQD(stateDir)
    try {
      const signal = new AbortController().signal
      const { head, headCtx, key } = qdResearchHead(env)

      // 1) Just-sleep the research head → dormant (sleepEpoch durable).
      const memo = headCtx.tools.get('dept_memo_write', key)
      await memo.execute({ summary: 'm-361 sleep memory.' }, { agent: head, signal })
      const sleep = headCtx.tools.get('dept_sleep', key)
      await withTimeout(sleep.execute({}, { agent: head, signal }), 1500, 'head dept_sleep returns (no self-deadlock wedge)')
      await waitFor(() => env.agents.store.has('head-research-head') === false, 5000, 'research head handle disposed after sleep')
      await waitFor(async () => (await readPosts(stateDir))['research-head'].sleepEpoch !== undefined, 5000, 'research head marked dormant')

      // 2) The QD ack (send_message ack:true) to the just-slept head — must NOT re-wake it (m-361).
      const host = env.agents.put(fakeParentAgent())
      const send = env.pluginCtx().tools.get('send_message')
      const ack = await send.execute({ to: ['research-head'], text: 'ack', ack: true }, { agent: host, signal })
      assert.equal(ack.delivered['research-head'], 'prepared', 'the ack to a just-slept head returns prepared (NOT re-woken)')
      assert.equal(await deliveryStatus(stateDir, ack.messageId, 'research-head'), 'prepared', 'the ack record persists as prepared (drains at the next real wake)')
      const postsAfterAck = await readPosts(stateDir)
      assert.equal(postsAfterAck['research-head'].sleepEpoch !== undefined, true, 'the just-slept head STAYS dormant (sleepEpoch NOT cleared)')

      // 3) A NON-ack send to the SAME dormant head STILL ALWAYS wakes it (the exempt
      //    work-delivery path — never no-wake a legitimate delivery).
      const beforeWake = env.agents.createCalls.length
      const work = await send.execute({ to: ['research-head'], text: 'work' }, { agent: host, signal })
      assert.equal(work.delivered['research-head'], 'resumed', 'a NON-ack send to a dormant head still ALWAYS wakes it (resumed)')
      await waitFor(() => env.agents.createCalls.length > beforeWake, 5000, 'the non-ack send materializes the dormant head')
      await waitFor(async () => (await readPosts(stateDir))['research-head'].sleepEpoch === undefined, 5000, 'sleepEpoch cleared after the non-ack wake')

      // 4) The head-slept DIRECTIVE to quality-head is STILL always-wake (the exempt
      //    path): emitted as a normal agent record (kind agent, NOT ack — so B3's
      //    `ack === true` condition never applies) and DELIVERED to the LIVE QH.
      await waitFor(async () => (await qualityDirectives(stateDir)).filter((d) => /head slept/.test(d.text)).length === 1, 5000, 'the head-slept directive to quality-head was emitted')
      const dirs = (await qualityDirectives(stateDir)).filter((d) => /head slept/.test(d.text))
      assert.equal(dirs.length, 1, 'exactly ONE head-slept directive was emitted')
      assert.equal(dirs[0].kind, 'agent', 'the directive is a normal agent record (kind agent, NOT ack) — B3 never no-wakes it')
      assert.equal(dirs[0].to.includes('quality-head'), true, 'the directive targets quality-head')
      const qh = env.agents.store.get('head-quality-head')
      assert.ok(qh, 'quality-head agent is live')
      await waitFor(() => qh.inboxMessages.some((m) => /head slept/.test(m.content[0].text)), 5000, 'the directive was delivered to the LIVE quality-head (always-wake, not queued prepared)')
    } finally {
      await env.dispose()
    }
  })
})

test('B2 send_message: child route FIRST — a direct continuable child is delivered natively (listChildren, never catalog-validated)', async () => {
  await withTempStateDir(async (stateDir) => {
    const { root, agents, pluginCtx, dispose } = await bootPlugin(stateDir)
    try {
      const host = agents.put(fakeParentAgent())
      const signal = new AbortController().signal
      // Establish a REAL continuable child of the caller through the REAL
      // SubagentRuntime continuation manager (stub provider prepares continuable
      // children; StubAgents materializes them with a real scoped ctx).
      const { childId } = await root.subagents.startContinuable({
        provider: 'spawn',
        label: 'b2-child',
        request: { parent: host, prompt: [{ type: 'text', text: 'initial prompt' }], maxDepth: 1 },
        signal
      })
      const child = agents.store.get(String(childId))
      assert.ok(child, 'continuable child materialized into the agents store')
      // The StubAgents.create ignores the factory `seed`, so the real store
      // session the child is entered under carries NO subagent/descriptor event
      // — the projection fold listChildren classifies on would serve no
      // identity. Mirror what the real agent factory writes at creation so the
      // child lists as mode:'continuable' (the child-route detection seam).
      const childSession = root.sessions.get(SessionId(childId))
      assert.ok(childSession, 'child entered in the real session store')
      childSession.append('subagent/descriptor', { version: 2, mode: 'continuable', provider: 'spawn', label: 'b2-child' })

      // The child id is NOT in the catalog — only the child route can reach it.
      const send = pluginCtx().tools.get('send_message')
      const result = await send.execute({ to: [String(childId)], text: 'continue' }, { agent: host, signal })
      assert.equal(result.delivered[String(childId)], 'delivered', 'child delivered through the native followup route')
      const childWake = child.inboxMessages.at(-1)
      assert.equal(childWake.content[0].text, '[From host-' + host.id + ' → ' + childId + ']: continue', 'child wake is framed like every bus delivery')
      assert.equal(childWake.source.kind, 'agent')
      assert.equal(childWake.source.senderSessionId, host.id)
    } finally {
      await dispose()
    }
  })
})

test('B2 agent_messages: paging 10-per-page with before cursor + remaining (20 seeded, newest-first, 11-20 via cursor)', async () => {
  await withTempStateDir(async (stateDir) => {
    const hostSessionId = SessionId('b2-host-page')
    const hostMemberId = `host-${hostSessionId}`
    const records = Array.from({ length: 20 }, (_, seq) => ({
      id: `m-${seq}`,
      seq,
      ts: 1700000000000 + seq,
      from: 'research-head',
      to: [hostMemberId],
      text: `message ${seq}`,
      kind: 'agent'
    }))
    await seedMessageRecords(stateDir, records)
    const { root, agents, pluginCtx, dispose } = await bootPlugin(stateDir)
    try {
      const host = agents.put(fakeParentAgent(SessionId('b2-host-page')))
      const signal = new AbortController().signal
      const messagesTool = pluginCtx().tools.get('agent_messages')

      // Page 1: newest 10 (m-19..m-10), 10 older remaining.
      const page1 = await messagesTool.execute({ limit: 10 }, { agent: host, signal })
      assert.equal(page1.total, 20, 'total is the caller-owned record count')
      assert.equal(page1.messages.length, 10)
      assert.deepEqual(page1.messages.map((message) => message.id), Array.from({ length: 10 }, (_, index) => `m-${19 - index}`), 'newest-first (m-19 … m-10)')
      assert.equal(page1.remaining, 10, 'remaining = exact older count (sparse-subset correct)')

      // Page 2 via cursor: records STRICTLY older than m-10 (m-9..m-0).
      const page2 = await messagesTool.execute({ limit: 10, before: 'm-10' }, { agent: host, signal })
      assert.deepEqual(page2.messages.map((message) => message.id), Array.from({ length: 10 }, (_, index) => `m-${9 - index}`), 'before cursor is exclusive')
      assert.equal(page2.remaining, 0, 'no older records below the oldest page')

      // Clamp rule: an unresolvable cursor (renumbered by a compaction) clamps
      // to the newest boundary — EXCLUSIVE at the newest record (the store's
      // implemented clamp §3.2, verified in messages-store.test.js:179): the
      // page restarts from the boundary instead of erroring.
      const pageClamped = await messagesTool.execute({ limit: 10, before: 'm-4049' }, { agent: host, signal })
      assert.deepEqual(pageClamped.messages.map((message) => message.id), Array.from({ length: 10 }, (_, index) => `m-${18 - index}`), 'missing cursor clamps to the newest boundary (exclusive); history still valid')

      // limit cap: 999 defensive-caps to 50 (store contract).
      const pageCapped = await messagesTool.execute({ limit: 999 }, { agent: host, signal })
      assert.equal(pageCapped.messages.length, 20, 'limit normalizes to the 50 max; 20 owned records served')
    } finally {
      await dispose()
    }
  })
})

test('F9 agent_messages result is JSON-lossless: threadId/sensitive keys omitted when absent, present when real — never undefined', async () => {
  await withTempStateDir(async (stateDir) => {
    const hostSessionId = SessionId('f9-host-lossless')
    const hostMemberId = `host-${hostSessionId}`
    // m-0: NO threadId, NO sensitive. m-1: threadId + sensitive:true.
    const records = [
      { id: 'm-0', seq: 0, ts: 1700000000000, from: 'research-head', to: [hostMemberId], text: 'no thread', kind: 'agent' },
      { id: 'm-1', seq: 1, ts: 1700000000001, from: 'research-head', to: [hostMemberId], text: 'with thread', kind: 'agent', threadId: 'm-0', sensitive: true }
    ]
    await seedMessageRecords(stateDir, records)
    const { agents, pluginCtx, dispose } = await bootPlugin(stateDir)
    try {
      const host = agents.put(fakeParentAgent(SessionId('f9-host-lossless')))
      const signal = new AbortController().signal
      const messagesTool = pluginCtx().tools.get('agent_messages')

      const page = await messagesTool.execute({ limit: 10 }, { agent: host, signal })
      assert.equal(page.total, 2, 'both records are owned')

      // (a) a record WITHOUT threadId/sensitive → those keys are ABSENT
      // (never `threadId: undefined`), and no message carries an undefined value.
      const noThread = page.messages.find((message) => message.id === 'm-0')
      assert.ok(noThread, 'm-0 present')
      assert.equal(Object.prototype.hasOwnProperty.call(noThread, 'threadId'), false, 'no threadId key when the record has none (NOT threadId: undefined)')
      assert.equal(Object.prototype.hasOwnProperty.call(noThread, 'sensitive'), false, 'no sensitive key when the record has no sensitive flag')

      // (b) a record WITH threadId/sensitive → the keys ARRIVE with real values.
      const withThread = page.messages.find((message) => message.id === 'm-1')
      assert.ok(withThread, 'm-1 present')
      assert.equal(withThread.threadId, 'm-0', 'threadId arrives as the real string')
      assert.equal(withThread.sensitive, true, 'sensitive arrives as the real boolean')

      // (c) the WHOLE result is JSON-lossless (no undefined/NaN/Infinity anywhere).
      assertLosslessJson(page)
      for (const message of page.messages) {
        assert.ok(Object.values(message).every((v) => v !== undefined), `message ${message.id} has no property with an undefined value`)
      }
    } finally {
      await dispose()
    }
  })
})

test('B2 dept_who: whole catalog — host + head rows with kind/title/live/sleeping/sessionId and you:true on the caller', async () => {
  await withTempStateDir(async (stateDir) => {
    const hostSessionId = SessionId('b2-host-who')
    await seedHostRegistration(stateDir, hostSessionId, 'board')
    const { root, agents, pluginCtx, dispose } = await bootPlugin(stateDir)
    try {
      await waitFor(() => agents.store.has('head-research-head'), 5000, 'head created at boot')
      const host = agents.put(fakeParentAgent(SessionId('b2-host-who')))
      const signal = new AbortController().signal

      const who = pluginCtx().tools.get('dept_who')
      const result = await who.execute({}, { agent: host, signal })
      assert.equal(result.members.length, 2, 'host + configured head')

      const hostRow = result.members.find((member) => member.agentId === `host-${hostSessionId}`)
      assert.equal(hostRow.kind, 'host', 'host row kind')
      assert.equal(hostRow.title, 'Asistente', 'host row title is Asistente')
      assert.equal(hostRow.live, true, 'host is live (agents.get defined)')
      assert.equal(hostRow.sleeping, false)
      assert.equal(hostRow.sessionId, String(hostSessionId), 'host sessionId is the registry session id')
      assert.equal(hostRow.you, true, 'host row marks the CALLER you:true')

      const headRow = result.members.find((member) => member.agentId === 'research-head')
      assert.equal(headRow.kind, 'head', 'head row kind')
      assert.equal(headRow.title, 'Research department head', 'title = coordinator.title (TEST_ORG coordinator.title is unset → role fallback… see note)')
      assert.equal(headRow.live, true, 'configured head is live at boot')
      assert.equal(headRow.sleeping, false)
      assert.equal(headRow.sessionId, 'head-research-head')
      assert.equal(headRow.you, false, 'only the caller is you')

      // The head's own view of the roster: you flips to the head.
      const head = agents.store.get('head-research-head')
      const { ctx: headCtx, key } = agents.childContexts[0]
      const headWho = headCtx.tools.get('dept_who', key)
      const headResult = await headWho.execute({}, { agent: head, signal })
      const headSelf = headResult.members.find((member) => member.agentId === 'research-head')
      assert.equal(headSelf.you, true, 'head own-layer dept_who marks the head you:true')
      const hostSelf = headResult.members.find((member) => member.agentId === `host-${hostSessionId}`)
      assert.equal(hostSelf.you, false)
    } finally {
      await dispose()
    }
  })
})

