test('A-series parity: dept_who with { scope: "includeRetired" } lists a RETIRED HOST row carrying retired:true (the host push carries the same retired parity as the worker push)', async () => {
  await withTempStateDir(async (stateDir) => {
    // A rotated v2 hosts.json: a LIVE host + a RETIRED host (retiredAt +
    // rotatedTo) — the exact shape dept_sleep/u2-rotation writes.
    const liveSessionId = SessionId('a-series-live-host')
    const retiredSessionId = SessionId('a-series-retired-host')
    await writeFile(path.join(stateDir, 'hosts.json'), JSON.stringify({
      schemaVersion: 2,
      [`host-${liveSessionId}`]: { sessionId: String(liveSessionId), roomId: 'board' },
      [`host-${retiredSessionId}`]: { sessionId: String(retiredSessionId), roomId: 'board', retired: true, retiredAt: 1787261781000, rotatedTo: `host-${liveSessionId}` }
    }, null, 2))
    const { agents, pluginCtx, dispose } = await bootPlugin(stateDir)
    try {
      await waitForHeadMaterialized(agents)
      // Caller is the LIVE registered host (so dept_who runs against the seeded
      // registry — no fresh self-registration, no retired entry mutated).
      const host = agents.put(fakeParentAgent(liveSessionId))
      const signal = new AbortController().signal
      const who = pluginCtx().tools.get('dept_who')
      const result = await who.execute({ scope: 'includeRetired' }, { agent: host, signal })
      const retiredRow = result.members.find((m) => m.kind === 'host' && m.agentId === `host-${retiredSessionId}`)
      assert.ok(retiredRow, 'A-series: includeRetired lists the retired HOST row')
      assert.equal(retiredRow.retired, true, 'A-series: the retired HOST row carries retired:true (host-push parity)')
      assert.equal(retiredRow.sessionId, String(retiredSessionId), 'A-series: the retired host row carries its session id')
      assert.equal(retiredRow.title, 'Asistente', 'A-series: the retired host row keeps the host title')
      // The LIVE host row must NOT carry a retired flag (conditioned spread).
      const liveRow = result.members.find((m) => m.kind === 'host' && m.agentId === `host-${liveSessionId}`)
      assert.ok(liveRow, 'A-series: the live host row is listed')
      assert.equal(liveRow.retired, undefined, 'A-series: the live host row carries no retired flag')
      // Regression guard: the DEFAULT `active` scope still HIDES the retired host.
      const active = await who.execute({}, { agent: host, signal })
      assert.equal(active.members.some((m) => m.kind === 'host' && m.agentId === `host-${retiredSessionId}`), false, 'A-series: default `active` scope HIDES the retired host')
    } finally {
      await dispose()
    }
  })
})

test('B2 send_message: the unified implementation is the ONE bound after the override — native control tool owns the global name, deepartments agents still get the unified UNIFIED (to array works, native error absent)', async () => {
  await withTempStateDir(async (stateDir) => {
    // Compose the REAL harness control plugin (dsh-tool-subagent-control: the
    // native global send_message) BEFORE the deepartments row — exactly the
    // GUI/headless composition. The plugin must NOT throw at apply (no global
    // duplicate) and must shadow the native per-agent own-layer.
    const overrideHostSessionId = SessionId('b2-host-override')
    await seedHostRegistration(stateDir, overrideHostSessionId, 'board')
    const { root, agents, pluginCtx, dispose } = await bootPlugin(stateDir, { nativeControlTool: true })
    try {
      await waitFor(() => agents.store.has('head-research-head'), 5000, 'head created at boot')

      // The GLOBAL name is the NATIVE one (dsh-base owns it): its schema is
      // the adapter shape, not the unified one.
      const globalSend = pluginCtx().tools.get('send_message')
      assert.ok(globalSend, 'send_message exists on the host plane')
      assert.equal(globalSend.parameters.properties.subagent_id !== undefined, true, 'global send_message is the NATIVE adapter (subagent_id schema)')
      assert.equal(typeof globalSend.parameters.properties.to, 'undefined', 'global layer still holds the native tool, not the unified one')

      // The HEAD own layer carries the UNIFIED tool (scoped shadow — the
      // harness-supported override: duplicate in one layer throws, so a scoped
      // registration that SHADOWS the global is the valid seam).
      const { ctx: headCtx, key } = agents.childContexts[0]
      const headSend = headCtx.tools.get('send_message', key)
      assert.ok(headSend, 'unified send_message installed in the head own layer')
      assert.equal(headSend.parameters.properties.to !== undefined, true, 'own-layer send_message is the UNIFIED one (to[] schema)')
      assert.equal(typeof headSend.parameters.properties.subagent_id, 'undefined', 'own-layer send_message is NOT the native adapter')

      // The unified bound implementation WORKS: to[] array against a catalog
      // id delivers — the native error (subagent_id required/continuable-only)
      // never surfaces.
      const head = agents.store.get('head-research-head')
      const host = agents.put(fakeParentAgent(SessionId('b2-host-override')))
      const signal = new AbortController().signal
      const result = await headSend.execute({ to: [`host-${host.id}`], text: 'reply to host' }, { agent: head, signal })
      assert.equal(result.delivered[`host-${host.id}`], 'delivered', 'unified tool delivers via the catalog (host live, followup inline)')
      const wake = host.inboxMessages.at(-1)
      assert.equal(wake.content[0].text, '[From research-head → host-' + host.id + ']: reply to host', 'unified framing')
      assert.equal(wake.source.kind, 'agent')
    } finally {
      await dispose()
    }
  })
})

// --- F3 (spec 004 §5.1-§5.3, §7.4): worker-management tools -----------------
// dept_worker_spawn (head own-layer ONLY: role template → worker root agent
// with departmentId/managerId/role/jobId, persona + task injection, title pin,
// slug dedup incl. retired) and dept_worker_retire (scope + retired mark +
// archiveSession so the sidebar row disappears), plus the dept_who row
// extension (departmentId/role/jobId; RETIRED workers stay listed with
// retired:true while the LIVE catalog keeps filtering them).

/** Boot the research department + a second department (programming) — the F3
 * cross-department scope tests need another head. Mirrors f2BootWithTwoHeads
 * (deliberately re-declared here so the F3 tests never depend on the F2 test
 * zone). */
async function f3BootWithTwoHeads(stateDir) {
  const env = await bootPlugin(stateDir, { org: TWO_DEPT_ORG })
  await waitFor(() => env.agents.store.has('head-research-head'), 5000, 'research head materialized at boot')
  await waitFor(() => env.agents.store.has('head-programming-head'), 5000, 'programming head materialized at boot')
  const researchHead = env.agents.store.get('head-research-head')
  const programmingHead = env.agents.store.get('head-programming-head')
  const researchCtx = childContextFor(env.agents, 'head-research-head')
  const programmingCtx = childContextFor(env.agents, 'head-programming-head')
  return { ...env, researchHead, programmingHead, researchKey: researchCtx.key, programmingKey: programmingCtx.key, researchCtx: researchCtx.ctx, programmingCtx: programmingCtx.ctx }
}

/** Spawn via the head own-layer dept_worker_spawn and wait for the worker
 * agent to be live. Returns the tool result + the live worker + its scoped
 * toolset. */
async function f3Spawn(env, headCtx, key, head, args) {
  const signal = new AbortController().signal
  const result = await headCtx.tools.get('dept_worker_spawn', key).execute(args, { agent: head, signal })
  await waitFor(() => env.agents.store.has(result.sessionId), 5000, `worker ${result.workerId} live`)
  const worker = env.agents.store.get(result.sessionId)
  const wctx = childContextFor(env.agents, result.sessionId)
  return { result, worker, ctx: wctx.ctx, key: wctx.key, signal }
}

test('F3 dept_worker_spawn: a head spawns a worker of its department (role template → persona + task, departmentId/managerId/role/jobId, title pin, first bus message) — and the host plane has NO dept_worker_spawn', async () => {
  await withTempStateDir(async (stateDir) => {
    const { root, agents, head, headCtx, key, dispose } = await bootWithHead(stateDir)
    try {
      assert.ok(headCtx.tools.get('dept_worker_spawn', key), 'dept_worker_spawn installed in the head own layer')
      // D2: structural — the host plane never sees the spawn tool (the
      // Asistente never mints research workers).
      assert.equal(root.tools.get('dept_worker_spawn'), undefined, 'host plane has NO dept_worker_spawn')

      const { result, worker, key: workerKey } = await f3Spawn({ agents, root }, headCtx, key, head, {
        role: 'researcher',
        task: 'track DSH updates and report',
        jobId: 'monitor-dsh-updates'
      })
      assert.equal(result.workerId, 'monitor-dsh-updates', 'slug = jobId when given (job worker)')
      assert.match(result.sessionId, /^worker-monitor-dsh-updates-[0-9a-f-]+$/, 'the worker mints a UNIQUE session id (worker-<slug>-<uuid>), never the deterministic worker-<slug>')
      const workerSid = result.sessionId
      // This title ONLY exists if the role template file was READ + its
      // frontmatter parsed (the deterministic proof of the persona-loading
      // mechanism — "Researcher" comes from presets/departments/research/
      // researcher.md frontmatter, not from code).
      assert.equal(result.title, 'Researcher: track DSH updates and report', 'default title = "<RoleTitle>: <task>" (role template title)')

      // Durable entry: provider/role/manager/department/jobId (spec §4.1/§5.2).
      const posts = await readPosts(stateDir)
      const entry = posts['monitor-dsh-updates']
      assert.equal(entry.provider, 'worker')
      assert.equal(entry.role, 'researcher', 'role = the role TEMPLATE id')
      assert.equal(entry.managerId, 'research-head', 'managerId = the creating head ("my workers")')
      assert.equal(entry.departmentId, 'research', 'departmentId = the creating head config department')
      assert.equal(entry.jobId, 'monitor-dsh-updates')
      assert.equal(entry.sessionId, workerSid, 'the durable registry entry.sessionId = the UNIQUE minted session id')

      // The worker agent is live and its FIRST bus message is the task.
      await waitFor(() => worker.inboxMessages.length >= 1, 5000, 'worker woken by its first bus message')
      assert.match(worker.inboxMessages.at(-1).content[0].text, /track DSH updates and report/, 'the task arrives as the first durable bus message')

      // Title pin: user-kind session/title on the worker session (sidebar row).
      const workerSession = root.sessions.get(SessionId(workerSid))
      assert.ok(workerSession !== undefined, 'the worker session is entered in the real sessions store')
      const title = workerSession.events.find((ev) => ev.type === 'session/title')
      assert.ok(title !== undefined, 'dept_worker_spawn pinned a session/title event')
      assert.equal(title.data.title, 'Researcher: track DSH updates and report')
      assert.deepEqual(title.data.source, { kind: 'user' }, 'the pin is user-source (the owner manual rename always wins)')

      // F7 (provider migration): the spawned worker is created with the
      // coordinator-aligned agentOptions — a discriminating assert on the
      // runtime materialization route (opencode-zen / vision-exp / max).
      const spawnCall = agents.createCalls.find((c) => String(c.sessionId) === workerSid)
      assert.ok(spawnCall, 'dept_worker_spawn issued one ctx.agents.create for the worker')
      assert.deepEqual(spawnCall.agentOptions, { provider: 'opencode-zen', model: 'deepseek-v4-flash', reasoningEffort: 'max' }, 'dept_worker_spawn worker agentOptions = opencode-zen / deepseek-v4-flash / reasoningEffort max (coordinator alignment)')

      // F3 persona mechanism (spec §7.4): the ROLE TEMPLATE body + the task are
      // injected as a systemPrompt section (the persona delta; the worker still
      // mounts the base deepartments-worker preset). The section surfacing via
      // assemble is BEST-EFFORT in this stub harness (the Fix A1 head test
      // guards the same seam — "a scope-less assemble may not surface it"), so
      // the content is asserted only when the section did surface; the static
      // proof is the title above (frontmatter-parsed) + the entry.role.
      const sp = worker.ctx?.get('systemPrompt')
      if (sp !== void 0 && typeof sp.assemble === 'function') {
        const assembly = await sp.assemble({ scope: workerKey })
        const persona = (assembly.sections ?? []).find((s) => s.name === 'deepartments:worker:role-persona:monitor-dsh-updates')
        if (persona !== undefined) {
          assert.match(persona.text, /You are a \*\*researcher\*\* of the \*\*Research Department\*\*/, 'the role persona body came from presets/departments/research/researcher.md')
          assert.match(persona.text, /track DSH updates and report/, 'the task is injected with the persona')
        }
        const roleSection = (assembly.sections ?? []).find((s) => s.name === 'deepartments:worker:role:monitor-dsh-updates')
        if (roleSection !== undefined) {
          assert.match(roleSection.text, /dept_worker_retire/, 'the worker framing names the NEW retire tool')
        }
      }
    } finally {
      await dispose()
    }
  })
})

test('F3 gates: a worker agent has NO dept_worker_spawn/dept_worker_retire, and an unknown role template rejects loudly', async () => {
  await withTempStateDir(async (stateDir) => {
    const { agents, head, headCtx, key, dispose } = await bootWithHead(stateDir)
    try {
      const { worker, ctx: workerCtx, key: workerKey } = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'check something' })

      // A worker never sees the department-lifecycle tools (manager:false).
      assert.equal(workerCtx.tools.get('dept_worker_spawn', workerKey), undefined, 'worker has NO dept_worker_spawn')
      assert.equal(workerCtx.tools.get('dept_worker_retire', workerKey), undefined, 'worker has NO dept_worker_retire')

      // A role without a template file fails LOUD (never a persona-less worker).
      await assert.rejects(
        () => headCtx.tools.get('dept_worker_spawn', key).execute({ role: 'nonexistent-role', task: 'x' }, { agent: head, signal: new AbortController().signal }),
        /no template at .*presets\/departments\/research\/nonexistent-role\.md/, 'a role that is not a file in the department template tree rejects'
      )
      assert.equal(agents.store.has('worker-nonexistent-role'), false, 'no agent is created for the failed spawn')
    } finally {
      await dispose()
    }
  })
})

// ===========================================================================
// F10 (spec 004 §7.1 real role→tools binding, §9.1 department-architecture
// injection) — discriminating tests.
// ===========================================================================

/** The repo-root path (the plugin resolves presets/departments/<id>/ against
 * it; lib/ and test/ are both one level below the root, so the same
 * derivation yields the root). */
const F10_REPO_ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..')
/** The department ARCHITECTURE.md the research department's posts read (spec
 * 004 §9.1). The "exists" tests write + clean it up as a fixture (the read
 * path is fixed at repo presets/departments/research/); the "absent" test
 * relies on it NOT existing. */
const F10_ARCHITECTURE_PATH = path.join(F10_REPO_ROOT, 'presets', 'departments', 'research', 'ARCHITECTURE.md')
/** The GLOBAL harness capability tools a department post can inherit (the
 * minimal composition registers no native tools, so the tests stub them on the
 * global plane BEFORE boot, exactly as the host profile composes them). */
const F10_GLOBAL_TOOLS = ['web_search', 'web_fetch', 'read', 'write', 'glob', 'grep', 'edit']

/** Pristine content of ONE repo preset file FROM GIT HEAD (fb-33): returns the
 * exact HEAD bytes of a tracked file, `{ kind: 'absent' }` for a path NOT in
 * HEAD (its pristine worktree state is absence — e.g. the untracked execbuilder
 * fixture), or `undefined` when git itself is unavailable (non-git checkout) —
 * the fallback then keeps the pre-fb-33 worktree-snapshot semantics so the
 * tests still pass on a plain checkout. The snapshot is NEVER taken from the
 * worktree file: an interrupted run may have already corrupted that file (the
 * fb-33 pattern — the old snapshot captured the corruption AS the "original",
 * so the finally-restore "repaired" the corruption back into the worktree). A
 * git-HEAD snapshot can never be the corruption, so the restore ALWAYS returns
 * the file to its HEAD state. */
function gitHeadPresetContent(relPath) {
  try {
    const out = execFileSync('git', ['-C', F10_REPO_ROOT, 'show', `HEAD:${relPath}`], { encoding: 'utf8', maxBuffer: 4 * 1024 * 1024, stdio: ['ignore', 'pipe', 'pipe'] })
    return { kind: 'content', data: out }
  } catch (err) {
    const stderr = String(err?.stderr ?? err?.message ?? '')
    if (/does not exist in 'HEAD'|path '.*' does not exist/.test(stderr)) return { kind: 'absent' }
    return undefined
  }
}

/** Snapshot the department ARCHITECTURE.md (its content, or absence) BEFORE an
 * injection fixture writes/removes the REAL preset file, so running the tests
 * never destroys a pre-existing ARCHITECTURE.md. Returns a restore() that
 * rewrites the ORIGINAL HEAD content if the file is tracked, or removes the
 * file when HEAD does not carry it — the exact pre-test state is restored in
 * every case. fb-33: the snapshot is taken from GIT HEAD (gitHeadPresetContent),
 * never from the worktree file — a file ALREADY corrupted by an interrupted
 * run is HEALED to HEAD on restore instead of being "repaired" with its own
 * corruption. */
async function snapshotArchitectureFile() {
  const relPath = 'presets/departments/research/ARCHITECTURE.md'
  const head = gitHeadPresetContent(relPath)
  if (head !== undefined) {
    // Pristine = git HEAD: tracked file → its exact bytes; absent in HEAD →
    // the file must not exist in the worktree after the test (fb-33 heal).
    return async function restoreArchitectureFile() {
      if (head.kind === 'content') await writeFile(F10_ARCHITECTURE_PATH, head.data, 'utf8')
      else await rm(F10_ARCHITECTURE_PATH, { force: true })
    }
  }
  // Fallback (no git, e.g. a plain checkout): snapshot the CURRENT worktree
  // file BEFORE any fixture write (pre-fb-33 semantics) and restore exactly it.
  let content = null
  try {
    content = await readFile(F10_ARCHITECTURE_PATH, 'utf8')
  } catch (err) {
    if (err?.code !== 'ENOENT') throw err
  }
  return async function restoreArchitectureFile() {
    if (content === null) await rm(F10_ARCHITECTURE_PATH, { force: true })
    else await writeFile(F10_ARCHITECTURE_PATH, content, 'utf8')
  }
}

test('fb-33 (crash-safety): the preset-fixture snapshot is git-HEAD-based — a worktree ARCHITECTURE.md ALREADY corrupted by an interrupted run (byte-different from HEAD) is HEALED to its exact HEAD bytes on restore, NEVER "repaired" with its own corruption; the untracked execbuilder fixture resolves to absence', async () => {
  // The fb-33 precondition: an interrupted run left the REAL preset file
  // corrupted in the worktree (differs from HEAD). The snapshot must NOT capture
  // this corruption — it must capture the git-HEAD bytes, so the restore returns
  // the file to its HEAD state (the old worktree snapshot would have snapshotted
  // the already-corrupted file and RE-WRITTEN the corruption on "restore").
  const head = gitHeadPresetContent('presets/departments/research/ARCHITECTURE.md')
  assert.notEqual(head, undefined, 'git HEAD resolves the tracked ARCHITECTURE.md (the crash-safe path is active)')
  assert.equal(head.kind, 'content', 'ARCHITECTURE.md is tracked at HEAD')
  const corrupt = '# fb-33 CORRUPTED BY AN INTERRUPTED RUN\n## Department architecture\n'
  await writeFile(F10_ARCHITECTURE_PATH, corrupt, 'utf8')
  const restore = await snapshotArchitectureFile()
  try {
    await restore()
    const healed = await readFile(F10_ARCHITECTURE_PATH, 'utf8')
    assert.equal(healed, head.data, 'the restore heals the corrupted worktree file to the EXACT git-HEAD bytes')
    assert.notEqual(healed, corrupt, 'the corruption is NOT what comes back (the old worktree snapshot would have re-persisted it)')
  } finally {
    // Absolute finally: even a mid-test failure returns the REAL file to HEAD.
    await restore()
    assert.equal(await readFile(F10_ARCHITECTURE_PATH, 'utf8'), head.data, 'the file is byte-identical to HEAD after the absolute finally')
  }
  // The untracked execbuilder role fixture: its pristine HEAD state is ABSENCE
  // (the file is a test-only fixture, never part of the repo tree).
  const execHead = gitHeadPresetContent('presets/departments/research/execbuilder.md')
  assert.equal(execHead.kind, 'absent', 'the untracked execbuilder fixture resolves to kind:"absent" at HEAD (restore removes it, never leaves it behind)')
})

/** Read ONE systemPrompt section by name for a post's scoped context. */
async function findPromptSection(ctx, key, sectionName, useScope) {
  const sp = ctx?.get('systemPrompt')
  if (sp === void 0 || typeof sp.assemble !== 'function') return undefined
  try {
    const assembly = await sp.assemble(useScope ? { scope: key } : {})
    return (assembly.sections ?? []).find((s) => s.name === sectionName)
  } catch {
    return undefined
  }
}

test('F10 (spec 004 §7.1): a worker inherits its role template REAL GLOBAL tools via the restrict allow-list (web_search/read/write/glob/grep), keeps the bus/ciclo tools visible, GATES `edit` by role presence (only a DECLARING role gets it), and denies the subagent lifecycle controls', async () => {
  await withTempStateDir(async (stateDir) => {
    const { agents, root, head, headCtx, key, dispose } = await bootWithHead(stateDir, { globalTools: F10_GLOBAL_TOOLS })
    try {
      // Sanity: the global stubs exist on the host plane (the inherited surface).
      for (const name of ['web_search', 'web_fetch', 'read', 'write', 'glob', 'grep', 'edit']) assert.ok(root.tools.get(name), `host plane exposes the global stub ${name}`)

      // The researcher role template declares web_search/web_fetch/read/write/
      // glob/grep + the bus tools → the worker's allow-list is the declared
      // tools that exist as GLOBALS (visible), bus/ciclo are own-layer exempt.
      // researcher does NOT declare `edit` → it never sees it (role-gated, not
      // a hard deny-set anymore).
      const researcher = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'investigate X' })
      const r = researcher.result
      for (const name of ['web_search', 'web_fetch', 'read', 'write', 'glob', 'grep']) {
        assert.ok(researcher.ctx.tools.get(name, researcher.key), `researcher worker "${r.workerId}" inherits the global role tool ${name}`)
      }
      for (const name of ['send_message', 'agent_messages', 'dept_who', 'dept_memo_write']) {
        assert.ok(researcher.ctx.tools.get(name, researcher.key), `researcher worker "${r.workerId}" still sees the bus/ciclo tool ${name}`)
      }
      assert.equal(researcher.ctx.tools.get('edit', researcher.key), undefined, 'researcher has NO edit (role does not declare it)')
      assert.equal(researcher.ctx.tools.get('dept_worker_spawn', researcher.key), undefined, 'researcher has NO dept_worker_spawn')

      // The organizer role template DECLARES `edit` — OWNER DECISION (2026-08-23):
      // `edit` is NOT a hard deny; it flows through the role allow-list like any
      // other tool, so a role that DECLARES it INHERITS it. organizer DECLARES
      // it → it HAS it.
      const organizer = await f3Spawn({ agents }, headCtx, key, head, { role: 'organizer', task: 'organize reports' })
      for (const name of ['read', 'write', 'edit', 'glob', 'grep']) {
        assert.ok(organizer.ctx.tools.get(name, organizer.key), `organizer worker "${organizer.result.workerId}" inherits the file tool ${name}`)
      }
      assert.equal(organizer.ctx.tools.get('web_search', organizer.key), undefined, 'organizer does NOT inherit web_search (not declared)')

      // A reviewer (role template WITHOUT `edit`) → NO edit, mirroring researcher.
      const reviewer = await f3Spawn({ agents }, headCtx, key, head, { role: 'reviewer', task: 'review a report' })
      assert.equal(reviewer.ctx.tools.get('edit', reviewer.key), undefined, 'reviewer has NO edit (role does not declare it)')
      assert.equal(reviewer.ctx.tools.get('subagent', reviewer.key), undefined, 'reviewer has NO subagent (hard-denied)')
    } finally {
      await dispose()
    }
  })
})

