// VALLE lane B — the LEGACY board-only class + the fb-29 loud guard. A legacy
// dept_post_create worker (FREE-FORM role with NO template file) keeps its
// board-only/messaging-only BY-DESIGN toolset (never a failure — the documented
// legacy residue); a ROLE-TEMPLATE worker whose template EXISTS but resolves an
// EMPTY tool-scope FAILS the cold re-spawn loudly (the original fb-29 invariant
// — never a silently messaging-only worker). The guard role is written under
// the RESEARCH department tree (the fixture discipline: snapshot + restore).
const VALLEB_GUARD_ROLE = 'valleb-coldguard'
const VALLEB_GUARD_ROLE_PATH = path.join(F10_REPO_ROOT, 'presets', 'departments', 'research', `${VALLEB_GUARD_ROLE}.md`)
const VALLEB_GUARD_FRONTMATTER = `---\nid: ${VALLEB_GUARD_ROLE}\ntitle: Empty scope (VALLE B guard)\ntools:\n---\n\nYou are an empty-scope guard worker.\n`

test('VALLE lane B (fb-29 structural fix): a legacy dept_post_create worker (free-form role, NO template file) cold-re-materializes UNCHANGED — board-only BY DESIGN, never a failure; and a ROLE-TEMPLATE worker whose template EXISTS with an EMPTY tool-scope FAILS the cold re-spawn LOUDLY (never a silent messaging-only worker — the fb-29 invariant)', async () => {
  // (1) the LEGACY class: free-form role 'legacy worker A' with the research
  // department (the role has NO template file → the A reader returns undefined
  // → no tools → the pre-fix board-only setup byte-identical).
  await withTempStateDir(async (stateDir) => {
    const sessionId = 'worker-legacy-valle-cccccccc'
    await seedPost(stateDir, { postId: 'legacy-valle', sessionId, roomId: 'board', agentPreset: 'deepartments-worker', provider: 'worker', role: 'legacy worker A', departmentId: 'research', managerId: 'research-head' })
    const { root, agents, dispose } = await bootPlugin(stateDir, { globalTools: F10_GLOBAL_TOOLS })
    try {
      const host = agents.put(fakeParentAgent())
      const signal = new AbortController().signal
      const r = await root.tools.get('send_message').execute({ to: ['legacy-valle'], text: 'wake the legacy worker' }, { agent: host, signal })
      assert.equal(r.delivered['legacy-valle'], 'resumed', 'a legacy board-only worker still cold-resumes (no failure — documented legacy residue)')
      await waitFor(() => agents.store.has(sessionId), 5000, 'the legacy worker is live')
      const { ctx: workerCtx, key: workerKey } = childContextFor(agents, sessionId)
      // Board-only BY DESIGN: no capability tools, only the bus/ciclo own-layer.
      assert.equal(workerCtx.tools.get('web_search', workerKey), undefined, 'legacy board-only worker still has NO web_search (messaging-only by design, unchanged)')
      for (const name of ['send_message', 'agent_messages', 'dept_who', 'dept_memo_write']) {
        assert.ok(workerCtx.tools.get(name, workerKey), `legacy board-only worker still sees the bus/ciclo tool ${name}`)
      }
    } finally {
      await dispose()
    }
  })
  // (2) the fb-29 GUARD: a role-template worker whose template EXISTS but has
  // an EMPTY tools list must NOT be silently re-materialized messaging-only —
  // the cold re-spawn fails loudly (the delivery maps to 'failed' + a durable
  // post-error row naming role/entry/cause).
  const restore = await snapshotRoleTemplate(VALLEB_GUARD_ROLE)
  try {
    await writeFile(VALLEB_GUARD_ROLE_PATH, VALLEB_GUARD_FRONTMATTER, 'utf8')
    await withTempStateDir(async (stateDir) => {
      const sessionId = 'worker-valle-guard-dddddddd'
      await seedPost(stateDir, { postId: 'valle-guard', sessionId, roomId: 'board', agentPreset: 'deepartments-worker', provider: 'worker', role: VALLEB_GUARD_ROLE, departmentId: 'research', managerId: 'research-head' })
      const { root, agents, dispose } = await bootPlugin(stateDir, { globalTools: F10_GLOBAL_TOOLS })
      try {
        const host = agents.put(fakeParentAgent())
        const signal = new AbortController().signal
        const r = await root.tools.get('send_message').execute({ to: ['valle-guard'], text: 'wake the empty-scope worker' }, { agent: host, signal })
        assert.equal(r.delivered['valle-guard'], 'failed', 'the empty-scope role-template worker FAILS the cold re-spawn loudly (fb-29 guard)')
        assert.equal(agents.resumeCalls.some((c) => String(c.resumeSessionId) === sessionId), false, 'NO agents.resume ran (the guard fires BEFORE any materialization)')
        assert.equal(agents.store.has(sessionId), false, 'the empty-scope worker is NOT materialized')
        const rows = readPostErrorsFile(stateDir).filter((r0) => r0.postId === 'valle-guard')
        assert.ok(rows.some((r0) => /cold re-materialization of worker "valle-guard" \(role "valleb-coldguard", dept "research"\) refused: the role template .*resolves an EMPTY tool scope/.test(r0.error)), 'the delivery failure names role + entry + cause (the fb-29 guard message) in the durable post-error row')
      } finally {
        await dispose()
      }
    })
  } finally {
    await restore()
  }
})

test('F10 (spec 004 §7.1): a department HEAD inherits the head base tools (read/write/glob/grep/web_search/web_fetch) + its own-layer board/lifecycle tools, and never edit', async () => {
  await withTempStateDir(async (stateDir) => {
    const { agents, root, head, headCtx, key, workspaceRegistry, dispose } = await bootWithHead(stateDir, { globalTools: F10_GLOBAL_TOOLS })
    const signal = new AbortController().signal
    try {
      // The booted head's OWN-LAYER board + department-lifecycle tools are
      // always visible (exempt from the mask) — asserted on the booted context.
      // LOTE A (2026-08-27): dept_sleep is RETIRED from the own layer — not asserted.
      for (const name of ['send_message', 'agent_messages', 'dept_who', 'dept_memo_write', 'dept_worker_spawn', 'dept_worker_retire', 'dept_post_create', 'dept_post_retire', 'dept_job_run', 'dept_job_list']) {
        assert.ok(headCtx.tools.get(name, key), `department head sees its own-layer tool ${name}`)
      }
      assert.equal(headCtx.tools.get('edit', key), undefined, 'department head has NO edit (never granted)')
      // The INHERITED surface (read/web_search) only lands where the head setup
      // ran AFTER the globals were registered — the booted head materialized at
      // boot (before the post-boot global registration), so a wake ROTATES it to
      // a FRESH session whose setup IS post-globals. LOTE A (2026-08-27): head
      // dept_sleep is RETIRED — the rotation is driven through the ARCHIVE-LEAK
      // path (P2) instead: a head whose durable session id is in the workspace
      // registry's archived set is rotated to a FRESH session on its next bus
      // wake (never resumed).
      await headCtx.tools.get('dept_memo_write', key).execute({ summary: 'rotate to expose inherited head tools' }, { agent: head, signal })
      agents.store.delete('head-research-head')
      if (!workspaceRegistry.archived.includes('head-research-head')) workspaceRegistry.archived.push('head-research-head')
      const r = await root.tools.get('send_message').execute(
        { to: ['research-head'], text: 'wake' },
        { agent: { id: 'host-any', session: { header: {} } }, signal }
      )
      assert.equal(r.delivered['research-head'], 'resumed', 'bus wake of the archived-session head reports resumed')
      await waitFor(() => agents.createCalls.length > 1, 5000, 'a fresh head session was created on wake (rotation)')
      const fresh = childContextFor(agents, String(agents.createCalls.at(-1).sessionId))
      assert.ok(fresh !== undefined, 'the re-materialized (fresh) head context resolves')
      for (const name of ['read', 'write', 'glob', 'grep', 'web_search', 'web_fetch']) {
        assert.ok(fresh.ctx.tools.get(name, fresh.key), `re-materialized department head inherits the head base tool ${name}`)
      }
      assert.equal(fresh.ctx.tools.get('edit', fresh.key), undefined, 're-materialized department head has NO edit (never granted)')
    } finally {
      await dispose()
    }
  })
})

// F10 live-layout regression (2026-08-23): in the REAL dsh agent-preset
// composition the model-facing capability tools (read/write/glob/grep/
// web_search/web_fetch) are an ANCESTOR contribution behind the base preset's
// `isolate` realm — the host GLOBAL layer is EMPTY of them, so the pre-fix
// probe `ctx.tools.get(name)` (the host GLOBAL view) resolved every declared
// capability tool to undefined and degraded the post to board-only (the F10
// runtime symptom). These two tests replicate that layout — an ancestor scope
// bound as the agent scope's PARENT, with the model tools registered THERE and
// not on the global root — and prove the allow-list is now sourced from the
// AGENT scope.
test('F10 (spec 004 §7.1): in the LIVE agent-preset layout the model tools are an ANCESTOR contribution — the allow-list must be sourced from the AGENT scope, not the host GLOBAL layer (a host-global probe degrades the post to board-only)', async () => {
  await withTempStateDir(async (stateDir) => {
    // NO globalTools: the host global layer is empty of model capabilities (the
    // live dsh base preset keeps them behind an `isolate` realm on the agent plane).
    const { agents, head, headCtx, key, root, dispose } = await bootWithHead(stateDir)
    try {
      // Replicate the base agent preset's standing `isolate` realm: a SCOPED
      // ancestor scope that carries the model capability tools.
      const ancestorKey = Symbol('base-agent-preset-isolate')
      const ancestor = createScope(agents.scopeAnchor, ancestorKey)
      for (const name of ['web_search', 'web_fetch', 'read', 'write', 'glob', 'grep']) ancestor.ctx.tools.register(stubGlobalTool(name))
      // Every agent materialized from here on inherits that ancestor.
      agents.scopeParentKey = ancestorKey
      // Sanity — the live bug: the host GLOBAL layer is empty of model tools,
      // so the plugin's pre-fix global-view probe would resolve them to undefined.
      for (const name of ['web_search', 'read', 'write']) {
        assert.equal(root.tools.get(name), undefined, `host global layer has NO ${name} (model tools are an ancestor contribution, as in the live preset layout)`)
      }
      // A researcher declares web_search/web_fetch/read/write/glob/grep + the bus
      // tools → the allow-list must carry the AGENT-scope (ancestor) capabilities.
      const researcher = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'investigate X' })
      for (const name of ['web_search', 'web_fetch', 'read', 'write', 'glob', 'grep']) {
        assert.ok(researcher.ctx.tools.get(name, researcher.key), `researcher inherits the AGENT-scope (ancestor) tool ${name}`)
      }
      assert.equal(researcher.ctx.tools.get('edit', researcher.key), undefined, 'researcher has NO edit (the role does not declare it)')
    } finally {
      await dispose()
    }
  })
})

test('F10 (spec 004 §7.1): a role that DECLARES the own-layer bus/lifecycle tools does NOT crash the restrict — the own-layer names are excluded (never named in the allow-list), the inherited model tools are conserved, and the own-layer bus tools stay visible', async () => {
  await withTempStateDir(async (stateDir) => {
    const { agents, head, headCtx, key, dispose } = await bootWithHead(stateDir)
    try {
      const ancestorKey = Symbol('base-agent-preset-isolate')
      const ancestor = createScope(agents.scopeAnchor, ancestorKey)
      for (const name of ['web_search', 'web_fetch', 'read', 'write', 'glob', 'grep']) ancestor.ctx.tools.register(stubGlobalTool(name))
      agents.scopeParentKey = ancestorKey
      // The researcher template declares the bus tools (send_message/...)
      // ALONGSIDE the capability tools; the allow-list must exclude the own-layer
      // names so restrict never throws "scope-local name" and degrades to allow:[].
      const researcher = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'investigate X' })
      // restrict did NOT degrade to allow:[] — the inherited model tools are conserved.
      for (const name of ['web_search', 'web_fetch', 'read', 'write', 'glob', 'grep']) {
        assert.ok(researcher.ctx.tools.get(name, researcher.key), `researcher conserves the inherited tool ${name} (restrict did not fall to allow:[])`)
      }
      // The own-layer bus/lifecycle tools are exempt from the mask — still visible.
      for (const name of ['send_message', 'agent_messages', 'dept_who', 'dept_memo_write']) {
        assert.ok(researcher.ctx.tools.get(name, researcher.key), `researcher still sees the own-layer bus tool ${name}`)
      }
    } finally {
      await dispose()
    }
  })
})

// F10 preset-mount ORDERING regression (2026-08-23): the earlier live-layout
// tests (the "ANCESTOR contribution" pair above) bound the ancestor scope as the
// agent scope's PARENT BEFORE spawn — simulating a post-mount ancestor, which
// HIDES the real timing bug. At runtime the mount() BIND happens INSIDE setup
// (agentPresets.mount), AFTER postSetup's capability probe. This test replicates
// the REAL order — the preset standing scope is bound DURING setup, via the
// agentPresets service — and proves the probe runs AFTER the (awaited) mount, so
// a post inherits read/write/glob/grep/web_search/web_fetch even though they are
// PRESET-ONLY (the host global layer is empty of them, as the web profile
// disables the base tool-fs/tool-fs-search). It FAILS if the probe runs before
// the mount (the pre-fix order): a pre-mount probe sees no fs tools (the agent
// scope is not yet parented to the standing scope) and drops them from the
// allow-list, which restrict() then masks.
test('F10 (spec 004 §7.1): the preset mount is AWAITED BEFORE the capability probe — a worker inherits the PRESET-ONLY fs/web tools (read/write/glob/grep/web_search/web_fetch) even with an empty host global layer', async () => {
  await withTempStateDir(async (stateDir) => {
    // NO globalTools: the host global layer is empty of model capabilities. The
    // fs tools exist ONLY as the agentPresets standing contribution — the real
    // order the web profile composes them. The stub registers them into a
    // PER-PRESET standing scope and binds the agent scope to it ONLY inside
    // mount() (the async bind inside the real agentPresets.mount).
    const { agents, root, head, headCtx, key, agentPresets, dispose } = await bootWithHead(stateDir, { agentPresets: true })
    try {
      assert.ok(agentPresets, 'the agentPresets stub is mounted in the composition')
      // Sanity: the capability tools are NOT on the host global layer — they
      // arrive only via the preset standing bind (the real dsh-agent-presets
      // layout keeps them behind the preset's own realm, not the host plane).
      for (const name of ['web_search', 'read', 'write', 'glob', 'grep']) {
        assert.equal(root.tools.get(name), undefined, `host global layer has NO ${name} (fs/web are a preset standing contribution, as in the live web profile)`)
      }
      // The researcher template declares web_search/web_fetch/read/write/glob/
      // grep + the bus tools. If the setup AWAITS the preset mount FIRST (the
      // fix), the probe runs against the post-mount agent view and the worker
      // inherits ALL six; if the probe ran before the mount (the bug), the
      // worker's allow-list would be empty-of-fs and restrict() would mask them.
      const researcher = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'investigate X' })
      for (const name of ['web_search', 'web_fetch', 'read', 'write', 'glob', 'grep']) {
        assert.ok(researcher.ctx.tools.get(name, researcher.key), `researcher inherits the preset-mounted tool ${name} (the mount runs BEFORE the capability probe)`)
      }
      assert.equal(researcher.ctx.tools.get('edit', researcher.key), undefined, 'researcher has NO edit (the role does not declare it)')
      // The worker's own-layer bus tools stay visible (exempt from the mask).
      for (const name of ['send_message', 'agent_messages', 'dept_who', 'dept_memo_write']) {
        assert.ok(researcher.ctx.tools.get(name, researcher.key), `researcher still sees the bus/ciclo tool ${name}`)
      }
      assert.ok(agentPresets.mountCalls.includes('deepartments-worker'), 'the worker preset was mounted during setup')
    } finally {
      await dispose()
    }
  })
})

test('F10 (spec 004 §9.1): an existing ARCHITECTURE.md injects a templated "## Department architecture" systemPrompt section for BOTH the department worker AND the head', async () => {
  await withTempStateDir(async (stateDir) => {
    // Fixture: write the research department's ARCHITECTURE.md (the read path
    // is fixed at repo presets/departments/research/). The test uses its own
    // stub body, so it does NOT depend on the real file; on exit the REAL file
    // (or its absence) is restored — the fixture never destroys it. The org
    // configures a workspacePath so {{workspacePath}}/{{reportDir}} bind.
    const restoreArchitectureFile = await snapshotArchitectureFile()
    try {
      await writeFile(F10_ARCHITECTURE_PATH, [
        '# Research Department Architecture',
        '',
        'Department: {{deptName}}',
        'Head: {{headPostId}}',
        'Workspace: {{workspacePath}}',
        'Reports: {{reportDir}}',
        '',
        'The department coordinates through the bus; workers are disposable.'
      ].join('\n') + '\n', 'utf8')
      const org = {
        departments: [
          {
            id: 'research',
            name: 'Research',
            workspacePath: path.join(stateDir, 'dept-research'),
            coordinator: { postId: 'research-head', role: 'Research department head', provider: 'deepseek-official', agentOptions: { provider: 'stub-coord', model: 'deepseek-v4-flash' } }
          }
        ]
      }
      const { agents, head, headCtx, key, dispose } = await bootWithHead(stateDir, { org })
      try {
        // The HEAD (materialized at boot) carries the architecture section.
        const headSection = await findPromptSection(head.ctx, key, 'deepartments:head:architecture:research-head', true)
        assert.ok(headSection !== undefined, 'the head has the department architecture section')
        const headText = headSection.text
        assert.match(headText, /^## Department architecture/m, 'the head architecture section opens with the "## Department architecture" heading')
        assert.match(headText, /Department: Research/, '{{deptName}} templated -> "Research"')
        assert.match(headText, /Head: research-head/, '{{headPostId}} templated -> "research-head"')
        assert.match(headText, new RegExp(`Workspace: ${path.join(stateDir, 'dept-research').replace(/[/\\]/g, '\\$&')}`), '{{workspacePath}} templated -> the configured workspace path')
        assert.match(headText, new RegExp(`Reports: ${path.join(stateDir, 'dept-research', 'reports').replace(/[/\\]/g, '\\$&')}`), '{{reportDir}} templated -> <workspacePath>/reports')

        // The WORKER (spawned via dept_worker_spawn) carries the same section.
        const worker = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'templated architecture' })
        const wSection = await findPromptSection(worker.ctx, worker.key, `deepartments:worker:architecture:${worker.result.workerId}`, true)
        assert.ok(wSection !== undefined, 'the spawned worker has the department architecture section')
        assert.match(wSection.text, /^## Department architecture/m, 'the worker architecture section opens with the "## Department architecture" heading')
        assert.match(wSection.text, /Department: Research/, 'worker {{deptName}} templated')
        assert.match(wSection.text, /Head: research-head/, 'worker {{headPostId}} templated')
      } finally {
        await dispose()
      }
    } finally {
      await restoreArchitectureFile()
    }
  })
})

