test('F10 (spec 004 §9.1): the ROLE PERSONA body is templated like the architecture — a raw uppercase {{headPostId}}/{{reportDir}} NEVER reaches the assembled systemPrompt (the harness prompt expander rejects them), while the lowercase harness variable {{cwd}} is LEFT for the preset', async () => {
  await withTempStateDir(async (stateDir) => {
    const org = {
      departments: [
        {
          id: 'research',
          name: 'Research',
          workspacePath: path.join(stateDir, 'dept-research'),
          coordinator: { postId: 'research-head', role: 'Research department head', provider: 'deepseek-official', agentOptions: { provider: 'stub-coord', model: 'deepseek-v4-flash' } }
        }
      ]
    }
    const { agents, head, headCtx, key, dispose } = await bootWithHead(stateDir, { org })
    try {
      const worker = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'templated persona' })
      const persona = await findPromptSection(worker.ctx, worker.key, `deepartments:worker:role-persona:${worker.result.workerId}`, true)
      assert.ok(persona !== undefined, 'the role-persona section is assembled')
      // The REAL researcher.md persona carries {{headPostId}}/{{workspacePath}}/
      // {{reportDir}}: the assembled section must NEVER leak a raw `{...}` into
      // the prompt (the harness expander only accepts lowercase [a-z][a-z0-9_]*).
      assert.doesNotMatch(persona.text, /\{\{\s*(headPostId|reportDir|workspacePath|deptName)\s*\}\}/, 'no raw department {{...}} placeholder remains in the persona')
      assert.match(persona.text, /research-head/, '{{headPostId}} templated -> "research-head"')
      assert.match(persona.text, new RegExp(path.join(stateDir, 'dept-research', 'reports').replace(/[/\\]/g, '\\$&')), '{{reportDir}} templated -> <workspacePath>/reports')
      // {{cwd}} is a legitimate lowercase HARNESS preset variable — NEVER touched.
      assert.match(persona.text, /\{\{cwd\}\}/, '{{cwd}} stays raw (harness preset variable)')
      // The task is still injected with the templated persona.
      assert.match(persona.text, /## Your current assignment/, 'the task section is still appended')
      assert.match(persona.text, /templated persona/, 'the spawned task is present')
    } finally {
      await dispose()
    }
  })
})

test('F3 title default (owner decision 2026-08-23): spawn without a title uses "Rol: Misión" (role capitalized + first line of the task), truncating a long task to ~70 chars; a passed title is respected verbatim', async () => {
  await withTempStateDir(async (stateDir) => {
    const { root, agents, head, headCtx, key, dispose } = await bootWithHead(stateDir)
    try {
      // No title + a short task → "<RoleDisplay>: <first line of the task>".
      const short = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'track DSH updates' })
      assert.equal(short.result.title, 'Researcher: track DSH updates', 'default title = "<RoleDisplay>: <mission>" (role capitalized, not the template title)')
      assert.equal(root.sessions.get(SessionId(short.result.sessionId)).events.find((ev) => ev.type === 'session/title')?.data.title, 'Researcher: track DSH updates', 'the pinned session title is the "Rol: Misión" default')

      // No title + a LONG task → the mission is cut to ~70 chars + ellipsis
      // (the ~70 cap applies to the MISSION, not the whole "Role: mission" row).
      const longTask = 'a very long assignment line that surely exceeds seventy characters when used verbatim as the sidebar mission text here'
      const long = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: longTask })
      const longPrefix = 'Researcher: '
      assert.ok(long.result.title.startsWith(longPrefix), 'the default title keeps the "<RoleDisplay>: " prefix')
      const longMission = long.result.title.slice(longPrefix.length)
      assert.ok(longMission.length <= 70, `the mission is capped at ~70 chars (got "${longMission}" — length ${longMission.length})`)
      assert.ok(longMission.endsWith('...'), 'the truncated mission carries a truncation ellipsis')
      assert.equal(longMission, `${longTask.slice(0, 67).trimEnd()}...`, 'the mission is the task start cut to ~70 chars')

      // A PASSED title is respected verbatim (never substituted).
      const custom = await f3Spawn({ agents }, headCtx, key, head, { role: 'reviewer', task: 'check the report', title: 'Custom reviewer label' })
      assert.equal(custom.result.title, 'Custom reviewer label', 'a passed title overwrites the "Rol: Misión" default')
      assert.equal(root.sessions.get(SessionId(custom.result.sessionId)).events.find((ev) => ev.type === 'session/title')?.data.title, 'Custom reviewer label', 'the pinned title is the passed override')
    } finally {
      await dispose()
    }
  })
})

test('F3 slug dedup: dept_worker_spawn dedups worker slugs with -2, -3… and NEVER reuses a RETIRED slug', async () => {
  await withTempStateDir(async (stateDir) => {
    const { agents, head, headCtx, key, dispose } = await bootWithHead(stateDir)
    try {
      const first = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'first' })
      assert.equal(first.result.workerId, 'researcher', 'first spawn takes the bare role slug')

      const second = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'second' })
      assert.equal(second.result.workerId, 'researcher-2', 'a live slug dedups to -2')

      // Retire the FIRST worker (its slug stays REGISTERED in posts.json with
      // retired:true — the F1 mark-not-erase invariant) and spawn again: the
      // retired slug is still NOT reused → -3.
      await headCtx.tools.get('dept_worker_retire', key).execute({ workerId: 'researcher' }, { agent: head, signal: new AbortController().signal })
      const third = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'third' })
      assert.equal(third.result.workerId, 'researcher-3', 'a RETIRED slug is not reused (dedup sees retired entries)')
    } finally {
      await dispose()
    }
  })
})

test('worker session-id uniqueness (F8 head-rotation pattern applied to workers): a retire archives the worker\'s UNIQUE session id, and a respawn of the SAME role mints a DIFFERENT UNIQUE session id that is NOT archived — the GUI sidebar never hides the replacement worker', async () => {
  await withTempStateDir(async (stateDir) => {
    const { agents, head, headCtx, key, workspaceRegistry, dispose } = await bootWithHead(stateDir)
    try {
      const signal = new AbortController().signal
      // Spawn the FIRST worker of role "researcher" → a UNIQUE session id.
      const first = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'first' })
      const firstSid = first.result.sessionId
      assert.match(firstSid, /^worker-researcher-[0-9a-f-]+$/, 'the first worker mints a UNIQUE session id (worker-<slug>-<uuid>), never the deterministic worker-researcher')
      assert.equal(first.result.workerId, 'researcher', 'the first worker keeps the bare role slug (the identity is the postId, not the session)')

      // Retire it → its UNIQUE session is archived (the sidebar row disappears).
      await headCtx.tools.get('dept_worker_retire', key).execute({ workerId: 'researcher' }, { agent: head, signal })
      await waitFor(() => workspaceRegistry.archivedSessionIds.includes(firstSid), 5000, 'the FIRST worker\'s unique session is archived (D5)')

      // Respawn the SAME role → the slug dedups to -2 and the session id is a
      // DIFFERENT unique mint (never the deterministic, never the archived id).
      const second = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'second' })
      const secondSid = second.result.sessionId
      assert.equal(second.result.workerId, 'researcher-2', 'the respawned same-role worker dedups its slug to -2')
      assert.match(secondSid, /^worker-researcher-2-[0-9a-f-]+$/, 'the second worker mints its OWN unique session id')
      assert.notEqual(secondSid, firstSid, 'the respawned worker\'s session id DIFFERS from the archived one')
      assert.equal(workspaceRegistry.archivedSessionIds.includes(secondSid), false, 'the respawned worker\'s session id is NOT archived')
      assert.equal(workspaceRegistry.archivedSessionIds.includes(firstSid), true, 'only the FIRST worker\'s (archived) session is in the archived set')

      // The replacement worker is LIVE and its row is visible (the GUI sidebar
      // filter `!archived.has(id)` never hides it) — session attached, NOT archived.
      assert.equal(agents.store.has(secondSid), true, 'the respawned worker is LIVE')
      const posts = await readPosts(stateDir)
      assert.equal(posts['researcher'].retired, true, 'the FIRST worker stays marked retired (mark, not erase)')
      assert.equal(posts['researcher-2'].retired, undefined, 'the respawned worker is LIVE')
      assert.equal(posts['researcher-2'].sessionId, secondSid, 'the respawned worker\'s durable entry.sessionId = ITS unique session id')
    } finally {
      await dispose()
    }
  })
})

test('F3 dept_worker_retire: marks retired (entry kept, live catalog stops addressing), archives the session, cross-department head DENIED, idempotent', async () => {
  await withTempStateDir(async (stateDir) => {
    const env = await f3BootWithTwoHeads(stateDir)
    try {
      const signal = new AbortController().signal
      // research-head spawns a worker of ITS department.
      const spawned = await f3Spawn(env, env.researchCtx, env.researchKey, env.researchHead, { role: 'researcher', task: 'investigate X' })
      const sid = spawned.result.sessionId

      // programming-head CANNOT retire it (different manager AND department).
      await assert.rejects(
        () => env.programmingCtx.tools.get('dept_worker_retire', env.programmingKey).execute({ workerId: 'researcher' }, { agent: env.programmingHead, signal }),
        /not a worker of YOUR department/, 'a head cannot retire a worker of ANOTHER department'
      )
      assert.equal((await readPosts(stateDir))['researcher']?.retired, undefined, 'the rejected retire left the entry live')

      // research-head retires its own worker: mark + archive.
      const result = await env.researchCtx.tools.get('dept_worker_retire', env.researchKey).execute({ workerId: 'researcher' }, { agent: env.researchHead, signal })
      assert.equal(result.retired, true)
      assert.equal(result.archived, true, 'the durable session archive was requested')
      await waitFor(() => env.workspaceRegistry.archivedSessionIds.includes(sid), 5000, 'the UNIQUE worker session is archived (sidebar row disappears, D5)')
      const posts = await readPosts(stateDir)
      assert.equal(posts['researcher'].retired, true, 'retire is a MARK, not an erase (posts.json keeps the entry)')
      assert.equal(posts['researcher'].managerId, 'research-head', 'the creator link survives the retire (logs/history kept, D5)')

      // LIVE catalog stops addressing it (per-recipient failed, like unknown).
      const host = env.agents.put(fakeParentAgent())
      const send = await env.root.tools.get('send_message').execute({ to: ['researcher'], text: 'are you there?' }, { agent: host, signal })
      assert.equal(send.delivered['researcher'], 'failed', 'a retired worker is not addressed by the live catalog')

      // dept_who (the MANAGEMENT view) still lists it WITH retired:true.
      const who = await env.root.tools.get('dept_who').execute({ scope: 'includeRetired' }, { agent: host, signal })
      const row = who.members.find((m) => m.agentId === 'researcher')
      assert.ok(row, 'the retired worker IS listed in dept_who')
      assert.equal(row.retired, true, 'the row carries retired:true')
      assert.equal(row.kind, 'worker', 'the row keeps the derived worker kind')

      // Idempotent: a second retire succeeds as a no-op (still archived).
      const again = await env.researchCtx.tools.get('dept_worker_retire', env.researchKey).execute({ workerId: 'researcher' }, { agent: env.researchHead, signal })
      assert.equal(again.retired, true)
      assert.equal(again.archived, true)
    } finally {
      await env.dispose()
    }
  })
})

// legacy A+B: head sleep retired 2026-08-27 — kept for history (R6)
test.skip('Fix B head-sleep worker drain: a worker report delivered to its DOMANT manager head is AUTO-RETIRED on delivery — status "resumed" (the sleep-boundary signature) and posts[workerId].retired === true', async () => {
  await withTempStateDir(async (stateDir) => {
    const { agents, head, headCtx, key, dispose } = await bootWithHead(stateDir)
    try {
      const signal = new AbortController().signal
      // Spawn a worker of the head (managerId = research-head), then sleep the head.
      const spawned = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'do the work and report back' })
      const workerId = spawned.result.workerId
      const worker = spawned.worker
      const wctx = spawned.ctx
      const wkey = spawned.key

      const sleep = headCtx.tools.get('dept_sleep', key)
      const memo = headCtx.tools.get('dept_memo_write', key)
      await memo.execute({ summary: 'drain memory' }, { agent: head, signal })
      await sleep.execute({}, { agent: head, signal })
      await waitFor(() => agents.store.has('head-research-head') === false, 5000, 'head handle disposed after sleep')

      // The worker reports to its just-disposed (dormant) manager head. The
      // delivery is the respawn-from-sleep branch → status "resumed", and Fix B
      // auto-retires the worker on that very delivery.
      const r = await wctx.tools.get('send_message', wkey).execute(
        { to: ['research-head'], text: 'report: work complete' },
        { agent: worker, signal }
      )
      assert.equal(r.delivered['research-head'], 'resumed', 'worker report to a dormant head delivers as resumed (the sleep-boundary signature)')

      // Fix B: the delivery itself is the retire trigger — no head-side open item.
      await waitFor(async () => (await readPosts(stateDir))[workerId]?.retired === true, 5000, 'the delivering worker is auto-retired')
      const posts = await readPosts(stateDir)
      assert.equal(posts[workerId].retired, true, 'Fix B auto-retire is durable (posts.json marks the worker retired)')
      // The sleep-boundary in-flight ledger is pruned as the worker is retired.
      assert.equal(posts['research-head']?.inflightWorkers?.includes(workerId), undefined, 'the retired worker was pruned from the head\'s in-flight ledger')
    } finally {
      await dispose()
    }
  })
})

