test('W8-c scheduler auto-run visibility (dedupe): the SAME no-fire on consecutive ticks is recorded ONCE (health-alerts-state.json dedupe, key scheduler:<jobId>:<reason>, 30min window) — never double-recorded', async () => {
  await withTempStateDir(async (stateDir) => {
    const jobDir = await mkdtemp(path.join(tmpdir(), 'deepartments-sched-'))
    try {
      await writeFile(path.join(jobDir, 'sched-d.md'), '---\nid: sched-d\ntitle: Sched D\nrole: researcher\ndescription: a due job\nowner: research-head\nschedule: "* * * * *"\n---\n\nbody\n', 'utf8')
      // A case (a) throw does NOT advance the job-runs ledger, so the SAME cron
      // is still due on the next tick (it re-attempts the fire) — the capture
      // dedupe is what prevents a second post-error row.
      const nowMs = new Date(2026, 7, 23, 9, 0, 30).getTime()
      const { deps } = schedTicker({ stateDir, nowMs, runJob: async () => { throw new Error('kaboom') } })
      deps.departments[0].jobDir = jobDir
      deps.departmentForEntry = () => ({ id: 'research', name: 'Research', jobDir })
      deps.departmentForJob = () => ({ id: 'research', name: 'Research', jobDir })
      await runAgendaSchedulerTick(deps)
      await runAgendaSchedulerTick(deps)
      const rows = readPostErrorsFile(stateDir).filter((r) => r.postId === 'scheduler')
      assert.equal(rows.length, 1, 'dedupe: the same no-fire is recorded ONCE inside the 30min window (not double-recorded on a consecutive tick)')
      const state = readHealthAlertsState(stateDir)
      assert.equal(state[schedulerAutoRunKey('sched-d', 'kaboom')], nowMs, 'dedupe: the scheduler dedupe ledger is persisted at now')
    } finally {
      await rm(jobDir, { recursive: true, force: true })
    }
  })
})

test('W8-c scheduler auto-run visibility (logging): the closure LOGS THE REASON (jobId + cause) into the finding/message text that surfaces in the host ALERT', async () => {
  await withTempStateDir(async (stateDir) => {
    const jobDir = await mkdtemp(path.join(tmpdir(), 'deepartments-sched-'))
    try {
      await writeFile(path.join(jobDir, 'sched-l.md'), '---\nid: sched-l\ntitle: Sched L\nrole: researcher\ndescription: a due job\nowner: research-head\nschedule: "0 9 * * *"\n---\n\nbody\n', 'utf8')
      const nowMs = new Date(2026, 7, 23, 9, 0, 30).getTime()
      const { deps, captured } = schedTicker({ stateDir, nowMs, runJob: async () => false })
      deps.departments[0].jobDir = jobDir
      deps.departmentForEntry = () => ({ id: 'research', name: 'Research', jobDir })
      deps.departmentForJob = () => ({ id: 'research', name: 'Research', jobDir })
      await runAgendaSchedulerTick(deps)
      // The captured finding carries the jobId + the exact skip cause.
      assert.equal(captured.length, 1, 'logging: the tick emitted exactly one scheduler finding')
      assert.equal(captured[0].jobId, 'sched-l', 'logging: the finding carries the jobId')
      assert.equal(captured[0].reason, 'idempotency-skip', 'logging: the finding carries the skip cause')
      // The recorded message text (which the alert surfaces) includes both.
      const row = readPostErrorsFile(stateDir).find((r) => r.postId === 'scheduler')
      assert.match(row.error, /sched-l/, 'logging: the finding/message text includes the jobId')
      assert.match(row.error, /idempotency-skip/, 'logging: the finding/message text includes the cause')
      // And the framer shows it verbatim in the host ALERT.
      const alerts = []
      await runHealthDaemonTick({
        now: () => nowMs, stateDir, bootId: 'boot-l',
        hosts: [{ hostId: 'host-asst', sessionId: 's-live', roomId: 'board' }],
        notifyHost: async (hostEntry, frame) => { alerts.push({ hostEntry, frame }) },
        logger: { warn: () => {} }
      })
      assert.match(alerts[0].frame, /idempotency-skip/, 'logging: the host ALERT surfaces the skip cause')
    } finally {
      await rm(jobDir, { recursive: true, force: true })
    }
  })
})

// --- W3b (spec W3 monitor → researcher): Parallel event_stream monitors ------
// The pure half (config resolution, state helpers, the poller tick) is tested
// with a fixed clock + stubbed create/poll/spawn/notify; dept_monitor_list is
// exercised through the real Loader (head own-layer / worker absence).

test('W3b parallel-monitor config: default 2 monitors (code), empty array → none, override passthrough; state round-trips + malformed → empty', async () => {
  assert.equal(DEFAULT_PARALLEL_MONITORS.length, 2, 'code default = 2 monitors')
  assert.equal(DEFAULT_PARALLEL_MONITORS[0].id, 'ai-industry-news', 'default #1 id')
  assert.equal(DEFAULT_PARALLEL_MONITORS[0].processor, 'base', 'default #1 processor = base')
  assert.equal(DEFAULT_PARALLEL_MONITORS[0].frequency, '1d', 'default #1 frequency = 1d')
  assert.equal(DEFAULT_PARALLEL_MONITORS[1].id, 'deepseek-dsh-news', 'default #2 id')

  // Absent section → code default; a present section without `monitors` → code default.
  assert.deepEqual(resolveParallelMonitorConfig(undefined).map((m) => m.id), DEFAULT_PARALLEL_MONITORS.map((m) => m.id), 'absent section → the 2 code defaults')
  assert.deepEqual(resolveParallelMonitorConfig({}).map((m) => m.id), DEFAULT_PARALLEL_MONITORS.map((m) => m.id), 'present section without monitors key → the 2 code defaults')
  // Explicit empty array → NONE (disable).
  assert.deepEqual(resolveParallelMonitorConfig({ monitors: [] }), [], 'explicit empty array → none (monitoring disabled)')
  // A non-empty array → verbatim.
  const custom = [{ id: 'custom-monitor', query: 'custom query', processor: 'lite', frequency: '6h' }]
  assert.deepEqual(resolveParallelMonitorConfig({ monitors: custom }), custom, 'non-empty array → verbatim')

  await withTempStateDir(async (stateDir) => {
    const now = Date.now()
    await writeParallelMonitorsState(stateDir, { monitors: { 'ai-industry-news': { monitorId: 'monitor_1', cursor: 'c1', lastPolledAt: now, lastFiredAt: now, lastEventCount: 3, seenEventIds: ['a', 'b'] } } })
    const state = readParallelMonitorsState(stateDir)
    assert.equal(state.monitors['ai-industry-news'].monitorId, 'monitor_1', 'state round-trips monitorId')
    assert.equal(state.monitors['ai-industry-news'].cursor, 'c1', 'state round-trips cursor')
    assert.equal(state.monitors['ai-industry-news'].lastEventCount, 3, 'state round-trips lastEventCount')
    assert.deepEqual(state.monitors['ai-industry-news'].seenEventIds, ['a', 'b'], 'state round-trips seenEventIds')
    await writeFile(path.join(stateDir, 'parallel-monitors-state.json'), 'junk', 'utf8')
    assert.deepEqual(readParallelMonitorsState(stateDir).monitors, {}, 'malformed → empty, never throws')
  })
})

test('W3b parallel-monitor config SCHEMA: the `parallel` section is declared in Config (W3b first-class), accepts the full field shape, and schemastery normalization preserves the documented default semantics', () => {
  const base = { stateDir: '.deepartments', org: { departments: [{ id: 'r', name: 'R' }] } }
  // Absent section → the field is undefined → the code default (2) applies.
  const absent = configSchema(base)
  assert.equal(absent.parallel, undefined, 'absent parallel section → undefined field (code default active)')
  assert.equal(resolveParallelMonitorConfig(absent.parallel).length, 2, 'absent section → the 2 code defaults')
  // Present section WITHOUT a monitors key → still the code default (not disabled).
  const empty = configSchema({ ...base, parallel: {} })
  assert.deepEqual(empty.parallel, {}, 'parallel:{} normalizes to an empty object (monitors stays undefined)')
  assert.equal(resolveParallelMonitorConfig(empty.parallel).length, 2, 'parallel:{} → the 2 code defaults')
  // Explicit empty array → disabled.
  const explicit = configSchema({ ...base, parallel: { monitors: [] } })
  assert.deepEqual(resolveParallelMonitorConfig(explicit.parallel), [], 'parallel:{monitors:[]} → none (disabled)')
  // Full field shape is accepted verbatim; absent optional sub-fields are NOT injected.
  const full = configSchema({ ...base, parallel: { apiKey: 'k', baseUrl: 'b', maxConsecutiveSpawns: 3, monitors: [{ id: 'a', query: 'q', processor: 'lite', frequency: '6h', outputSchema: { foo: 1 }, sourcePolicy: ['x'], includeBackfill: true }] } })
  assert.equal(full.parallel.apiKey, 'k', 'apiKey preserved')
  assert.equal(full.parallel.baseUrl, 'b', 'baseUrl preserved')
  assert.equal(full.parallel.maxConsecutiveSpawns, 3, 'maxConsecutiveSpawns preserved')
  assert.deepEqual(resolveParallelMonitorConfig(full.parallel), full.parallel.monitors, 'full monitors → verbatim')
  const minimal = configSchema({ ...base, parallel: { apiKey: 'k', monitors: [{ id: 'a', query: 'q' }] } }).parallel.monitors[0]
  assert.deepEqual(minimal, { id: 'a', query: 'q' }, 'absent optional monitor sub-fields are not injected ({}/[]/false)')
})

test('W3b runParallelMonitorTick: creates the monitor once (no monitorId), fires a FRESH first-run event exactly once (spawn + notify), records-not-fires a STALE first-run event, advances the cursor', async () => {
  await withTempStateDir(async (stateDir) => {
    const nowMs = new Date(2026, 7, 23, 12, 0, 0).getTime()
    const freshEvent = { event_id: 'mevt_fresh', event_date: new Date(nowMs - 3600000).toISOString().slice(0, 10), output: { content: 'DeepSeek V4 released' } }
    const staleEvent = { event_id: 'mevt_stale', event_date: new Date(nowMs - 3 * 24 * 3600000).toISOString().slice(0, 10), output: { content: 'old news' } }
    const createCalls = []
    const spawnCalls = []
    const notifyCalls = []
    const warns = []
    const deps = {
      now: () => nowMs,
      stateDir,
      monitors: [{ id: 'ai-industry-news', query: 'AI news', processor: 'base', frequency: '1d' }],
      apiKey: 'k',
      baseUrl: 'https://api.parallel.ai',
      maxConsecutiveSpawns: 2,
      createMonitor: async () => { createCalls.push(1); return { monitorId: 'monitor_1' } },
      fetchEvents: async (monitorId, cursor) => {
        // First poll (cursor undefined) returns the batch; the next poll returns [] (consumed).
        if (cursor === undefined) return { events: [staleEvent, freshEvent], nextCursor: 'c1' }
        return { events: [], nextCursor: undefined }
      },
      spawnResearcher: async (monitor, ev) => { spawnCalls.push(ev.event_id); return { workerId: `worker-${ev.event_id}` } },
      notifyHead: async (monitor, ev, wid) => { notifyCalls.push({ ev: ev.event_id, wid }) },
      liveWorkerCount: () => 0,
      logger: { warn: (x) => { warns.push(x) } }
    }
    // Tick 1: create the monitor + first poll.
    await runParallelMonitorTick(deps)
    assert.equal(createCalls.length, 1, 'created the monitor exactly once (no monitorId yet)')
    assert.deepEqual(spawnCalls, ['mevt_fresh'], 'ONLY the fresh event fires on the first run (the stale event is recorded-not-fired)')
    assert.equal(notifyCalls.length, 1, 'exactly ONE head notice for the one fired event')
    assert.equal(notifyCalls[0].ev, 'mevt_fresh', 'the notice is for the fired fresh event')
    assert.equal(notifyCalls[0].wid, 'worker-mevt_fresh', 'the notice carries the spawned worker id')
    const state = readParallelMonitorsState(stateDir)
    assert.equal(state.monitors['ai-industry-news'].monitorId, 'monitor_1', 'monitorId is persisted')
    assert.equal(state.monitors['ai-industry-news'].cursor, 'c1', 'the cursor advances past the first window')
    assert.ok(state.monitors['ai-industry-news'].seenEventIds.includes('mevt_stale'), 'the stale event is recorded (seen) so it never re-fires')
    assert.ok(state.monitors['ai-industry-news'].seenEventIds.includes('mevt_fresh'), 'the fired event is recorded (seen) so it never double-fires')
    assert.equal(warns.length, 0, 'a clean tick logs no warns')
  })
})

test('W3b runParallelMonitorTick: idempotent — no new events spawn nothing; an already-seen event spawns nothing; a storm-guarded live-worker count skips', async () => {
  await withTempStateDir(async (stateDir) => {
    const nowMs = new Date(2026, 7, 23, 12, 0, 0).getTime()
    const spawnCalls = []
    const notifyCalls = []
    const warns = []
    const baseDeps = {
      now: () => nowMs,
      stateDir,
      monitors: [{ id: 'm1', query: 'q', processor: 'base', frequency: '1d' }],
      apiKey: 'k',
      baseUrl: 'https://api.parallel.ai',
      maxConsecutiveSpawns: 2,
      createMonitor: async () => ({ monitorId: 'monitor_1' }),
      spawnResearcher: async (monitor, ev) => { spawnCalls.push(ev.event_id); return { workerId: `w-${ev.event_id}` } },
      notifyHead: async (monitor, ev, wid) => { notifyCalls.push(ev.event_id) },
      liveWorkerCount: () => 0,
      logger: { warn: (x) => { warns.push(x) } }
    }
    // Seed a monitor already created with a cursor (the poll is now a "later window").
    await writeParallelMonitorsState(stateDir, { monitors: { m1: { monitorId: 'monitor_1', cursor: 'c9', seenEventIds: ['mevt_seen'] } } })
    // (a) no new events → nothing.
    await runParallelMonitorTick({ ...baseDeps, fetchEvents: async () => ({ events: [], nextCursor: undefined }) })
    assert.equal(spawnCalls.length, 0, 'no events → no spawn')
    assert.equal(notifyCalls.length, 0, 'no events → no notify')
    // (b) an already-seen event → nothing (dedup by event_id).
    await runParallelMonitorTick({ ...baseDeps, fetchEvents: async () => ({ events: [{ event_id: 'mevt_seen', event_date: new Date(nowMs).toISOString().slice(0, 10), output: { content: 'again' } }], nextCursor: 'c10' }) })
    assert.equal(spawnCalls.length, 0, 'an already-seen event → no spawn')
    assert.equal(notifyCalls.length, 0, 'an already-seen event → no notify')
    // (c) storm guard: live workers == maxConsecutiveSpawns → skip (no spawn, warn).
    await runParallelMonitorTick({
      ...baseDeps,
      fetchEvents: async () => ({ events: [{ event_id: 'mevt_new', event_date: new Date(nowMs).toISOString().slice(0, 10), output: { content: 'new' } }], nextCursor: 'c11' }),
      liveWorkerCount: () => 2
    })
    assert.equal(spawnCalls.length, 0, 'live workers ≥ max → the spawn is skipped (storm guard)')
    assert.match(warns.join(' '), /storm guard/, 'a storm-guard skip emits a warn')
  })
})

test('W3b runParallelMonitorTick: storm guard caps LIVE spawns WITHIN one page — 5 fresh events, max 2 → exactly 2 spawns, 3 consumed (skipped, not doubled)', async () => {
  await withTempStateDir(async (stateDir) => {
    const nowMs = new Date(2026, 7, 23, 12, 0, 0).getTime()
    const events = Array.from({ length: 5 }, (_, i) => ({ event_id: `mevt_${i}`, event_date: new Date(nowMs).toISOString().slice(0, 10), output: { content: `item ${i}` } }))
    const spawnCalls = []
    const notifyCalls = []
    const warns = []
    const deps = {
      now: () => nowMs,
      stateDir,
      monitors: [{ id: 'm1', query: 'q', processor: 'base', frequency: '1d' }],
      apiKey: 'k',
      baseUrl: 'https://api.parallel.ai',
      maxConsecutiveSpawns: 2,
      createMonitor: async () => ({ monitorId: 'monitor_1' }),
      fetchEvents: async () => ({ events, nextCursor: 'c_next' }),
      spawnResearcher: async (monitor, ev) => { spawnCalls.push(ev.event_id); return { workerId: `w-${ev.event_id}` } },
      notifyHead: async (monitor, ev, wid) => { notifyCalls.push(ev.event_id) },
      liveWorkerCount: () => 0,
      logger: { warn: (x) => { warns.push(x) } }
    }
    // Seed a monitor already created with a cursor (a "later window" — NOT the
    // first-run freshness gate, so all 5 events are eligible to fire).
    await writeParallelMonitorsState(stateDir, { monitors: { m1: { monitorId: 'monitor_1', cursor: 'c0', seenEventIds: [] } } })
    await runParallelMonitorTick(deps)
    assert.equal(spawnCalls.length, 2, 'exactly 2 spawns (maxConsecutiveSpawns=2), NOT 5 — one page cannot blow past the live cap')
    assert.deepEqual(spawnCalls, ['mevt_0', 'mevt_1'], 'the first 2 events fire, then the live cap is hit')
    assert.equal(notifyCalls.length, 2, 'one head notice per fired event')
    const state = readParallelMonitorsState(stateDir)
    assert.equal(state.monitors.m1.cursor, 'c_next', 'the cursor advances (the 3 skipped events are consumed, not re-fetched)')
    assert.ok(state.monitors.m1.seenEventIds.includes('mevt_0'), 'the fired event is recorded seen')
    assert.ok(state.monitors.m1.seenEventIds.includes('mevt_1'), 'the fired event is recorded seen')
    assert.ok(!state.monitors.m1.seenEventIds.includes('mevt_2'), 'the first storm-guarded event is NOT recorded seen (skipped, consumed by the cursor advance)')
    assert.ok(!state.monitors.m1.seenEventIds.includes('mevt_4'), 'the last storm-guarded event is NOT recorded seen (skipped, consumed by the cursor advance)')
    assert.match(warns.join(' '), /storm guard/, 'a storm-guard skip emits a warn')
  })
})

test('W3b runParallelMonitorTick: create/poll/spawn/notify errors NEVER throw (warn + skip)', async () => {
  await withTempStateDir(async (stateDir) => {
    const warns = []
    const deps = {
      now: () => Date.now(),
      stateDir,
      monitors: [{ id: 'm1', query: 'q' }],
      apiKey: 'k',
      baseUrl: 'x',
      maxConsecutiveSpawns: 2,
      createMonitor: async () => { throw new Error('create boom') },
      fetchEvents: async () => { throw new Error('poll boom') },
      spawnResearcher: async () => { throw new Error('spawn boom') },
      notifyHead: async () => { throw new Error('notify boom') },
      liveWorkerCount: () => 0,
      logger: { warn: (x) => { warns.push(x) } }
    }
    await runParallelMonitorTick(deps) // create fails → warn + skip (must NOT throw)
    assert.ok(warns.some((w) => /create monitor/.test(w)), 'a create failure warns')
    // Seed an already-created monitor so the poll path is exercised.
    await writeParallelMonitorsState(stateDir, { monitors: { m1: { monitorId: 'monitor_1', cursor: 'c1' } } })
    await runParallelMonitorTick(deps) // poll fails → warn + skip (must NOT throw)
    assert.ok(warns.some((w) => /poll/.test(w)), 'a poll failure warns')
    // A poll returning ONE fresh event whose spawn fails → warn + skip (never throw).
    await runParallelMonitorTick({
      ...deps,
      fetchEvents: async () => ({ events: [{ event_id: 'e1', event_date: new Date().toISOString().slice(0, 10), output: { content: 'x' } }], nextCursor: 'c2' })
    })
    assert.ok(warns.some((w) => /spawn for/.test(w)), 'a spawn failure warns')
  })
})

test('W3b parallel-monitor daemon: LAZY head resolution survives the boot race (empty byPost → skip without throw; populated → create + poll + spawn + notify)', async () => {
  await withTempStateDir(async (stateDir) => {
    const byPost = new Map()
    const departments = TEST_ORG.departments
    const created = []
    const polled = []
    const spawned = []
    const notified = []
    const warns = []
    const infos = []
    let nowMs = Date.now()
    let pollCount = 0
    const daemon = createParallelMonitorDaemon({
      baseUrl: 'https://api.parallel.ai',
      maxConsecutiveSpawns: 2,
      monitors: [{ id: 'm1', query: 'fresh events' }],
      stateDir,
      now: () => nowMs,
      departments,
      byPost,
      logger: { warn: (m) => warns.push(m), info: (m) => infos.push(m) },
      createMonitor: async (monitor) => { created.push(monitor.id); return { monitorId: `monitor_${monitor.id}` } },
      fetchEvents: async (monitorId, cursor) => {
        polled.push({ monitorId, cursor })
        pollCount += 1
        if (pollCount === 1) return { events: [], nextCursor: 'c1' }
        // The SECOND poll returns one FRESH event → spawn + notify.
        return { events: [{ event_id: 'mevt_1', event_date: new Date(nowMs).toISOString().slice(0, 10), output: { content: 'news' } }], nextCursor: 'c2' }
      },
      countWorkers: () => 0,
      spawnWorker: async (dept, head, opts) => { spawned.push({ dept: dept.id, head: head.postId, jobId: opts.jobId }); return { workerId: 'w1' } },
      notifyHead: async (head, monitor, event, workerId) => { notified.push({ head: head.postId, monitor: monitor.id, workerId }) }
    })
    // Tick 1 — byPost is EMPTY (the boot race): the daemon must SKIP (no create /
    // poll / spawn / notify), NOT throw, and write no monitor state.
    await daemon.tick()
    assert.equal(created.length, 0, 'empty byPost → no monitor is created')
    assert.equal(polled.length, 0, 'empty byPost → nothing is polled')
    assert.equal(spawned.length, 0, 'empty byPost → nothing is spawned')
    assert.equal(notified.length, 0, 'empty byPost → nothing is notified')
    assert.equal(warns.length, 1, 'a no-target skip emits exactly one discreet warn')
    assert.match(warns[0], /no research department \/ head/, 'the skip warns it is waiting for the department head')
    assert.ok(!('m1' in readParallelMonitorsState(stateDir).monitors), 'a skipped tick writes no monitor state')
    // Tick 2 — byPost is now POPULATED with the head: the target resolves LAZILY
    // and the tick creates the monitor + polls it (the old bug would have left
    // the daemon permanently disabled).
    byPost.set('research-head', { postId: 'research-head', sessionId: 'head-1', roomId: 'r', agentPreset: 'deepartments-head' })
    await daemon.tick()
    assert.equal(created.length, 1, 'the populated tick creates the monitor once')
    assert.equal(polled.length, 1, 'the populated tick polls the monitor')
    assert.equal(infos.length, 1, 'the one-shot enable info is logged once')
    assert.match(infos[0], /1 monitor\(s\) enabled/, 'the enable info names the count')
    assert.match(infos[0], /research-head/, 'the enable info names the resolved head postId')
    assert.equal(spawned.length, 0, 'an empty first poll spawns nothing')
    const afterCreate = readParallelMonitorsState(stateDir)
    assert.equal(afterCreate.monitors.m1.monitorId, 'monitor_m1', 'the created monitorId is persisted')
    assert.equal(afterCreate.monitors.m1.cursor, 'c1', 'the poll cursor advances')
    // Tick 3 — one fresh event: spawn + notify through the RESOLVED target; the
    // enable info is NOT re-logged (one-shot).
    nowMs += 1000
    await daemon.tick()
    assert.equal(spawned.length, 1, 'a fresh event spawns one researcher')
    assert.equal(spawned[0].dept, 'research', 'the researcher lands under the research department')
    assert.equal(spawned[0].head, 'research-head', 'the researcher is spawned via the resolved head')
    assert.equal(notified.length, 1, 'the head is notified for the fired event')
    assert.equal(notified[0].head, 'research-head', 'the notification targets the resolved head')
    assert.equal(infos.length, 1, 'the enable info is NOT re-logged on later ticks')
    assert.equal(warns.length, 1, 'no further warns once the target is available')
  })
})

test('W3b dept_monitor_list (head own-layer ONLY): lists the code-default monitors + the persisted state; a worker has NO dept_monitor_list', async () => {
  await withTempStateDir(async (stateDir) => {
    const { root, agents, head, headCtx, key, dispose } = await bootWithHead(stateDir)
    try {
      const signal = new AbortController().signal
      // Seed a persisted monitor state (which the daemon would have written).
      await writeParallelMonitorsState(stateDir, { monitors: { 'ai-industry-news': { monitorId: 'monitor_ai', cursor: 'c1', lastPolledAt: 1, lastFiredAt: 2, lastEventCount: 5 } } })
      assert.ok(headCtx.tools.get('dept_monitor_list', key), 'dept_monitor_list installed in the head own layer')
      const result = await headCtx.tools.get('dept_monitor_list', key).execute({}, { agent: head, signal })
      assert.equal(result.monitors.length, 2, 'the 2 code-default monitors are listed')
      const ai = result.monitors.find((m) => m.id === 'ai-industry-news')
      assert.ok(ai, 'the ai-industry-news monitor is listed')
      assert.equal(ai.monitorId, 'monitor_ai', 'the persisted monitorId is surfaced by the tool')
      assert.equal(ai.lastEventCount, 5, 'the persisted lastEventCount is surfaced')
      assert.equal(ai.cursor, 'c1', 'the persisted cursor is surfaced')
      const dsh = result.monitors.find((m) => m.id === 'deepseek-dsh-news')
      assert.ok(dsh, 'the deepseek-dsh-news monitor is listed')
      assert.equal(dsh.monitorId, undefined, 'an un-created monitor surfaces no monitor_id')
      // A WORKER has NO dept_monitor_list (the tool is head own-layer ONLY).
      const spawned = await headCtx.tools.get('dept_worker_spawn', key).execute({ role: 'researcher', task: 'check this' }, { agent: head, signal })
      const { ctx: workerCtx, key: workerKey } = childContextFor(agents, spawned.sessionId)
      assert.equal(workerCtx.tools.get('dept_monitor_list', workerKey), undefined, 'a worker has NO dept_monitor_list')
    } finally {
      await dispose()
    }
  })
})

// ===========================================================================
// B2 (spec W5-B2): dept_exec — the SCOPED shell tool for department posts, and
// the calendar `departmentId` attribution. The dept_exec guard + allow-roots are
// CENTRAL and unit-testable (deptExecDenyReason), and the tool is integration-
// tested through the real Loader (a role that DECLARES dept_exec owns it; a
// role that does not never sees it; the host and a config head never get it).
// ===========================================================================

/** A one-off role template for the dept_exec tests: declares `dept_exec` so the
 * spawned worker's allow-list carries it (a role that does not declare it never
 * registers the tool). */
const EXEC_ROLE = 'execbuilder'
const EXEC_ROLE_PATH = path.join(F10_REPO_ROOT, 'presets', 'departments', 'research', `${EXEC_ROLE}.md`)
const EXEC_ROLE_FRONTMATTER = `---\nid: ${EXEC_ROLE}\ntitle: Exec builder\ntools:\n  - dept_exec\n---\n\nYou are an exec builder worker.\n`

/** Snapshot a role template under presets/departments/research/<role>.md (its
 * content, or absence) so a fixture write/remove restores the exact state.
 * fb-33: the snapshot is taken from GIT HEAD — the untracked execbuilder.md
 * restores to ABSENCE (its pristine HEAD state), a tracked role restores to
 * its exact HEAD bytes — never from the worktree file, so an interrupted-run
 * corruption is HEALED, not "repaired" with itself. */
async function snapshotRoleTemplate(role) {
  const p = path.join(F10_REPO_ROOT, 'presets', 'departments', 'research', `${role}.md`)
  const head = gitHeadPresetContent(`presets/departments/research/${role}.md`)
  if (head !== undefined) {
    return async function restoreRoleTemplate() {
      if (head.kind === 'content') await writeFile(p, head.data, 'utf8')
      else await rm(p, { force: true })
    }
  }
  // Fallback (no git): snapshot the CURRENT worktree file BEFORE any write.
  let content = null
  try {
    content = await readFile(p, 'utf8')
  } catch (err) {
    if (err?.code !== 'ENOENT') throw err
  }
  return async function restoreRoleTemplate() {
    if (content === null) await rm(p, { force: true })
    else await writeFile(p, content, 'utf8')
  }
}

test('B2 dept_exec (real Loader): a worker whose role DECLARES dept_exec runs a scoped command in-workspace; denied commands/cwd/paths are a clean OUT_OF_SCOPE error; a role without it never sees the tool; the host plane has NO dept_exec', async () => {
  const restore = await snapshotRoleTemplate(EXEC_ROLE)
  try {
    await writeFile(EXEC_ROLE_PATH, EXEC_ROLE_FRONTMATTER, 'utf8')
    await withTempStateDir(async (stateDir) => {
      const { root, agents, head, headCtx, key, dispose } = await bootWithHead(stateDir)
      try {
        const signal = new AbortController().signal
        const { worker, ctx: workerCtx, key: workerKey, result } = await f3Spawn({ agents }, headCtx, key, head, { role: EXEC_ROLE, task: 'scoped build' })
        // The role declares dept_exec → the worker OWNS it (own-layer).
        const exec = workerCtx.tools.get('dept_exec', workerKey)
        assert.ok(exec, 'dept_exec is installed for a role whose template declares it')
        assert.equal(root.tools.get('dept_exec'), undefined, 'the host plane has NO dept_exec (never global)')

        // Positive path: the default cwd is the department workspace/session root
        // (stateDir, inside a scoped root in this fixture) → `echo ok` runs.
        const run = await exec.execute({ command: 'echo ok' }, { agent: worker, signal })
        assert.equal(run.ok, true, 'a scoped command succeeds')
        assert.equal(run.exitCode, 0, 'a scoped command exits 0')
        assert.match(run.stdout, /ok/, 'the command stdout is surfaced')

        // Denylist (case-insensitive substring) → DENIED before any execution.
        await assert.rejects(
          () => exec.execute({ command: 'sudo rm -rf /tmp/x' }, { agent: worker, signal }),
          /OUT_OF_SCOPE \/ DENIED — command contains a denied token "sudo"/, 'a sudo-style command is denied'
        )

        // A MUTATING systemctl form (not the read-only `is-active`) → DENIED
        // before any execution (the read-only `is-active` allow is asserted
        // deterministically in the PURE guard test below, not by running a real
        // systemctl in this hermetic fixture).
        await assert.rejects(
          () => exec.execute({ command: 'systemctl status' }, { agent: worker, signal }),
          /command contains a denied systemctl form/, 'a mutating systemctl-style command is denied'
        )

        // The protected stable-profile token → the specific protected reason.
        await assert.rejects(
          () => exec.execute({ command: 'cat /opt/dsh/.dsh/config.yml' }, { agent: worker, signal }),
          /the stable profile is protected — requires explicit owner approval via the Asistente/, 'a /opt/dsh/.dsh reference is protected-denied'
        )

        // The DEV deployment home (`/opt/dsh/.dsh-dev`) is NOT stable — a command
        // referencing it is ALLOWED (the boundary-aware token must not deny `-dev`).
        const devRun = await exec.execute({ command: 'echo /opt/dsh/.dsh-dev' }, { agent: worker, signal })
        assert.equal(devRun.ok, true, 'a command referencing the DEV home is allowed (not stable)')
        assert.match(devRun.stdout, /\/opt\/dsh\/\.dsh-dev/, 'the dev-home command actually ran')

        // A NO-SPACE redirect target (`>/etc/foo`) is now a scoped abs-path token
        // → OUT_OF_SCOPE (not a silent false-negative allow).
        await assert.rejects(
          () => exec.execute({ command: 'echo hi >/etc/foo' }, { agent: worker, signal }),
          /command references absolute path "\/etc\/foo" outside a scoped dept_exec root/, 'a no-space redirect target outside a root is out of scope'
        )

        // W5-B2c: the fd-redirect digit-guard is REMOVED — an fd-redirect into a
        // non-root path (`2>/etc/foo`) is now a scoped abs-path token → OUT_OF_SCOPE.
        await assert.rejects(
          () => exec.execute({ command: 'echo hi 2>/etc/foo' }, { agent: worker, signal }),
          /command references absolute path "\/etc\/foo" outside a scoped dept_exec root/, 'an fd-redirect into a non-root path is out of scope'
        )

        // An absolute path token outside a scoped root → OUT_OF_SCOPE.
        await assert.rejects(
          () => exec.execute({ command: 'ls /etc/passwd' }, { agent: worker, signal }),
          /command references absolute path "\/etc\/passwd" outside a scoped dept_exec root/, 'an absolute path outside a root is out of scope'
        )

        // W5-B2c: a `..`-escape THROUGH an allowed root is canonicalized to its
        // real target → OUT_OF_SCOPE (not a lexical false-allow).
        await assert.rejects(
          () => exec.execute({ command: 'cat /home/esuarez/projects/deepartments/../../root/.ssh/id_rsa' }, { agent: worker, signal }),
          /command references absolute path "\/home\/esuarez\/projects\/deepartments\/\.\.\/\.\.\/root\/\.ssh\/id_rsa" outside a scoped dept_exec root/, 'a `..`-escape through an allowed root is out of scope'
        )

        // An absolute path UNDER a scoped root is allowed (repo root).
        const repoRun = await exec.execute({ command: `cat ${path.join(F10_REPO_ROOT, 'README.md')}` }, { agent: worker, signal })
        assert.equal(repoRun.ok, true, 'an absolute path under a scoped root runs')

        // W5-B2c: the /dev sink whitelist — an fd-redirect into /dev/null is
        // ALLOWED (not a lexical deny); it actually runs.
        const devNullRun = await exec.execute({ command: 'ls 2>/dev/null' }, { agent: worker, signal })
        assert.equal(devNullRun.ok, true, 'an fd-redirect into /dev/null is allowed')
        assert.equal(devNullRun.exitCode, 0, 'the /dev/null redirect command exits 0')

        // W5-B2c: a redirect TARGET under a scoped root is ALLOWED — it writes
        // into the temp stateDir (a scoped root), not an out-of-scope path.
        const redirectRun = await exec.execute({ command: `cat ${path.join(F10_REPO_ROOT, 'README.md')} > ${path.join(stateDir, 'scratch.txt')}` }, { agent: worker, signal })
        assert.equal(redirectRun.ok, true, 'a redirect target under a scoped root runs')

        // cwd outside the scoped roots → DENIED.
        await assert.rejects(
          () => exec.execute({ command: 'echo hi', cwd: '/etc' }, { agent: worker, signal }),
          /cwd "\/etc" is not inside a scoped dept_exec root/, 'a cwd outside the scoped roots is denied'
        )

        // A role (researcher) that does NOT declare dept_exec never sees it.
        const researcher = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'investigate' })
        assert.equal(researcher.ctx.tools.get('dept_exec', researcher.key), undefined, 'a role without dept_exec does not inherit the tool')
        assert.equal(researcher.ctx.tools.get('dept_worker_spawn', researcher.key), undefined, 'the researcher peer still lacks the head lifecycle tools (no cross-contamination)')
      } finally {
        await dispose()
      }
    })
  } finally {
    await restore()
  }
})

test('B2 dept_exec mission grant (real Loader, QH auto-file item 1/2): an explicit `org.missionExecRoots` entry is read by the allowedRoots assembly → the worker may run a command referencing the GRANTED stable home `/opt/dsh/.dsh`; the same grant is config-recorded, and without it the stable home stays protected-denied', async () => {
  const restore = await snapshotRoleTemplate(EXEC_ROLE)
  try {
    await writeFile(EXEC_ROLE_PATH, EXEC_ROLE_FRONTMATTER, 'utf8')
    await withTempStateDir(async (stateDir) => {
      // A config with an EXPLICIT mission-level owner grant naming the stable home.
      const { agents, head, headCtx, key, dispose } = await bootWithHead(stateDir, { org: { departments: TEST_ORG.departments, missionExecRoots: ['/opt/dsh/.dsh'] } })
      try {
        const signal = new AbortController().signal
        const { worker, ctx: workerCtx, key: workerKey } = await f3Spawn({ agents }, headCtx, key, head, { role: EXEC_ROLE, task: 'owner-authorized mission' })
        const exec = workerCtx.tools.get('dept_exec', workerKey)
        assert.ok(exec, 'dept_exec is installed for the exec role')
        // The grant is read by deptExecAllowedRoots (config.org.missionExecRoots):
        // a command referencing /opt/dsh/.dsh is ALLOWED (echo only touches the
        // literal, so this is deterministic and needs no stable shell access).
        const grantedRun = await exec.execute({ command: 'echo /opt/dsh/.dsh' }, { agent: worker, signal })
        assert.equal(grantedRun.ok, true, 'a command referencing the GRANTED stable home is allowed')
        assert.match(grantedRun.stdout, /\/opt\/dsh\/\.dsh/, 'the granted command actually ran')
        // Config-recorded: the schema normalizes/returns the grant verbatim too.
        const schemaOrg = configSchema({ stateDir, org: { departments: TEST_ORG.departments, missionExecRoots: ['/opt/dsh/.dsh'] } }).org
        assert.deepEqual(schemaOrg.missionExecRoots, ['/opt/dsh/.dsh'], 'the mission grant is config-recorded (auditable)')
      } finally {
        await dispose()
      }
    })
  } finally {
    await restore()
  }
})

test('B2 dept_exec guard (pure): deptExecDenyReason centralizes the scope policy (cwd root, denylist, boundary-aware stable-profile token, absolute-path tokens)', () => {
  const roots = ['/home/esuarez/projects', '/usr/lib/node_modules/@deepseek-ai/dsh', '/srv/dept-ws', '/opt/dsh/.dsh-dev']
  // cwd inside a root → no deny for a harmless command.
  assert.equal(deptExecDenyReason('echo ok', '/srv/dept-ws', roots), undefined, 'an in-root cwd + harmless command passes')
  assert.equal(deptExecDenyReason('cat /home/esuarez/projects/README.md', '/srv/dept-ws', roots), undefined, 'an absolute path under a root passes')
  // cwd outside the roots → out of scope.
  assert.match(deptExecDenyReason('echo ok', '/etc', roots), /OUT_OF_SCOPE \/ DENIED — cwd "\/etc"/, 'cwd outside the roots is out of scope')
  // denylist (case-insensitive) — reboot/sudo/etc unchanged, systemctl is a
  // DEDICATED carve-out below (mutating forms denied, read-only is-active allowed).
  assert.match(deptExecDenyReason('sudo rm -rf /tmp/x', '/srv/dept-ws', roots), /denied token "sudo"/, 'sudo is denied')
  assert.match(deptExecDenyReason('reboot now', '/srv/dept-ws', roots), /denied token "reboot"/, 'reboot is denied')
  // systemctl carve-out: a MUTATING form is denied, the READ-ONLY is-active is allowed.
  assert.match(deptExecDenyReason('SYSTEMCTL list-units', '/srv/dept-ws', roots), /command contains a denied systemctl form/, 'a mutating systemctl form is denied (case-insensitive)')
  assert.match(deptExecDenyReason('systemctl restart dsh.service', '/srv/dept-ws', roots), /command contains a denied systemctl form/, 'systemctl restart is denied')
  assert.match(deptExecDenyReason('systemctl start dsh.service', '/srv/dept-ws', roots), /command contains a denied systemctl form/, 'systemctl start is denied')
  assert.match(deptExecDenyReason('systemctl stop dsh.service', '/srv/dept-ws', roots), /command contains a denied systemctl form/, 'systemctl stop is denied')
  assert.equal(deptExecDenyReason('systemctl is-active dsh.service', '/srv/dept-ws', roots), undefined, 'the read-only systemctl is-active is allowed')
  assert.equal(deptExecDenyReason('systemctl is-active dsh.service && foo', '/srv/dept-ws', roots)?.includes('denied systemctl form') === true, true, 'a chained is-active (&&) is NOT read-only → denied')
  // the protected stable-profile token (boundary-aware).
  assert.match(deptExecDenyReason('cat /opt/dsh/.dsh/agent.cordis.yml', '/srv/dept-ws', roots), /the stable profile is protected/, 'the stable-profile token is protected-denied')
  // (the /opt/dsh/.dsh-vs-/.dsh-dev boundary discrimination is the DEDICATED test
  // below — the W5-R2 review coverage gap that missed the (c) bug)
  // a `su -` denylist match (denylist includes "su -").
  assert.match(deptExecDenyReason('su - root', '/srv/dept-ws', roots), /denied token "su -"/, 'su - is denied')
  // an absolute path outside the roots → out of scope.
  assert.match(deptExecDenyReason('cat /etc/passwd', '/srv/dept-ws', roots), /references absolute path "\/etc\/passwd"/, 'an absolute path outside the roots is out of scope')
  // (d) a NO-SPACE redirect target is now a scoped abs-path token → OUT_OF_SCOPE.
  assert.match(deptExecDenyReason('echo hi >/etc/foo', '/srv/dept-ws', roots), /references absolute path "\/etc\/foo" outside a scoped dept_exec root/, 'a no-space redirect target outside a root is out of scope')
  // the fixed default roots are the documented set (DEV home present, stable out).
  assert.ok(DEPT_EXEC_DEFAULT_ROOTS.includes('/home/esuarez/projects'), 'the fixed default roots include the projects root')
  assert.ok(DEPT_EXEC_DEFAULT_ROOTS.includes('/opt/dsh/.dsh-dev'), 'the fixed default roots include the DEV deployment home')
  assert.ok(!DEPT_EXEC_DEFAULT_ROOTS.includes('/opt/dsh/.dsh'), 'the stable home is NOT a dept_exec root')
})

test('B2 dept_exec guard (boundary, W5-R2 review gap): the protected stable token is a WHOLE path component — a cwd/command under `/opt/dsh/.dsh` is DENIED while `/opt/dsh/.dsh-dev` (and anything under it) is ALLOWED', () => {
  const roots = ['/home/esuarez/projects', '/usr/lib/node_modules/@deepseek-ai/dsh', '/srv/dept-ws', '/opt/dsh/.dsh-dev']
  // (b) the boundary-aware primitive itself (pure, exported) — the literal token
  // is matched only as a whole path component, so the `-dev` sibling is excluded.
  assert.equal(isStablePath('/opt/dsh/.dsh'), true, 'the stable home is stable')
  assert.equal(isStablePath('/opt/dsh/.dsh/'), true, 'the stable home (trailing /) is stable')
  assert.equal(isStablePath('/opt/dsh/.dsh/.deepartments'), true, 'a path under the stable home is stable')
  assert.equal(isStablePath('cat /opt/dsh/.dsh/x'), true, 'a command referencing the stable home is stable')
  assert.equal(isStablePath('/opt/dsh/.dsh-dev'), false, 'the DEV home is NOT stable')
  assert.equal(isStablePath('/opt/dsh/.dsh-dev/runner'), false, 'a path under the DEV home is NOT stable')
  assert.equal(isStablePath('cat /opt/dsh/.dsh-dev/x'), false, 'a command referencing the DEV home is NOT stable')
  // (c) the explicit stable home (exact path or anything under it) in a command
  // is protected-denied.
  assert.match(deptExecDenyReason('cat /opt/dsh/.dsh', '/srv/dept-ws', roots), /the stable profile is protected/, 'the exact stable home in a command is protected-denied')
  assert.match(deptExecDenyReason('cat /opt/dsh/.dsh/./x', '/srv/dept-ws', roots), /the stable profile is protected/, 'anything under the stable home in a command is protected-denied')
  // (c) a cwd AT/UNDER the stable home is denied too — via the cwd-in-root check,
  // because the stable home is deliberately NOT a dept_exec root.
  assert.match(deptExecDenyReason('echo ok', '/opt/dsh/.dsh', roots), /is not inside a scoped dept_exec root/, 'a cwd at the stable home is denied (cwd-in-root)')
  assert.match(deptExecDenyReason('echo ok', '/opt/dsh/.dsh/.deepartments', roots), /is not inside a scoped dept_exec root/, 'a cwd under the stable home is denied (cwd-in-root)')
  // (a) a cwd under the DEV home is ALLOWED (not denied by any rule).
  assert.equal(deptExecDenyReason('echo ok', '/opt/dsh/.dsh-dev/runner', roots), undefined, 'a cwd under the DEV home is allowed (not denied by any rule)')
  // (b) a command referencing the DEV home is ALLOWED (not stable).
  assert.equal(deptExecDenyReason('cat /opt/dsh/.dsh-dev/agent.cordis.yml', '/srv/dept-ws', roots), undefined, 'a command referencing the DEV home is allowed (not stable)')
})

test('B2 dept_exec guard (mission grant, QH auto-file item 1/2): an explicit MISSION-LEVEL owner grant (`org.missionExecRoots`) adds the STABLE home as an allowed root → the GRANTED stable path is ALLOWED; WITHOUT the grant the stable home stays DENIED (no silent widening); the grant bypasses ONLY the stable token, never the rest of the guard', () => {
  const base = ['/home/esuarez/projects', '/usr/lib/node_modules/@deepseek-ai/dsh', '/srv/dept-ws', '/opt/dsh/.dsh-dev']
  const grantRoots = [...base, '/opt/dsh/.dsh'] // the realpath-resolved missionExecRoots entry
  // (c) WITHOUT the grant — the default deny is UNCHANGED (no silent widening).
  assert.equal(isStableHomeGranted(base), false, 'without a grant the stable home is NOT granted')
  assert.match(deptExecDenyReason('cat /opt/dsh/.dsh/settings.yaml', '/srv/dept-ws', base), /the stable profile is protected/, 'without a grant a stable-home command stays protected-denied')
  assert.match(deptExecDenyReason('echo ok', '/opt/dsh/.dsh', base), /is not inside a scoped dept_exec root/, 'without a grant a cwd at the stable home is denied (cwd-in-root)')
  // (a) WITH the grant — the granted stable path is ALLOWED (explicit, not silent).
  assert.equal(isStableHomeGranted(grantRoots), true, 'with a grant the stable home IS granted')
  assert.equal(deptExecDenyReason('cat /opt/dsh/.dsh/settings.yaml', '/srv/dept-ws', grantRoots), undefined, 'with a grant a command under the stable home is allowed')
  assert.equal(deptExecDenyReason('echo ok', '/opt/dsh/.dsh', grantRoots), undefined, 'with a grant a cwd at the stable home is allowed')
  assert.equal(deptExecDenyReason('cat /opt/dsh/.dsh/.deepartments/posts.json', '/opt/dsh/.dsh', grantRoots), undefined, 'with a grant a cwd + command under the stable home are allowed')
  // The grant is SURGICAL — it lifts ONLY the stable token, never the other guards:
  // a mutating systemctl, `sudo`, and an out-of-root abs path are STILL denied.
  assert.match(deptExecDenyReason('systemctl restart dsh.service', '/opt/dsh/.dsh', grantRoots), /denied systemctl form/, 'a mutating systemctl is STILL denied even with the grant')
  assert.match(deptExecDenyReason('sudo cat /opt/dsh/.dsh/settings.yaml', '/opt/dsh/.dsh', grantRoots), /denied token "sudo"/, 'sudo is STILL denied even with the grant')
  assert.match(deptExecDenyReason('cat /etc/passwd', '/opt/dsh/.dsh', grantRoots), /references absolute path "\/etc\/passwd"/, 'an out-of-root path is STILL denied even with the grant')
  // The DEV home never grants the stable home (a `-dev` root does not widen).
  assert.equal(isStableHomeGranted(['/opt/dsh/.dsh-dev']), false, 'the DEV home never grants the stable home')
  // The config schema accepts org.missionExecRoots (absent → [], present → verbatim).
  const sAbsent = configSchema({ stateDir: '.d', org: { departments: [{ id: 'r', name: 'R' }] } })
  assert.deepEqual(sAbsent.org.missionExecRoots, [], 'absent org.missionExecRoots defaults to []')
  const sGranted = configSchema({ stateDir: '.d', org: { departments: [{ id: 'r', name: 'R' }], missionExecRoots: ['/opt/dsh/.dsh'] } })
  assert.deepEqual(sGranted.org.missionExecRoots, ['/opt/dsh/.dsh'], 'a granted org.missionExecRoots entry is preserved verbatim')
})

test('B2 dept_exec guard (read-only systemctl helper, QH auto-file item 3): `isReadOnlySystemctl` permits EXACTLY the single `systemctl is-active <unit>` form and NOTHING else on the same line; every mutating systemctl form is not read-only', () => {
  assert.equal(isReadOnlySystemctl('systemctl is-active dsh.service'), true, 'the canonical read-only form is read-only')
  assert.equal(isReadOnlySystemctl('systemctl is-active'), true, 'is-active with no unit is read-only')
  assert.equal(isReadOnlySystemctl('/usr/bin/systemctl is-active dsh.service'), true, 'a path-prefixed systemctl is read-only')
  assert.equal(isReadOnlySystemctl('SYSTEMCTL IS-ACTIVE dsh.service'), true, 'is-active is case-insensitive')
  // NOT read-only — the mutating/other forms.
  assert.equal(isReadOnlySystemctl('systemctl restart dsh.service'), false, 'restart is not read-only')
  assert.equal(isReadOnlySystemctl('systemctl start dsh.service'), false, 'start is not read-only')
  assert.equal(isReadOnlySystemctl('systemctl stop dsh.service'), false, 'stop is not read-only')
  assert.equal(isReadOnlySystemctl('systemctl enable dsh.service'), false, 'enable is not read-only')
  assert.equal(isReadOnlySystemctl('systemctl status dsh.service'), false, 'status is not read-only')
  assert.equal(isReadOnlySystemctl('systemctl list-units'), false, 'list-units is not read-only')
  assert.equal(isReadOnlySystemctl('systemctl daemon-reload'), false, 'daemon-reload is not read-only')
  // NOT read-only — NOTHING ELSE on the same line (no chaining/leading command).
  assert.equal(isReadOnlySystemctl('systemctl is-active dsh.service && foo'), false, 'a chained is-active is NOT read-only')
  assert.equal(isReadOnlySystemctl('echo x; systemctl is-active dsh.service'), false, 'a leading command sep is NOT read-only')
  assert.equal(isReadOnlySystemctl('systemctl is-active dsh.service | grep active'), false, 'a piped is-active is NOT read-only')
})

test('B2 dept_exec guard (token normalization, W5-B2c review gap): a `..`-escape THROUGH an allowed root is canonicalized to its real target → OUT_OF_SCOPE; the fd-redirect digit-guard is REMOVED so every `>`/`<`-adjacent absolute path token is checked, EXCEPT the /dev sink whitelist (always allowed)', () => {
  const roots = ['/home/esuarez/projects', '/usr/lib/node_modules/@deepseek-ai/dsh', '/srv/dept-ws', '/opt/dsh/.dsh-dev']
  // (a) traversal — `..`-escapes through an allowed root collapse to a REAL path
  // outside the roots → OUT_OF_SCOPE (not a lexical false-allow).
  assert.match(
    deptExecDenyReason('cat /home/esuarez/projects/deepartments/../../root/.ssh/id_rsa', '/srv/dept-ws', roots),
    /command references absolute path "\/home\/esuarez\/projects\/deepartments\/\.\.\/\.\.\/root\/\.ssh\/id_rsa" outside a scoped dept_exec root/,
    'a `..`-escape through an allowed root is out of scope'
  )
  // (b) an fd-redirect into a non-root path is NO LONGER skipped by a digit-guard.
  assert.match(
    deptExecDenyReason('echo hi 2>/etc/foo', '/srv/dept-ws', roots),
    /command references absolute path "\/etc\/foo" outside a scoped dept_exec root/,
    'an fd-redirect into a non-root path is out of scope'
  )
  // (c) the /dev sink whitelist is ALWAYS allowed (not realpath'd, not under a root).
  assert.equal(deptExecDenyReason('ls 2>/dev/null', '/srv/dept-ws', roots), undefined, 'an fd-redirect into /dev/null is allowed')
  assert.equal(deptExecDenyReason('cat x > /dev/stdout', '/srv/dept-ws', roots), undefined, '/dev/stdout is whitelisted')
  assert.equal(deptExecDenyReason('cat x > /dev/stderr', '/srv/dept-ws', roots), undefined, '/dev/stderr is whitelisted')
  assert.equal(deptExecDenyReason('cat x > /dev/zero', '/srv/dept-ws', roots), undefined, '/dev/zero is whitelisted')
  assert.equal(deptExecDenyReason('cat x > /dev/tty', '/srv/dept-ws', roots), undefined, '/dev/tty is whitelisted')
  // (d) a redirect TARGET under an allowed root is ALLOWED (both tokens are scoped).
  assert.equal(
    deptExecDenyReason('cat /home/esuarez/projects/deepartments/README.md > /home/esuarez/projects/scratch.txt', '/srv/dept-ws', roots),
    undefined,
    'a redirect target under an allowed root is allowed'
  )
  // The whitelist is SURGICAL — a non-whitelisted out-of-scope token is still denied
  // even when the command ALSO redirects to /dev/null.
  assert.match(
    deptExecDenyReason('cat /etc/passwd 2>/dev/null', '/srv/dept-ws', roots),
    /command references absolute path "\/etc\/passwd" outside a scoped dept_exec root/,
    'the /dev whitelist does not mask a non-whitelisted out-of-scope path'
  )
  // A `..`-escape that normalizes to the STABLE home is protected-denied — the
  // boundary token now sees the CANONICAL target, not the raw lexical form.
  assert.match(
    deptExecDenyReason('cat /home/esuarez/projects/x/../../../../opt/dsh/.dsh/agent.cordis.yml', '/srv/dept-ws', roots),
    /the stable profile is protected/,
    'a `..`-escape to the stable home is protected-denied'
  )
})

test('B2 dept_exec guard (fb-10, QH): URL-LIKE ARITHMETIC tokens are NOT paths — `$((10-fails))/10`, a pipeline with `/3600000` and `//3600000` are NO LONGER denied; `$((...))` internals never tokenize; real letter-bearing paths PRESERVE access (inside roots allowed, outside roots denied)', () => {
  const roots = ['/home/esuarez/projects', '/usr/lib/node_modules/@deepseek-ai/dsh', '/srv/dept-ws', '/opt/dsh/.dsh-dev']
  // (1) the QH native reproduction — `$((10-fails))/10` (a division by 10) is NOT denied.
  assert.equal(deptExecDenyReason('echo $((10-fails))/10', '/srv/dept-ws', roots), undefined, '`$((10-fails))/10` is a division, not a path')
  // (2) a pipeline with `/3600000` and `//3600000` (ms→h unit division) is NOT denied.
  assert.equal(deptExecDenyReason('echo $((86400000/24)) //3600000 | cat', '/srv/dept-ws', roots), undefined, 'a pipeline with /3600000 and //3600000 units is not denied')
  assert.equal(deptExecDenyReason('echo $((ms))/3600000 | awk "{printf \\"%.2f\\", \\$1}"', '/srv/dept-ws', roots), undefined, 'a bare /3600000 division after arithmetic is not denied')
  // (2b) the `$((...))` INTERNALS never tokenize — even a LETTER term (`/ b`) inside
  // arithmetic is not a path (rule (b): arithmetic is opaque to the path scanner).
  assert.equal(deptExecDenyReason('echo $((a / b))', '/srv/dept-ws', roots), undefined, 'an arithmetic-internal `/ b` term is not a path')
  // (4) the ACCESS flow is intact: a real path INSIDE a root stays allowed.
  assert.equal(deptExecDenyReason('cat /opt/dsh/.dsh-dev/settings.yaml', '/srv/dept-ws', roots), undefined, 'a real path inside a root stays allowed')
  assert.equal(deptExecDenyReason('cat /home/esuarez/projects/README.md', '/srv/dept-ws', roots), undefined, 'a real in-root path stays allowed')
  // (3) a real path OUTSIDE the roots stays DENIED (access preserved): drop the DEV
  // home from the roots → the very same /opt/dsh/.dsh-dev/settings.yaml is out of scope.
  const rootsNoDev = ['/home/esuarez/projects', '/usr/lib/node_modules/@deepseek-ai/dsh', '/srv/dept-ws']
  assert.match(deptExecDenyReason('cat /opt/dsh/.dsh-dev/settings.yaml', '/srv/dept-ws', rootsNoDev), /command references absolute path "\/opt\/dsh\/\.dsh-dev\/settings\.yaml" outside a scoped dept_exec root/, 'a real letter-bearing path outside the roots is STILL denied')
  assert.match(deptExecDenyReason('cat /etc/passwd', '/srv/dept-ws', roots), /references absolute path "\/etc\/passwd"/, 'an out-of-root real path stays denied')
  // The masking is SURGICAL — a REAL absolute path DIRECTLY after `$((...))` (no
  // space) keeps its own boundary and is STILL scoped-checked (no smuggling).
  assert.match(deptExecDenyReason('cat $((x))/etc/passwd', '/srv/dept-ws', roots), /references absolute path "\/etc\/passwd"/, 'a real path right after arithmetic is STILL denied')
  // The digit rule is SURGICAL — a multi-segment real path with digits under a
  // root stays ALLOWED (only `/`+digits-ONLY words are divisions, never a path shape).
  assert.equal(deptExecDenyReason('cat /home/esuarez/projects/deepartments/v1/bin/run.sh', '/srv/dept-ws', roots), undefined, 'a multi-segment real path under a root stays allowed')
})

// ===========================================================================
// E2-ZSTD (QH 2026-08-28): dept_zstd_read — the READ-ONLY .zstd session reader
// for department posts (registered on the SAME `allowExec` gate as dept_exec,
// so the roles that declare dept_exec — IPD builder/reviewer/explore-deep +
// quality-inspector — also get it). The deny guard + the bounded decode are
// PURE (unit-tested); the real-Loader test verifies the tool through a
// dept_exec-declaring worker (no dept_exec call needed for a .zstd read).
// ===========================================================================

test('E2 dept_zstd_read (pure): deptZstdReadDenyReason — a path inside an allowed root passes; outside the roots / the protected stable profile are DENIED; a mission grant un-protects the stable home for the named root', () => {
  const roots = ['/srv/dept-ws', '/opt/dsh/.dsh-dev']
  assert.equal(deptZstdReadDenyReason('/srv/dept-ws/archive/session.jsonl.zstd', roots), undefined, 'a path inside an allowed root passes')
  assert.equal(deptZstdReadDenyReason('/srv/dept-ws', roots), undefined, 'the root itself passes')
  assert.match(deptZstdReadDenyReason('/etc/passwd', roots), /OUT_OF_SCOPE \/ DENIED — path "\/etc\/passwd" is not inside a scoped dept_exec root/, 'a path outside the roots is denied')
  assert.match(deptZstdReadDenyReason('/opt/dsh/.dsh/settings.yaml', roots), /the stable profile is protected/, 'the stable home is protected-denied WITHOUT a grant')
  assert.equal(deptZstdReadDenyReason('/opt/dsh/.dsh-dev/sessions/x.jsonl.zstd', roots), undefined, 'the DEV home is allowed (not stable)')
  const grantRoots = [...roots, '/opt/dsh/.dsh']
  assert.equal(deptZstdReadDenyReason('/opt/dsh/.dsh/sessions/x.jsonl.zstd', grantRoots), undefined, 'a mission grant naming the stable home allows it')
  assert.match(deptZstdReadDenyReason('/etc/passwd', grantRoots), /not inside a scoped dept_exec root/, 'an out-of-root path is STILL denied even with the grant')
})

test('E2 dept_zstd_read (pure): runDeptZstdRead decodes a real .zstd file through `zstd -dc` with the bounded line WINDOW (offset/lines), the per-line cap and the line cap; a decode failure is an ok:false result, never a throw', async () => {
  await withTempStateDir(async (stateDir) => {
    const dataPath = path.join(stateDir, 'session.jsonl.zstd')
    await writeFile(dataPath, Buffer.concat([
      await compressZstdFrame('{ "type": "session", "seq": 0 }\n'),
      await compressZstdFrame([1, 2, 3, 4, 5].map((n) => `{ "type": "turn", "seq": ${n} }`).join('\n') + '\n')
    ]))
    // Full decode → the whole artifact (header frame + event frame).
    const all = await runDeptZstdRead(dataPath, 0, 100)
    assert.equal(all.ok, true, 'a real .zstd fixture decodes')
    assert.equal(all.lines.length, 6, 'all 6 lines of the fixture decode (header + 5 events)')
    assert.match(all.lines[0], /"type": "session"/, 'the header frame line decodes first')
    assert.equal(all.truncated, false, 'a small fixture is not truncated')
    // A WINDOW: offset 2, lines 2 → exactly the third + fourth lines.
    const window = await runDeptZstdRead(dataPath, 2, 2)
    assert.equal(window.ok, true, 'the offset/lines window decodes')
    assert.deepEqual(window.lines, ['{ "type": "turn", "seq": 2 }', '{ "type": "turn", "seq": 3 }'], 'the window [offset, offset+lines) is returned')
    // The line cap: requested lines beyond the cap are clamped to
    // DEPT_ZSTD_READ_MAX_LINES (never a giant output).
    const capped = await runDeptZstdRead(dataPath, 0, 99999)
    assert.equal(capped.lines.length, 6, 'a huge lines request returns only the existing (bounded) content')
    // A decode failure (corrupt zstd, or a non-zstd file) → ok:false with the
    // stderr surfaced (never a throw).
    await writeFile(path.join(stateDir, 'garbage.bin'), 'not zstd at all', 'utf8')
    const failed = await runDeptZstdRead(path.join(stateDir, 'garbage.bin'), 0, 10)
    assert.equal(failed.ok, false, 'a non-zstd file → ok:false (never a throw)')
    assert.ok((failed.error ?? '').length > 0, 'the decode failure carries the stderr/detail')
    // An absent file → ok:false (never a throw).
    const missing = await runDeptZstdRead(path.join(stateDir, 'nope.zstd'), 0, 10)
    assert.equal(missing.ok, false, 'an absent file → ok:false')
  })
})

test('E2 dept_zstd_read (pure, fb-19): a >4MB decoded session (the b29 4.54MB class) STREAMS with the line window — NO execFile maxBuffer failure; totalLines exact, per-line cap applies, offset/lines window works', async () => {
  await withTempStateDir(async (stateDir) => {
    const dataPath = path.join(stateDir, 'big-session.jsonl.zstd')
    // ~200 lines × ~25 KB ≈ 5 MB decoded — well past the OLD 4MB maxBuffer cap
    // (the b29 archive was 4.54MB), far under the 32MB budget; the payload is
    // highly compressible so the .zstd fixture stays tiny.
    const bigLines = []
    for (let i = 0; i < 200; i++) bigLines.push(`{ "type": "turn", "seq": ${i}, "payload": "${'x'.repeat(25000)}" }`)
    await writeFile(dataPath, await compressZstdFrame(bigLines.join('\n') + '\n'))
    const all = await runDeptZstdRead(dataPath, 0, 500)
    assert.equal(all.ok, true, 'a >4MB decoded session STREAMS OK — no raw stdout maxBuffer error (fb-19)')
    assert.equal(all.totalLines, 200, 'all 200 lines are counted (exact totalLines)')
    assert.equal(all.lines.length, 200, 'the window returns all lines (under the 500 line cap)')
    assert.equal(all.truncated, false, 'the window covers the whole session (nothing cut)')
    assert.match(all.lines[0], /"seq": 0/, 'the first line decodes')
    assert.match(all.lines[0], /\[line truncated\]/, 'a >4000-char line is truncated with the marker')
    assert.match(all.lines[199], /"seq": 199/, 'the last line decodes')
    // An offset/lines WINDOW into the big session works too (the window is
    // retained, the rest streamed past without buffering).
    const window = await runDeptZstdRead(dataPath, 5, 2)
    assert.equal(window.ok, true, 'the window into the big session decodes')
    assert.deepEqual(window.lines, all.lines.slice(5, 7), 'the window matches the same lines of the full read')
  })
})

test('E2 dept_zstd_read (pure, fb-19): a session beyond the 32MB decode budget is aborted with the CLEAR budget error — NEVER a raw maxBuffer exception', async () => {
  await withTempStateDir(async (stateDir) => {
    const dataPath = path.join(stateDir, 'giant-session.jsonl.zstd')
    // ~34000 lines × ~1 KB ≈ 33 MB decoded — over the 32MB budget; highly
    // compressible, so the fixture is small on disk.
    const giantLines = []
    const payload = `{"type":"turn","p":"${'x'.repeat(1024)}"}`
    for (let i = 0; i < 34000; i++) giantLines.push(payload)
    await writeFile(dataPath, await compressZstdFrame(giantLines.join('\n') + '\n'))
    const result = await runDeptZstdRead(dataPath, 0, 500)
    assert.equal(result.ok, false, 'a session over the budget → ok:false (never a throw)')
    assert.match(result.error ?? '', /exceeds the zstd-read budget .*use dept_exec for full streaming/, 'the CLEAR budget error, never the raw stdout maxBuffer message')
  })
})

test('E2 dept_zstd_read (real Loader): a worker whose role DECLARES dept_exec owns dept_zstd_read on its OWN layer — it reads a .zstd session fixture WITHOUT dept_exec (no shell); a role without dept_exec never sees the tool; the host plane has NO dept_zstd_read; a path outside the allowed roots is DENIED', async () => {
  const restore = await snapshotRoleTemplate(EXEC_ROLE)
  try {
    await writeFile(EXEC_ROLE_PATH, EXEC_ROLE_FRONTMATTER, 'utf8')
    await withTempStateDir(async (stateDir) => {
      // A real .zstd session fixture under the temp stateDir (an allowed root —
      // the worker's department workspace resolves to stateDir in this harness).
      const artifactPath = path.join(stateDir, 'session.jsonl.zstd')
      await writeFile(artifactPath, Buffer.concat([
        await compressZstdFrame('{ "type": "session", "version": 0 }\n'),
        await compressZstdFrame('{ "type": "turn/start", "seq": 1 }\n{ "type": "turn/end", "seq": 2 }\n')
      ]))
      const { root, agents, head, headCtx, key, dispose } = await bootWithHead(stateDir)
      try {
        const signal = new AbortController().signal
        const { worker, ctx: workerCtx, key: workerKey } = await f3Spawn({ agents, root }, headCtx, key, head, { role: EXEC_ROLE, task: 'read a zstd session' })
        // The role declares dept_exec → the worker OWNS dept_zstd_read too
        // (the SAME allowExec gate — no shell needed for a .zstd read).
        const zread = workerCtx.tools.get('dept_zstd_read', workerKey)
        assert.ok(zread, 'dept_zstd_read is installed for a role whose template declares dept_exec')
        assert.equal(root.tools.get('dept_zstd_read'), undefined, 'the host plane has NO dept_zstd_read (never global)')
        assert.equal(root.tools.get('dept_zstd_read'), undefined, 'a config head never gets it via HEAD_BASE_TOOLS (no allowExec)')

        // The tool reads the .zstd fixture WITHOUT dept_exec — the text comes out.
        const read = await zread.execute({ path: artifactPath }, { agent: worker, signal })
        assert.equal(read.ok, true, 'the .zstd fixture decodes through the tool')
        assert.match(read.lines[0], /"type": "session"/, 'the session header line is surfaced')
        assert.equal(read.lines.length, 3, 'the whole fixture (3 lines) is returned by default')
        // A window read (offset/lines) works through the tool too.
        const window = await zread.execute({ path: artifactPath, offset: 1, lines: 1 }, { agent: worker, signal })
        assert.deepEqual(window.lines, ['{ "type": "turn/start", "seq": 1 }'], 'the offset/lines window through the real tool')

        // Out-of-roots path → the scope guard DENIES before any zstd decode.
        await assert.rejects(
          () => zread.execute({ path: '/etc/hostname' }, { agent: worker, signal }),
          /OUT_OF_SCOPE \/ DENIED — path "\/etc\/hostname" is not inside a scoped dept_exec root/,
          'a path outside the allowed roots is denied (the scope guard runs BEFORE the decode)'
        )

        // A worker whose role does NOT declare dept_exec never sees the tool.
        const { result: researcher, ctx: researcherCtx, key: researcherKey } = await f3Spawn({ agents, root }, headCtx, key, head, { role: 'researcher', task: 'plain researcher' })
        void researcher
        assert.equal(researcherCtx.tools.get('dept_zstd_read', researcherKey), undefined, 'a role without dept_exec does not inherit dept_zstd_read')

        // The head (manager, HEAD_BASE_TOOLS — no dept_exec) never sees it either.
        assert.equal(headCtx.tools.get('dept_zstd_read', key), undefined, 'a config head has NO dept_zstd_read')
      } finally {
        await dispose()
      }
    })
  } finally {
    await restore()
  }
})

test('B2 calendar attribution (real Loader): dept_calendar_add stamps departmentId; list with NO filter returns the FULL shared agenda; list with departmentId returns only that department; a legacy entry without departmentId is NOT matched by a filter', async () => {
  await withTempStateDir(async (stateDir) => {
    const { agents, head, headCtx, key, dispose } = await bootWithHead(stateDir, { org: TWO_DEPT_ORG })
    try {
      const signal = new AbortController().signal
      const progHead = agents.store.get('head-programming-head')
      assert.ok(progHead, 'the programming head materialized at boot')
      const progCtx = childContextFor(agents, 'head-programming-head')
      assert.ok(progCtx, 'the programming head context resolves')

      // research head adds → departmentId 'research'.
      const rEntry = await headCtx.tools.get('dept_calendar_add', key).execute({ label: 'Research sync', at: '2026-08-25T09:00:00.000Z' }, { agent: head, signal })
      assert.equal(rEntry.departmentId, 'research', 'adding via the research head stamps departmentId research')
      // programming head adds → departmentId 'programming'.
      const pEntry = await progCtx.ctx.tools.get('dept_calendar_add', progCtx.key).execute({ label: 'Programming sync', at: '2026-08-25T10:00:00.000Z' }, { agent: progHead, signal })
      assert.equal(pEntry.departmentId, 'programming', 'adding via the programming head stamps departmentId programming')

      // NO filter → the FULL shared (global) agenda, both departments.
      const all = await headCtx.tools.get('dept_calendar_list', key).execute({}, { agent: head, signal })
      assert.equal(all.count, 2, 'no filter returns the FULL shared agenda (both departments)')
      assert.deepEqual(all.entries.map((e) => e.departmentId).sort(), ['programming', 'research'], 'both departments surface in the unfiltered agenda')

      // departmentId filter → only the matching department.
      const researchOnly = await headCtx.tools.get('dept_calendar_list', key).execute({ departmentId: 'research' }, { agent: head, signal })
      assert.equal(researchOnly.count, 1, 'the research filter returns only the research entry')
      assert.equal(researchOnly.entries[0].label, 'Research sync')
      const programmingOnly = await headCtx.tools.get('dept_calendar_list', key).execute({ departmentId: 'programming' }, { agent: head, signal })
      assert.equal(programmingOnly.count, 1, 'the programming filter returns only the programming entry')
      assert.equal(programmingOnly.entries[0].label, 'Programming sync')

      // A legacy entry WITHOUT departmentId is NOT matched by a filter but stays
      // in the unfiltered (global) agenda.
      const state = readCalendarStateFile(stateDir)
      state.entries.push({ id: 'legacy-1', label: 'No dept', at: '2026-08-25T11:00:00.000Z', createdBy: 'some-old-post', fired: false })
      await writeCalendarStateFile(stateDir, state)
      const filtered = await headCtx.tools.get('dept_calendar_list', key).execute({ departmentId: 'research' }, { agent: head, signal })
      assert.equal(filtered.count, 1, 'an entry without departmentId is NOT matched by a departmentId filter')
      const unfiltered = await headCtx.tools.get('dept_calendar_list', key).execute({}, { agent: head, signal })
      assert.equal(unfiltered.count, 3, 'the unfiltered agenda still returns the legacy entry')
    } finally {
      await dispose()
    }
  })
})

