    const kinds = audit.at(-1).findings.map((f) => f.kind).sort()
    assert.deepEqual(kinds, ['context-threshold', 'pooler-capacity', 'qi-silence', 'system-idle'], 'the audit row records ALL FOUR distinct kinds')
