test('W8-c PART 2 stale-live watchdog: a catalog-live post with pending addressed messages AND no session writes for >= N min is a STALLED post (alerts once/30min, re-alerts after the window); does NOT alert with no pending messages or when NOT silent', async () => {
  await withTempStateDir(async (stateDir) => {
    const T0 = new Date(2026, 7, 24, 12, 0, 0).getTime()
    const hosts = [{ hostId: 'host-asst', sessionId: 's-live', roomId: 'board' }]
    const alerts = []
    const tick = (nowMs, posts) => runHealthDaemonTick({
      now: () => nowMs,
      stateDir,
      bootId: 'boot-w8c-2',
      hosts,
      posts,
      notifyHost: async (hostEntry, frame) => { alerts.push(frame) },
      logger: { warn: () => {} }
    })
    // (a) stalled: the last session write is >= 10min old (T0-25min) and a
    // pending addressed message (T0-20min) has NO completed turn after it.
    const stalled = { postId: 'worker-slow', retired: false, events: [{ type: 'user/message', time: T0 - 25 * 60000, data: {} }], inboxTs: [T0 - 20 * 60000] }
    await tick(T0, [stalled])
    assert.equal(alerts.length, 1, 'a stalled post ALERTS the host')
    assert.match(alerts[0], /stalled-post: worker-slow/, 'the alert names the stalled post')
    assert.match(alerts[0], /pending message/, 'the alert describes the pending-message condition')
    // (b) dedupe per post/30min: inside the window → no re-alert.
    await tick(T0 + 60_000, [stalled])
    assert.equal(alerts.length, 1, 'a second tick inside the 30min window does NOT re-alert')
    // (c) re-alert after the window.
    await tick(T0 + 31 * 60000, [stalled])
    assert.equal(alerts.length, 2, 'a tick after the 30min window re-alerts the same stalled post')
    // (d) NO pending addressed messages → NOT stalled (regardless of age).
    const noPending = { postId: 'worker-quiet', retired: false, events: [{ type: 'user/message', time: T0 - 60 * 60000, data: {} }], inboxTs: [] }
    const before = alerts.length
    await tick(T0 + 32 * 60000, [noPending])
    assert.equal(alerts.length, before, 'a post with NO pending messages is NOT stalled')
    // (e) NOT silent (recent session write) → NOT stalled, even with pending.
    const notSilent = { postId: 'worker-busy', retired: false, events: [{ type: 'turn/end', time: T0 - 60_000, data: { turn: 1, reason: { kind: 'ok' } } }], inboxTs: [T0 - 5000] }
    const before2 = alerts.length
    await tick(T0, [notSilent])
    assert.equal(alerts.length, before2, 'a post with a RECENT session write is NOT stalled')
    // (f) a RETIRED post is never flagged.
    const retired = { postId: 'worker-gone', retired: true, events: [{ type: 'user/message', time: T0 - 60 * 60000, data: {} }], inboxTs: [T0 - 20 * 60000] }
    const before3 = alerts.length
    await tick(T0 + 33 * 60000, [retired])
    assert.equal(alerts.length, before3, 'a retired post is NEVER stalled')
  })
})

// ---------------------------------------------------------------------------
// P2 (2026-08-24) system-health daemon fixes — Bug A (retired-host re-probe),
// Bug B (stalled-post false positives) + B-EXT (retired-post), Bug C (post-error
// re-alert loop, ERROR IDENTITY), and the latent single-use-iterator fix.
// ---------------------------------------------------------------------------

test('P2 Bug B: scanStalledPosts NEVER flags a RUNNING post (an in-flight turn is healthy progress, not stale) — the running flag is the disambiguator', () => {
  const T0 = 1_000_000_000_000
  // A post with a pending message + an OLD last session write (>= stale, so
  // WITHOUT the flag it WOULD be stale) BUT the LIVE agent is currently running
  // → NOT stalled (Bug B short-circuit).
  const running = { postId: 'worker-run', retired: false, running: true, events: [{ type: 'turn/start', time: T0 - 40 * 60000, data: { turn: 1 } }], inboxTs: [T0 - 20 * 60000] }
  assert.equal(scanStalledPosts([running], T0, 10).length, 0, 'a running post is NEVER stalled even with pending + old activity')
  // Control: the SAME shape without `running:true` IS stale → the running flag
  // is exactly what saves a long in-flight turn.
  const notRunning = { ...running, running: false }
  assert.equal(scanStalledPosts([notRunning], T0, 10).length, 1, 'the SAME post without the running flag is stale (control: running is the disambiguator)')
})

test('P2 Bug B: scanStalledPosts does NOT flag a post with RECENT queue/inbox traffic (fresh delivery = alive) even when its last session write is old', () => {
  const T0 = 1_000_000_000_000
  // Last session write is OLD (>= stale) but a FRESH inbox delivery (1 min ago)
  // is happening → NOT stalled (Bug B: fresh queue/delivery activity = alive).
  const receiving = { postId: 'worker-receive', retired: false, events: [{ type: 'user/message', time: T0 - 40 * 60000, data: {} }], inboxTs: [T0 - 60_000] }
  assert.equal(scanStalledPosts([receiving], T0, 10).length, 0, 'a post with a RECENT inbox delivery (fresh queue traffic) is NOT stalled')
  // Control: the same post with only OLD inbox ts IS stale (within the window).
  const quiet = { ...receiving, inboxTs: [T0 - 20 * 60000] }
  assert.equal(scanStalledPosts([quiet], T0, 10).length, 1, 'a post with no RECENT activity IS stale (control)')
})

test('P2 Bug B-EXT: scanStalledPosts NEVER flags a RETIRED post (a retired member is not a stale-live signal)', () => {
  const T0 = 1_000_000_000_000
  const retired = { postId: 'worker-gone', retired: true, running: false, events: [{ type: 'user/message', time: T0 - 60 * 60000, data: {} }], inboxTs: [T0 - 20 * 60000] }
  assert.equal(scanStalledPosts([retired], T0, 10).length, 0, 'a retired post is NEVER a stalled finding')
})

test('P2 Bug B-EXT (dormant-exclusion, owner m-169/m-174/m-192/m-193): a DORMANT post (sleepEpoch set — deliberately asleep) with STALE pre-sleep pendings produces NEITHER a stalled-post finding NOR a system-wait finding; a LIVE post with the SAME stale pendings still produces BOTH (so the exclusion does NOT over-suppress)', () => {
  const T0 = 1_000_000_000_000
  const oldTs = T0 - 40 * 60000 // 40 min old — older than the 10min stale window and the 30min wait window
  // DORMANT head: sleepEpoch set (sleeping: true) — its pre-sleep pending queue is
  // the EXPECTED dormant state, not a stuck session.
  const dormantStall = { postId: 'research-head', retired: false, sleeping: true, running: false, events: [], inboxTs: [oldTs] }
  // LIVE (awake) head: the SAME stale pendings — candidly stale, MUST be flagged.
  const liveStall = { postId: 'research-head', retired: false, running: false, events: [], inboxTs: [oldTs] }
  const stalledDormant = scanStalledPosts([dormantStall], T0, 10)
  const stalledLive = scanStalledPosts([liveStall], T0, 10)
  assert.equal(stalledDormant.length, 0, 'a DORMANT post is NEVER a stalled-post finding (its queue drains at wake)')
  assert.equal(stalledLive.length, 1, 'a LIVE post with the SAME stale pendings is STILL a stalled-post finding (no over-suppression)')
  assert.equal(stalledLive[0].postId, 'research-head', 'the stalled finding names the LIVE post')
  const dormantWait = { postId: 'research-head', retired: false, sleeping: true, events: [], hostMessages: [{ messageId: 'm-1', ts: oldTs }] }
  const liveWait = { postId: 'research-head', retired: false, events: [], hostMessages: [{ messageId: 'm-2', ts: oldTs }] }
  const waitsDormant = scanHostWaits([dormantWait], T0, SYSTEM_WAIT_DEFAULT_MS)
  const waitsLive = scanHostWaits([liveWait], T0, SYSTEM_WAIT_DEFAULT_MS)
  assert.equal(waitsDormant.length, 0, 'a DORMANT post is NEVER a system-wait finding (its queue drains at wake)')
  assert.equal(waitsLive.length, 1, 'a LIVE post with a STALE host expectation is STILL a system-wait finding (no over-suppression)')
  assert.equal(waitsLive[0].postId, 'research-head', 'the wait finding names the LIVE post')
})

test('m-228 orphaned-worker exclusion: scanStalledPosts NEVER flags a non-retired WORKER with NO live handle + NO session activity (an orphan whose retire step was cut by a restart); a LIVE worker and a configured HEAD with the SAME stale pendings are STILL flagged (no over-suppression)', () => {
  const T0 = 1_000_000_000_000
  const oldTs = T0 - 40 * 60000 // 40 min old — older than the 10min stale window
  // ORPHANED worker: non-retired + provider:"worker" + hasLiveHandle:false + NO
  // session events + a stale pending message → NOT a stalled-post finding. WITHOUT
  // the m-228 exclusion this shape IS stale (pending + no activity → the control
  // below proves it), so the exclusion is exactly what suppresses the zombie.
  const orphan = { postId: 'builder-orphan', retired: false, provider: 'worker', hasLiveHandle: false, running: false, events: [], inboxTs: [oldTs] }
  assert.equal(scanStalledPosts([orphan], T0, 10).length, 0, 'an orphaned worker (no live handle + no session activity) is NEVER a stalled-post finding')
  // CONTROL 1 — LIVE worker: provider:"worker" but hasLiveHandle:true (a live
  // AgentHandle), SAME stale pendings, not running → STILL flagged (a live-but-
  // idle worker is candidly stale, NOT an orphan — no over-suppression).
  const liveWorker = { postId: 'builder-live', retired: false, provider: 'worker', hasLiveHandle: true, running: false, events: [], inboxTs: [oldTs] }
  const liveFindings = scanStalledPosts([liveWorker], T0, 10)
  assert.equal(liveFindings.length, 1, 'a LIVE worker with stale pendings is STILL a stalled-post finding (no over-suppression)')
  assert.equal(liveFindings[0].postId, 'builder-live', 'the stalled finding names the LIVE worker')
  // CONTROL 2 — configured HEAD: provider !== "worker" (absent), no live handle,
  // SAME stale pendings → STILL flagged (a head is NEVER orphan-swept — the
  // orphan signal is strictly the disposable-worker marker).
  const head = { postId: 'research-head', retired: false, provider: undefined, hasLiveHandle: false, running: false, events: [], inboxTs: [oldTs] }
  const headFindings = scanStalledPosts([head], T0, 10)
  assert.equal(headFindings.length, 1, 'a configured HEAD with no live handle is STILL a stalled-post finding (never orphan-swept)')
  assert.equal(headFindings[0].postId, 'research-head', 'the stalled finding names the HEAD')
  // CONTROL 3 — orphaned worker WITH session activity (events present) is NOT the
  // orphan class → STILL flagged (a worker that wrote events but lost its handle
  // is not confirmed-dead; the conservative no-activity gate holds).
  const workerWithEvents = { postId: 'builder-eventful', retired: false, provider: 'worker', hasLiveHandle: false, running: false, events: [{ type: 'user/message', time: T0 - 50 * 60000, data: {} }], inboxTs: [oldTs] }
  assert.equal(scanStalledPosts([workerWithEvents], T0, 10).length, 1, 'a worker with (old) session activity is still flagged — the orphan class requires NO activity')
})

test('P2 Bug A (defense-in-depth): scanPostErrorFindings skips a row whose postId is a RETIRED host id (a legacy disk row never re-alerts the live host)', async () => {
  await withTempStateDir(async (stateDir) => {
    const T0 = 1_700_000_000_000
    await writeFile(path.join(stateDir, 'post-errors.jsonl'), [
      JSON.stringify({ ts: T0, postId: 'host-retired', messageId: 'm-1', error: 'session "s" not found' }),
      JSON.stringify({ ts: T0 + 1000, postId: 'host-live', error: 'boom' })
    ].join('\n') + '\n', 'utf8')
    const all = scanPostErrorFindings(stateDir, T0 + 10_000)
    assert.ok(all.some((f) => f.postId === 'host-retired'), 'without the retired set the retired-host row is a finding (legacy)')
    const filtered = scanPostErrorFindings(stateDir, T0 + 10_000, new Set(['host-retired']))
    assert.ok(!filtered.some((f) => f.postId === 'host-retired'), 'with the retired-host set a retired-host row is NEVER a finding (Bug A)')
    assert.ok(filtered.some((f) => f.postId === 'host-live'), 'a live-host row is still a finding')
  })
})

