test('P2 Bug A cross-boot regression (real Loader): a boot with a LIVE + RETIRED host in hosts.json NEVER alerts a legacy retired-host post-error row (scanPostErrorFindings retiredHostIds skip + busDeliverToHost retired short-circuit) across >=2 consecutive boots', async () => {
  await withTempStateDir(async (stateDir) => {
    const liveSessionId = SessionId(randomUUID())
    const retiredSessionId = SessionId(randomUUID())
    const liveHostId = `host-${liveSessionId}`
    const retiredHostId = `host-${retiredSessionId}`
    const T0 = new Date(2026, 7, 24, 12, 0, 0).getTime()
    // (i) Seed a hosts.json with a LIVE host + a RETIRED host (v2 rotation shape).
    await writeFile(path.join(stateDir, 'hosts.json'), JSON.stringify({
      schemaVersion: 2,
      [liveHostId]: { sessionId: String(liveSessionId), roomId: 'board' },
      [retiredHostId]: { sessionId: String(retiredSessionId), roomId: 'board', retired: true, retiredAt: T0 - 1000, rotatedTo: liveHostId }
    }, null, 2))
    // The retired-host `session not found` post-error row (the 17:08 deploy
    // noise the P2 silence invariant must never re-alert the live host with).
    await writeFile(path.join(stateDir, 'post-errors.jsonl'), JSON.stringify({ ts: T0 - 60_000, postId: retiredHostId, messageId: 'm-retired', error: `session "${retiredSessionId}" not found` }) + '\n', 'utf8')

    const hostList = () => [
      { hostId: liveHostId, sessionId: String(liveSessionId), roomId: 'board' },
      { hostId: retiredHostId, sessionId: String(retiredSessionId), roomId: 'board', retired: true, retiredAt: T0 - 1000, rotatedTo: liveHostId }
    ]
    const driveTick = async (alerts) => {
      await runHealthDaemonTick({
        now: () => T0 + 2000,
        stateDir,
        bootId: 'boot-bugA-cross',
        hosts: hostList(),
        posts: [],
        notifyHost: async (hostEntry, frame) => { alerts.push({ hostEntry, frame }) },
        logger: { warn: () => {} }
      })
    }
    const assertNoRetiredAlert = (alerts, bootLabel) => {
      const retiredFrames = alerts.filter((a) => a.frame.includes(`post-error: ${retiredHostId}`))
      assert.equal(retiredFrames.length, 0, `${bootLabel}: the daemon NEVER sends a retired-host post-error finding to the host (Bug A)`)
      assert.ok(alerts.every((a) => a.hostEntry.hostId === liveHostId || a.hostEntry.retired !== true), `${bootLabel}: every alert targets the LIVE host, never a terminal retired host`)
    }

    // Boot 1 — the plugin BOOTS with the retired host present (the loader restores it).
    let env = await bootPlugin(stateDir)
    try {
      await waitFor(() => env.agents.store.has('head-research-head'), 5000, 'head materialized at boot 1')
      // The loader restored BOTH entries from hosts.json (live + retired intact).
      const hostsFile = await readHosts(stateDir)
      assert.ok(hostsFile[liveHostId]?.sessionId !== undefined, 'boot 1: the LIVE host is loaded from hosts.json')
      assert.equal(hostsFile[retiredHostId].retired, true, 'boot 1: the RETIRED host marker survived the boot (terminal evidence kept)')
      // scanPostErrorFindings with the retired-host set threaded in skips the row.
      const retiredSet = new Set(hostList().filter((h) => h.retired === true).map((h) => h.hostId))
      assert.ok(!scanPostErrorFindings(stateDir, T0 + 10_000, retiredSet).some((f) => f.postId === retiredHostId), 'boot 1: scanPostErrorFindings (retired set) skips the retired-host row')
      // A full tick → NO alert for the retired host (Bug A defense-in-depth).
      const alerts1 = []
      await driveTick(alerts1)
      assertNoRetiredAlert(alerts1, 'boot 1')
    } finally {
      await env.dispose()
    }

    // Boot 2 — RE-boot + re-scan: the retired-host post-error row PERSISTS on
    // disk and STILL never alerts over a second, fresh process.
    env = await bootPlugin(stateDir)
    try {
      await waitFor(() => env.agents.store.has('head-research-head'), 5000, 'head materialized at boot 2')
      const hostsFile = await readHosts(stateDir)
      assert.equal(hostsFile[retiredHostId].retired, true, 'boot 2: the RETIRED host marker survives a re-boot')
      assert.equal(readPostErrorsFile(stateDir).some((r) => r.postId === retiredHostId), true, 'boot 2: the retired-host post-error row is STILL on disk (persisted across the boot)')
      const alerts2 = []
      await driveTick(alerts2)
      assertNoRetiredAlert(alerts2, 'boot 2')
    } finally {
      await env.dispose()
    }
  })
})

test('Bug A SOURCE GATE (no over-suppression, write seam): a NON-retired host with a PERSISTENT "session not found" delivery STILL appends its post-error ROW at the busDeliverToHost write — the source gate re-validates the durable hosts registry and never suppresses a legitimate post-error for a live host', async () => {
  await withTempStateDir(async (stateDir) => {
    const liveSessionId = 'host-buga-sourcegate-live'
    const liveHostId = await seedHostRegistration(stateDir, liveSessionId)
    const { head, headCtx, key, dispose } = await bootWithHead(stateDir, { resumeNotFound: [liveSessionId] })
    try {
      const signal = new AbortController().signal
      const send = await headCtx.tools.get('send_message', key).execute(
        { to: [liveHostId], text: 'persistent wake' },
        { agent: head, signal }
      )
      assert.equal(send.delivered[liveHostId], 'failed', 'a persistent session-not-found host delivery reports failed')
      // The busDeliverToHost catch re-validates against the durable registry:
      // the host is NOT retired, so `(hosts.get()?.retired ?? hostEntry.retired)
      // === true` is FALSE → the source gate does NOT suppress the write.
      const rows = readPostErrorsFile(stateDir).filter((r) => r.postId === liveHostId)
      assert.equal(rows.length, 1, 'the NON-retired host STILL gets its legitimate post-error ROW (the source gate does NOT over-suppress a live host)')
      assert.match(rows[0].error, /session "host-buga-sourcegate-live" not found/, 'the recorded error is the not-found class')
    } finally {
      await dispose()
    }
  })
})

test('Bug A SOURCE GATE (retired-host ZERO new ROWS + ZERO QD directives, write seam): a host that is RETIRED in the DURABLE hosts registry NEVER gets a new post-error ROW for a bus delivery and NEVER emits a quality-inspect directive — the source gate suppresses the ROW at the write (the scan gate only suppresses the FINDING; this suppresses the ROW)', async () => {
  await withTempStateDir(async (stateDir) => {
    process.env[QUALITY_INSPECT_ENV_VAR] = '1' // force the QD dice so the emit WOULD fire if a row were written
    try {
      // Seed the durable hosts registry BEFORE boot: a RETIRED host (terminal,
      // the 17:08 noise source) + a LIVE host (the rotation successor the daemon
      // actually alerts). The loader restores both into the in-memory `hosts`
      // Map that busDeliverToHost's source gate re-validates against.
      const retiredSessionId = 'host-buga-retired'
      const liveSessionId = 'host-buga-live'
      const retiredHostId = `host-${retiredSessionId}`
      const liveHostId = `host-${liveSessionId}`
      await writeFile(path.join(stateDir, 'hosts.json'), JSON.stringify({
        schemaVersion: 2,
        [liveHostId]: { sessionId: liveSessionId, roomId: 'board' },
        [retiredHostId]: { sessionId: retiredSessionId, roomId: 'board', retired: true, retiredAt: Date.now() - 1000, rotatedTo: liveHostId }
      }, null, 2))

      const env = await bootWithQD(stateDir, { health: { intervalMs: 50 }, resumeNotFound: [liveSessionId] })
      try {
        // A legacy post-error ROW for the retired host (the 17:08 deploy noise)
        // + a FRESH post-error ROW for a worker post so the daemon tick has a
        // net-new finding to alert the LIVE host about.
        await appendPostError(stateDir, { ts: Date.now() - 60_000, postId: retiredHostId, messageId: 'm-legacy-retired', error: `session "${retiredSessionId}" not found` })
        await appendPostError(stateDir, { ts: Date.now(), postId: 'worker-research', messageId: 'm-fresh', error: 'could not be materialized' })

        const { head, headCtx, key } = qdResearchHead(env)

        // (a) The production system-health daemon (real notifyHost →
        // busDeliverToHost, health.intervalMs) delivers a net-new finding ALERT
        // to the LIVE host; the LIVE host's resume throws (resumeNotFound) so
        // the busDeliverToHost catch WRITES a post-error ROW for the LIVE host.
        // This proves the write seam is live and the source gate does NOT
        // over-suppress it.
        await waitFor(async () => {
          return readPostErrorsFile(stateDir).some((r) => r.postId === liveHostId)
        }, 5000, 'the daemon recorded the LIVE host post-error (real notifyHost → busDeliverToHost catch → dedupe append)')
        assert.equal(readPostErrorsFile(stateDir).filter((r) => r.postId === liveHostId).length, 1, 'the LIVE host gets exactly one post-error ROW (no over-suppression at the write seam)')

        // The RETIRED host must NEVER be the daemon's alert target (retiredHostIds
        // scan skip + pickLiveHostEntry retired skip) and must have ZERO NEW
        // post-error ROWS: the ONLY retired-host row is the untouched legacy seed.
        const retiredRows = readPostErrorsFile(stateDir).filter((r) => r.postId === retiredHostId)
        assert.equal(retiredRows.length, 1, 'the ONLY retired-host row is the seeded legacy row (ZERO NEW rows written)')
        assert.equal(retiredRows[0].messageId, 'm-legacy-retired', 'the legacy retired-host row is the untouched seed (no NEW write)')

        // (b) A direct bus delivery to the RETIRED host via the REAL send_message
        // seam → the catalog/entry gate refuses it (a retired host is terminal),
        // so it reports failed AND appends ZERO new ROWS + ZERO QD directives.
        const before = readPostErrorsFile(stateDir).filter((r) => r.postId === retiredHostId).length
        const signal = new AbortController().signal
        const sendRetired = await headCtx.tools.get('send_message', key).execute(
          { to: [retiredHostId], text: 'wake the retired host' },
          { agent: head, signal }
        )
        assert.equal(sendRetired.delivered[retiredHostId], 'failed', 'a delivery to a durable-RETIRED host reports failed')
        const after = readPostErrorsFile(stateDir).filter((r) => r.postId === retiredHostId).length
        assert.equal(after, before, 'the RETIRED host got ZERO NEW post-error ROWs (the source gate suppresses the write)')
        await waitFor(async () => {
          return readPostErrorsFile(stateDir).filter((r) => r.postId === retiredHostId).length === before
        }, 5000, 'retired-host row count is stable after the delivery attempt')
        // No QD quality-inspect directive addressed to quality-head for the
        // retired host (a suppressed write never reaches the maybeEmitQualityInspectDirective emit).
        const dirs = await qualityDirectives(stateDir)
        assert.equal(dirs.filter((d) => /post-error.*post host-buga-retired/.test(d.text)).length, 0, 'NO quality-inspect directive is emitted for the RETIRED host')
      } finally {
        await env.dispose()
      }
    } finally {
      delete process.env[QUALITY_INSPECT_ENV_VAR]
    }
  })
})

test('Bug A DURABLE GATE (STALE in-memory registry, real Loader): a host that is RETIRED in the DURABLE hosts.json but STALE-LIVE in the boot-time IN-MEMORY registry (a second daemon twin that booted BEFORE the rotation, sharing the stateDir) appends ZERO new post-error ROWs and ZERO QD directives for a bus delivery whose materialize CALL throws "session not found" — the on-disk hosts.json re-validation closes the stale-twin bypass that the in-memory source gate + scan gate both miss', async () => {
  await withTempStateDir(async (stateDir) => {
    process.env[QUALITY_INSPECT_ENV_VAR] = '1' // force the QD dice so the emit WOULD fire if a row were written
    try {
      const hostSessionId = 'host-buga-durable-stale'
      const hostId = `host-${hostSessionId}`
      // (i) Seed hosts.json BEFORE boot with the host as LIVE — this is the "twin"
      // that boots pre-rotation and caches the host as live in its in-memory Map.
      await writeFile(path.join(stateDir, 'hosts.json'), JSON.stringify({
        schemaVersion: 2,
        [hostId]: { sessionId: hostSessionId, roomId: 'board' }
      }, null, 2))

      const env = await bootWithQD(stateDir, { health: { enabled: false }, resumeNotFound: [hostSessionId] })
      try {
        // Boot restored the host into the in-memory registry as LIVE. NOW the
        // rotation commits: overwrite hosts.json ON DISK to mark it RETIRED —
        // WITHOUT rebooting, so the in-memory registry stays STALE-LIVE (the
        // process never re-reads hosts.json, exactly the real stale-twin).
        await writeFile(path.join(stateDir, 'hosts.json'), JSON.stringify({
          schemaVersion: 2,
          [hostId]: { sessionId: hostSessionId, roomId: 'board', retired: true, retiredAt: Date.now() - 1000, rotatedTo: 'host-session-rotated' }
        }, null, 2))
        const hostsFile = await readHosts(stateDir)
        assert.equal(hostsFile[hostId].retired, true, 'the DURABLE hosts.json now marks the host retired (the authoritative rotation record)')

        const { head, headCtx, key } = qdResearchHead(env)
        const before = readPostErrorsFile(stateDir).filter((r) => r.postId === hostId).length
        const signal = new AbortController().signal

        // (ii) Drive the busDeliverToHost CATCH: a delivery to the host. The
        // addressing/catalog gate reads the STALE in-memory registry (host is
        // LIVE there) so it is NOT refused — the delivery reaches busDeliverToHost,
        // agents.resume throws "session not found", and the catch runs.
        const send = await headCtx.tools.get('send_message', key).execute(
          { to: [hostId], text: 'wake the stale-live twin' },
          { agent: head, signal }
        )
        assert.equal(send.delivered[hostId], 'failed', 'the delivery reports failed')
        // The in-memory registry was stale-live, so busDeliverToHost DID attempt the
        // host resume (proving the catch was reached) — the durable gate alone is what
        // stops the ROW.
        assert.equal(env.agents.resumeCalls.some((c) => String(c.resumeSessionId) === hostSessionId), true, 'busDeliverToHost attempted the host resume (the in-memory registry is stale-live, so the addressing gate passed and the catch ran)')

        // (iii) ZERO new post-error ROWs for the retired host — the DURABLE
        // hosts.json gate sees it retired even though the in-memory registry says live.
        await waitFor(async () => {
          return readPostErrorsFile(stateDir).filter((r) => r.postId === hostId).length === before
        }, 5000, 'retired-host (stale in-memory) row count is stable')
        const staleRows = readPostErrorsFile(stateDir).filter((r) => r.postId === hostId)
        assert.equal(staleRows.length, before, `the STALE-in-memory but DURABLY-retired host appends ZERO NEW post-error ROWs (${before} before → ${staleRows.length} after)`)
        // No QD quality-inspect directive addressed to quality-head for it.
        const dirs = await qualityDirectives(stateDir)
        assert.equal(dirs.filter((d) => /post-error.*post host-buga-durable-stale/.test(d.text)).length, 0, 'NO quality-inspect directive is emitted for the DURABLY-retired host')
      } finally {
        await env.dispose()
      }
    } finally {
      delete process.env[QUALITY_INSPECT_ENV_VAR]
    }
  })
})

test('HEALTH ALERT RECIPIENT (durable rotation chain beats a STALE in-memory registry): a daemon whose in-memory `deps.hosts` is STALE — host A still LIVE with no rotation knowledge (a long-lived/twin daemon that booted BEFORE the 12:30 rotation) — resolves the ALERT recipient DURABLE-FIRST from hosts.json, where host A is retired:true (rotatedTo B) + host B is the live successor (previousSessionId = A). notifyHost receives the alert addressed to B, and NOTHING is addressed to A (no alert / no re-alert row for the retired host)', async () => {
  await withTempStateDir(async (stateDir) => {
    const T0 = new Date(2026, 7, 24, 12, 30, 0).getTime() // fixed epoch (post-rotation)
    const sessionA = 'host-session-a'
    const sessionB = 'host-session-b'
    const hostA = `host-${sessionA}`
    const hostB = `host-${sessionB}`
    // (i) The DURABLE hosts.json — the truthful rotation record: host A RETIRED
    // (rotatedTo B) + host B LIVE (the successor, previousSessionId = A). This is
    // the state the rotation committed ON DISK AFTER the daemon already booted
    // (the daemon's boot-time in-memory registry never re-reads it).
    await writeFile(path.join(stateDir, 'hosts.json'), JSON.stringify({
      schemaVersion: 2,
      [hostA]: { sessionId: sessionA, roomId: 'board', retired: true, retiredAt: T0 - 1000, rotatedTo: hostB },
      [hostB]: { sessionId: sessionB, roomId: 'board', previousSessionId: sessionA }
    }, null, 2))
    // readDurableHostEntries must PRESERVE the rotation-chain metadata the Bug A
    // `readDurableHostsRegistry` (a `{hostId:{retired}}` map) discards, so the
    // successor detection in the follow-up pickLiveHostEntry works.
    const durableEntries = readDurableHostEntries(stateDir)
    assert.ok(durableEntries !== undefined, 'the durable hosts.json is read fresh')
    const durableB = durableEntries?.find((e) => e.hostId === hostB)
    const durableA = durableEntries?.find((e) => e.hostId === hostA)
    assert.equal(durableB?.previousSessionId, sessionA, 'the live successor entry preserves previousSessionId (rotate-from) on the durable read')
    assert.equal(durableA?.retired, true, 'the retired entry preserves retired:true on the durable read')
    assert.equal(durableA?.rotatedTo, hostB, 'the retired entry preserves rotatedTo on the durable read')
    // (ii) A net-new finding for the daemon to alert about.
    await writeFile(path.join(stateDir, 'post-errors.jsonl'), JSON.stringify({ ts: T0 - 60_000, postId: 'worker-w', messageId: 'm-1', error: 'could not be materialized' }) + '\n', 'utf8')
    const alerts = []
    const warns = []
    // (iii) The STALE in-memory registry: host A LIVE only (the twin booted pre-
    // rotation; it has NO knowledge that A is retired or that B exists).
    const staleInMemoryHosts = [{ hostId: hostA, sessionId: sessionA, roomId: 'board' }]
    assert.equal(pickLiveHostEntry(staleInMemoryHosts).live?.hostId, hostA, 'sanity: the stale in-memory registry ALONE resolves the recipient to host A (the pre-fix behavior this regression guards)')
    // (iv) Run the tick with the stale in-memory registry; the durable file is the
    // truth the recipient must resolve from.
    await runHealthDaemonTick({
      now: () => T0,
      stateDir,
      bootId: 'boot-recipient',
      hosts: staleInMemoryHosts,
      posts: [],
      notifyHost: async (hostEntry, frame) => { alerts.push({ hostEntry, frame }) },
      logger: { warn: (m) => warns.push(m) }
    })
    // (v) The alert is addressed to the DURABLE live successor (host B), NOT A.
    assert.equal(alerts.length, 1, 'one alert fires for the net-new finding')
    assert.equal(alerts[0].hostEntry.hostId, hostB, 'the alert targets the DURABLE live successor (host B), NOT the stale in-memory host A')
    assert.notEqual(alerts[0].hostEntry.hostId, hostA, 'the alert is NOT addressed to the retired host A')
    assert.match(alerts[0].frame, /^\[From deepartments\] System-health ALERT:/, 'the alert is framed correctly')
    assert.match(alerts[0].frame, /post-error: worker-w/, 'the alert names the finding')
    // (vi) The finding is deduped at now (delivered once); NOTHING ever targets A.
    const state = readHealthAlertsState(stateDir)
    assert.equal(state[`post-error:worker-w:${errorIdentityHash('could not be materialized')}`], T0, 'the finding is deduped at now')
    assert.equal(alerts.every((a) => a.hostEntry.hostId !== hostA), true, 'NO alert is ever addressed to host A')
    assert.equal(warns.length, 0, 'a fully-resolvable tick emits no warns')
  })
})

test('P2 Bug C: an ALREADY-delivered post-error identity is NEVER re-alerted (no per-window re-fire); a NEW postId (a new error identity) alerts', async () => {
  await withTempStateDir(async (stateDir) => {
    const T0 = new Date(2026, 7, 24, 12, 0, 0).getTime()
    const hosts = [{ hostId: 'host-asst', sessionId: 's-live', roomId: 'board' }]
    const alerts = []
    const tick = (nowMs) => runHealthDaemonTick({
      now: () => nowMs, stateDir, bootId: 'boot-bugC',
      hosts,
      notifyHost: async (hostEntry, frame) => { alerts.push({ hostEntry, frame }) },
      logger: { warn: () => {} }
    })
    // A post-error row for worker-a (error 'boom').
    await appendPostError(stateDir, { ts: T0, postId: 'worker-a', messageId: 'm-1', error: 'boom' }, T0)
    await tick(T0)
    assert.equal(alerts.length, 1, 'the FIRST error identity alerts')
    assert.match(alerts[0].frame, /post-error: worker-a/, 'the alert names the post')
    // A RE-CURRENCE of the SAME error identity (new row, fresh ts) inside the
    // 2h window → NOT a new alert (Bug C: a delivered identity never re-alerts).
    await appendPostError(stateDir, { ts: T0 + 10 * 60000, postId: 'worker-a', messageId: 'm-1b', error: 'boom' }, T0 + 10 * 60000)
    await tick(T0 + 10 * 60000)
    assert.equal(alerts.length, 1, 'a re-current SAME error identity is NOT re-alerted')
    // After the 30min window elapses the identity is STILL delivered → NOT re-alerted.
    await tick(T0 + 31 * 60000)
    assert.equal(alerts.length, 1, 'the SAME error identity is NEVER re-alerted even after the dedupe window (Bug C)')
    // A NEW postId (a genuinely NEW error identity) → alerts immediately.
    await appendPostError(stateDir, { ts: T0 + 32 * 60000, postId: 'worker-b', messageId: 'm-2', error: 'a new error' }, T0 + 32 * 60000)
    await tick(T0 + 32 * 60000)
    assert.equal(alerts.length, 2, 'a NEW postId (a new error identity) alerts immediately')
    assert.match(alerts.at(-1).frame, /post-error: worker-b/, 'the new-alert names the new postId')
  })
})

test('P2 LATENT FIX: the daemon tick does NOT drop the conditional system-wait when the ALERT path ALSO fires in the SAME tick (deps.hosts is materialized ONCE — no exhausted single-use iterator)', async () => {
  await withTempStateDir(async (stateDir) => {
    const T0 = new Date(2026, 7, 24, 12, 0, 0).getTime()
    await appendPostError(stateDir, { ts: T0, postId: 'worker-a', messageId: 'm-1', error: 'boom' }, T0)
    const hosts = [{ hostId: 'host-asst', sessionId: 's-live', roomId: 'board' }]
    const frames = []
    // A quiet host expectation (a host-sent message without a reply/resources).
    const waitPost = { postId: 'worker-b', retired: false, events: [], hostMessages: [{ messageId: 'm-2', ts: T0 - 40 * 60000 }] }
    await runHealthDaemonTick({
      now: () => T0, stateDir, bootId: 'boot-latent',
      config: { stateDir, org: { departments: [] } },
      hosts,
      hostWaits: [waitPost],
      posts: [],
      notifyHost: async (hostEntry, frame) => { frames.push(frame) },
      logger: { warn: () => {} }
    })
    // BOTH the ALERT (post-error) AND the WAIT (system-wait) deliver in ONE tick —
    // before the fix the WAIT path read an EXHAUSTED deps.hosts iterator (the ALERT
    // path consumed it) → live was undefined → the wake was silently dropped.
    assert.equal(frames.filter((f) => f.includes('System-health ALERT')).length, 1, 'the ALERT path is delivered')
    assert.equal(frames.filter((f) => f.includes('system-wait: worker-b')).length, 1, 'the CONDITIONAL WAIT wake is delivered in the SAME tick (not dropped by an exhausted host iterator)')
    assert.equal(frames.length, 2, 'both the ALERT + the WAIT wake are delivered')
  })
})

