test('QD echo guard (cross-check 5): a failing bus delivery to the QD target (postId === "quality-head") emits NO post-error directive, while a non-QD target still emits exactly one', async () => {
  // The reviewer gate (cross-check 5): a post-error directive whose OWN delivery
  // to `quality-head` fails lands in THIS SAME catch. If we re-emitted a
  // post-error for it, the directive → busDeliverToPost(quality-head) → fail →
  // re-append → re-emit loop would be unbounded. The guard gates the emit on
  // `entry.postId !== 'quality-head'` so the QD target's OWN delivery failure is
  // recorded (post-errors.jsonl) but NEVER bubbled back into another directive.
  // Scenario (a): the QD target itself fails → NO post-error directive is emitted.
  await withTempStateDir(async (stateDir) => {
    // An org WITHOUT a quality coordinator: `quality-head` is ONLY the seeded,
    // non-materialized post, so its bus delivery fails cleanly into the catch
    // block AND `byPost.get('quality-head')` is still a valid directive target
    // (un-guarded the emit would fire and echo).
    await seedPost(stateDir, { postId: 'quality-head', sessionId: 'head-quality-head', roomId: 'board', agentPreset: 'deepartments-head' })
    const env = await bootPlugin(stateDir, { resumeRejects: ['head-quality-head'], createRejects: ['head-quality-head'] })
    try {
      const host = env.agents.put(fakeParentAgent())
      const signal = new AbortController().signal
      const send = env.pluginCtx().tools.get('send_message')
      const result = await send.execute({ to: ['quality-head'], text: 'wake the unwakeable QD target' }, { agent: host, signal })
      assert.equal(result.delivered['quality-head'], 'failed', 'a dual-fail materialization of the QD target reports failed')
      // The failure IS a real post-error record (the echo is not silently dropped).
      const errors = readPostErrorsFile(stateDir)
      assert.equal(errors.length, 1, 'the QD target failure is RECORDED in post-errors.jsonl')
      assert.equal(errors[0].postId, 'quality-head', 'the post-error carries the failed QD target postId')
      // But the QD target's OWN failure must NOT re-signal a directive (bounded).
      const dirs = await qualityDirectives(stateDir)
      assert.equal(dirs.filter((d) => /post-error/.test(d.text)).length, 0, 'the QD target failure emits NO post-error directive (echo guard)')
    } finally {
      await env.dispose()
    }
  })
  // Scenario (b): a non-QD target's failure still emits exactly ONE post-error
  // directive to quality-head (the guard is scoped to the QD target only).
  await withTempStateDir(async (stateDir) => {
    await seedPost(stateDir, { postId: 'ghost-head', sessionId: 'head-ghost-head', roomId: 'board', agentPreset: 'deepartments-head' })
    const env = await bootWithQD(stateDir, { resumeRejects: ['head-ghost-head'], createRejects: ['head-ghost-head'] })
    try {
      const host = env.agents.put(fakeParentAgent())
      const signal = new AbortController().signal
      const send = env.pluginCtx().tools.get('send_message')
      const result = await send.execute({ to: ['ghost-head'], text: 'wake the unwakeable' }, { agent: host, signal })
      assert.equal(result.delivered['ghost-head'], 'failed', 'a dual-fail materialization reports failed')
      const dirs = await qualityDirectives(stateDir)
      const errorDirs = dirs.filter((d) => /post-error/.test(d.text))
      assert.equal(errorDirs.length, 1, 'a non-QD failure still emits exactly ONE post-error directive')
      assert.match(errorDirs[0].text, /post ghost-head/, 'the directive names the failed postId')
    } finally {
      await env.dispose()
    }
  })
})

test('QD non-fatal: a failing directive emit (store.append rejects) still commits the retire', async () => {
  await withTempStateDir(async (stateDir) => {
    process.env[QUALITY_INSPECT_ENV_VAR] = '1' // force the worker dice true so the emit runs
    try {
      const env = await bootWithQD(stateDir)
      try {
        const signal = new AbortController().signal
        const { head, headCtx, key } = qdResearchHead(env)
        const spawned = await f3Spawn(env, headCtx, key, head, { role: 'researcher', task: 'qd non-fatal' })
        const sid = spawned.result.sessionId
        // Force the directive emit to FAIL: make the messages file path a DIRECTORY
        // so `store.append` (the durable flush) rejects inside the emit; the emit's
        // own try/catch must swallow it and the retire must still commit.
        await rm(path.join(stateDir, 'messages.jsonl'), { force: true })
        await mkdir(path.join(stateDir, 'messages.jsonl'))
        const result = await headCtx.tools.get('dept_worker_retire', key).execute({ workerId: spawned.result.workerId }, { agent: head, signal })
        assert.equal(result.retired, true, 'the retire mark still commits (the failing emit never breaks the seam)')
        assert.equal(result.archived, true, 'the archive still runs (the failing emit is non-fatal)')
        await waitFor(() => env.workspaceRegistry.archivedSessionIds.includes(sid), 5000, 'the worker session archived despite the failing emit')
        // Restore a readable messages path so the directive read is ENOENT→[].
        await rm(path.join(stateDir, 'messages.jsonl'), { recursive: true, force: true })
        const dirs = await qualityDirectives(stateDir)
        assert.equal(dirs.filter((d) => /worker retired/.test(d.text)).length, 0, 'no directive was recorded (store.append rejected → caught → warn)')
      } finally {
        await env.dispose()
      }
    } finally {
      delete process.env[QUALITY_INSPECT_ENV_VAR]
    }
  })
})

// --- HOST-side first-wake fix (2026-08-24) config guard ----------------------
//
// The host (Asistente) session is NOT created by the plugin, so a plugin-only
// real-Loader test cannot reproduce the CORE first-wake assembly failure (the
// plugin's heads/workers hard-code WORKER_AGENT_OPTIONS / coordinator.agentOptions
// and are already immune). The primary host-side regression guard is a CONFIG
// test: it reads the repo's OWN bundled patch (operator-owned — "bundles →
// profile → $DSH_HOME → --patch, last wins per row") and asserts the two
// override rows that neutralize the CORE default deployment persona's unbound
// model variable (dsh-web-app/cordis.patch.yml system-prompt persona references
// the model variable, unbound at the first post-restart wake because the async
// model-selection/settings source is not yet loaded). If these rows regress the
// config back to the unbound model variable, the test fails.

/** Read the repo's bundled cordis.patch.yml (the operator-owned bundle patch). */
function readBundlePatchText() {
  return readFile(new URL('../cordis.patch.yml', import.meta.url), 'utf8')
}

/** Split a cordis patch text into its TOP-LEVEL entries. A top-level list item
 * starts with `- ` at column 0; nested entries under `insert:` are indented, so
 * the per-entry id is matched only at the entry root. Returns the entries that
 * declare an `id:` at their root, as {id, block}. */
function topLevelPatchEntries(text) {
  const entries = []
  let cur = null
  for (const line of text.split('\n')) {
    if (/^- /.test(line)) {
      cur = [line]
      entries.push(cur)
    } else if (cur) {
      cur.push(line)
    }
  }
  const out = []
  for (const blockLines of entries) {
    const block = blockLines.join('\n')
    const idMatch = block.match(/^- id:\s*(\S+)/m)
    if (idMatch) out.push({ id: idMatch[1], block })
  }
  return out
}

test('HOST-SIDE FIRST-WAKE FIX config guard: the bundled patch overrides the CORE default deployment persona to a literal model (no unbound model variable) and pins an explicit default model — guard against regressing the config back to the unbound {{model}} token', async () => {
  const text = await readBundlePatchText()
  const entries = topLevelPatchEntries(text)
  const sp = entries.find((e) => e.id === 'system-prompt')
  const adm = entries.find((e) => e.id === 'agent-default-model')

  assert.ok(sp, 'a top-level `- id: system-prompt` override row exists in the bundled patch')
  assert.ok(adm, 'a top-level `- id: agent-default-model` override row exists in the bundled patch')

  // (a) The default deployment persona MUST be a literal model — never the
  // unbound model variable (nor the broken-brace rendering). This is the
  // assembly-failure surface: at the first post-restart wake the model selection
  // is empty, so the CORE persona's model variable throws "has no value".
  assert.ok(sp.block.includes('persona:'), 'the system-prompt row carries a persona')
  assert.ok(!sp.block.includes('{{model}}'), 'the system-prompt persona does NOT reference the unbound {{model}} variable')
  assert.ok(!sp.block.includes('{ {model}}'), 'the system-prompt persona does NOT reference the broken-brace { {model}} rendering')
  assert.ok(sp.block.includes('deepseek-v4-flash'), 'the system-prompt persona names the literal model')
  assert.ok(sp.block.includes('{{cwd}}'), 'the system-prompt persona references the bound working-directory var {{cwd}}')

  // (b) The default model MUST be pinned explicitly (provider + model both set),
  // so the host's agent.options.model/provider are NEVER empty before the
  // settings document loads (a base default behind a loaded-but-empty settings
  // section would otherwise be emptied).
  assert.ok(adm.block.includes('provider: opencode-zen'), 'the agent-default-model row pins provider opencode-zen')
  assert.ok(adm.block.includes('model: deepseek-v4-flash'), 'the agent-default-model row pins model deepseek-v4-flash')
})

test('HOST-SIDE FIRST-WAKE FIX real-Loader regression: the plugin materializes its own heads/workers with a MODEL-BOUND session (provider + model never empty) — the plugin side must never regress to an unbound model', async () => {
  await withTempStateDir(async (stateDir) => {
    const { agents, head, headCtx, key, dispose } = await bootWithHead(stateDir)
    try {
      // The booted head is materialized with an explicit provider + model.
      const headCall = agents.createCalls.find((c) => String(c.sessionId) === 'head-research-head')
      assert.ok(headCall, 'the head is materialized via ctx.agents.create at boot')
      assert.ok(headCall.agentOptions, 'the head create carries agentOptions')
      assert.ok(typeof headCall.agentOptions.provider === 'string' && headCall.agentOptions.provider.length > 0, 'the head provider is non-empty')
      assert.ok(typeof headCall.agentOptions.model === 'string' && headCall.agentOptions.model.length > 0, 'the head model is non-empty')

      // A spawned worker is materialized with an explicit provider + model too.
      const { result } = await f3Spawn({ agents }, headCtx, key, head, { role: 'researcher', task: 'model-bound regression' })
      const workerCall = agents.createCalls.find((c) => String(c.sessionId) === result.sessionId)
      assert.ok(workerCall, 'the spawned worker is materialized via ctx.agents.create')
      assert.ok(workerCall.agentOptions, 'the worker create carries agentOptions')
      assert.ok(typeof workerCall.agentOptions.provider === 'string' && workerCall.agentOptions.provider.length > 0, 'the worker provider is non-empty')
      assert.ok(typeof workerCall.agentOptions.model === 'string' && workerCall.agentOptions.model.length > 0, 'the worker model is non-empty')
    } finally {
      await dispose()
    }
  })
})

